// ============================================================================
// ≡ƒôª App Shell Container (App.tsx)
// ============================================================================
// Low-level mechanics: 
// 1. Coordinates page state layout dynamically based on Zustand store settings.
// 2. Applies global dynamic CSS style overrides (appStyle/backgroundStyle) at the body root.
// 3. Performs lazy-loading fallback boundaries (Suspense) for large components.
// ============================================================================

import { AnimatePresence, MotionConfig } from 'motion/react'; // Handles exit transitions: keeps components in the DOM until their fade/slide animations finish.
import { Settings } from 'lucide-react'; // Lucide SVG icon definition for the gear button.
import React, { Suspense } from 'react'; // React default + Suspense for lazy imports.
import { DockedLayout } from './components/layout/DockedLayout'; // Workspace structure defining Left, Center, and Right panels.
import { IconButton } from './components/common/IconButton'; // Standardized accessible button component with hover glow effects.
import { ParticleOverlay } from './components/ParticleOverlay'; // Canvas element rendering floating background canvas shapes.
import { CesiumBackground } from './components/background/CesiumBackground'; // Virtual Earth component rendered on a persistent background layer.
import WorldWideTelescopeView from './components/learning/WorldWideTelescopeView';
import { LauncherPage } from './components/launcher/LauncherPage'; // Welcome/Splash component shown when first loading the interface.
import { SettingsPage } from './components/settings/SettingsPage'; // Configuration panel (lazy loaded to reduce initial bundle size).
import { ErrorBoundary } from './components/ErrorBoundary'; // React error boundary: catches runtime crashes inside nested components without freezing the tab.
import { CustomCursor } from './components/layout/CustomCursor'; // Custom pointer element that tracks client mouse moves.
import { useThemeVariables } from './hooks/useThemeVariables'; // Computes current palette style objects and monitors CPU strain.
import { useUIStore } from './store/uiStore'; // Shared state manager (Zustand) tracking navigation and user preferences.
import { ConfigProvider } from './context/ConfigContext';
import { useDiagnosticsStore } from './store/diagnosticsStore';
import { useKeyboardShortcuts } from './hooks/useKeyboardShortcuts';

// Dev-only harness: lazy-load to avoid impacting production bundles
const MountUnmountHarness = React.lazy(() => import('./components/dev/MountUnmountHarness'));
const DiagnosticPanel = React.lazy(() => import('./components/dev/DiagnosticPanel'));

// ----------------------------------------------------------------------------
// ≡ƒÅ╖∩╕Å Top Navigation Bar
// ----------------------------------------------------------------------------
function TopAppBar() {
  // Read target page states from the Zustand memory store to set toggled visibility.
  const currentPage = useUIStore((state) => state.currentPage);
  const setCurrentPage = useUIStore((state) => state.setCurrentPage);

  return (
    // Uses absolute positioning to stay at the top and z-index 20 to sit above background map canvas.
    <div className="absolute left-0 top-0 z-20 flex h-12 w-full items-center justify-between border-b border-panel-border bg-panel/50 px-4 panel-glass">
      <div className="flex items-center gap-3 font-mono text-xs font-bold uppercase tracking-widest text-primary">
        {/* Glow indicator: styled using a box shadow colored by the primary theme variable */}
        <span className="h-2 w-2 rounded-full bg-primary shadow-[0_0_8px_var(--theme-primary)]" />
        <span className="glitch-target hover-glitch cursor-pointer" data-text="Silver Wolf VI">Silver Wolf VI</span>
      </div>
      {/* settings icon: clicking updates Zustand page string, triggering main App page re-render */}
      <IconButton
        icon={Settings}
        label={currentPage === 'settings' ? 'Close settings' : 'Open settings'}
        onClick={() => setCurrentPage(currentPage === 'settings' ? 'workspace' : 'settings')}
      />
    </div>
  );
}

// ----------------------------------------------------------------------------
// ≡ƒææ Core Application Entrypoint
// ----------------------------------------------------------------------------
export default function App() {
  useKeyboardShortcuts();
  // Subscription selectors: only trigger re-renders when these specific properties change in the Zustand store.
  const currentPage = useUIStore((state) => state.currentPage);
  const interactionMode = useUIStore((state) => state.interactionMode);
  const customWallpaper = useUIStore((state) => state.customWallpaper);
  const scanlineOverlay = useUIStore((state) => state.scanlineOverlay);
  const spaceBlendOpacity = useUIStore((state) => state.spaceBlendOpacity);
  const spaceInteractionTarget = useUIStore((state) => state.spaceInteractionTarget);

  // Detect if running in headless test/fallback mode
  const isHeadless = typeof window !== 'undefined' && (
    /HeadlessChrome/i.test(navigator.userAgent) ||
    navigator.webdriver ||
    window.location.search.includes('fallback')
  );

  // Dev harness toggle: append `?mountharness` to the URL to open the mount/unmount harness
  const showHarness = typeof window !== 'undefined' && window.location.search.includes('mountharness');
  const showDiagnostics = typeof window !== 'undefined' && window.location.search.includes('diagnostics');
  const setCurrentPage = useUIStore((state) => state.setCurrentPage);

  // If dev toggles are present, force the app into workspace so overlays render
  React.useEffect(() => {
    try {
      if (showHarness || showDiagnostics) {
        setCurrentPage('workspace');
      }
    } catch (e) {}
  }, [showHarness, showDiagnostics, setCurrentPage]);

  React.useEffect(() => {
    // Report holistic upgrade status to the new diagnostic engine
    useDiagnosticsStore.getState().add({
      level: 'info',
      message: 'Silver Wolf VI Holistic Upgrade Complete.',
      metadata: {
        version: 'v6.2.0-stable',
        diagnosticEngine: 'active',
        bridgeProxy: 'active',
        standardizedTheme: 'active'
      }
    });
  }, []);

  // Destructures computed theme object and the CPU load state.
  const { appStyle, isHighLoad } = useThemeVariables();

  // If a custom image URL exists, build background style overrides.
  const backgroundStyle = customWallpaper
    ? { backgroundImage: `url(${customWallpaper})`, backgroundSize: 'cover', backgroundPosition: 'center' }
    : undefined;

  return (
    <ConfigProvider>
      <MotionConfig reducedMotion={isHeadless ? "always" : "user"}>
      {/* Outer viewport root container. Covers whole screen (h-screen, w-full), disables default scrolls (overflow-hidden). */}
      <div
        className={`relative flex h-screen w-full overflow-hidden bg-base font-sans text-text-main transition-colors duration-500 ${
          isHighLoad ? 'state-high-load' : '' // High load CSS class: throttles expensive SVG/canvas calculations when active.
        } ${isHeadless ? 'is-headless' : ''}`}
        style={{ ...appStyle, ...backgroundStyle }} // Merge global theme CSS variables with optional background image style.
      >
      {/* ≡ƒîì 3D MAP & SPACE BACKGROUND: Layered WWT and Cesium Globe */}
      {!customWallpaper && (
        <div className="absolute inset-0 z-0">
          {/* 1. Telescope Background Layer (WWT) at z-0 */}
          {interactionMode === 'orbital' && (!isHeadless || spaceInteractionTarget === 'telescope') && (
            <div className="absolute inset-0 z-0">
              <WorldWideTelescopeView bgOnly />
            </div>
          )}

          {/* 2. Earth Globe Background Layer (Cesium) at z-10 */}
          <div 
            className="absolute inset-0 transition-all duration-500 ease-in-out"
            style={{
              zIndex: 10,
              opacity: interactionMode === 'orbital' 
                ? (spaceInteractionTarget === 'telescope' ? spaceBlendOpacity : 1.0) 
                : 1.0,
              pointerEvents: interactionMode === 'orbital' && spaceInteractionTarget === 'earth' ? 'auto' : 'none'
            }}
          >
            <CesiumBackground interactive={interactionMode === 'orbital' && spaceInteractionTarget === 'earth'} />
          </div>
        </div>
      )}

      {/* ≡ƒò╢∩╕Å BACKDROP SHADE: Semi-translucent screen layer. Fades the map so chat text contrast remains high. */}
      {interactionMode !== 'orbital' && (
        <div className="absolute inset-0 bg-[#06070a]/75 backdrop-blur-[2px] pointer-events-none z-0" />
      )}

      {/* ≡ƒô║ SCANLINE LAYER: Simulated scanlines using a CSS gradient background scaled to 4px tall repetitions. */}
      {scanlineOverlay && (
        <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.12)_50%)] bg-[size:100%_4px] pointer-events-none z-10" />
      )}

      {/* ROUTING CONTROLLER: Swaps pages by comparing active page string */}
      {currentPage === 'launcher' ? (
        <LauncherPage />
      ) : (
        <>
          {/* Performance Optimization: Turn off floaty dots and custom cursor tracks if CPU is struggling. */}
          {!isHighLoad && <ParticleOverlay />}
          {!isHighLoad && <CustomCursor appHighLoad={isHighLoad} />}

          {/* Cyberpunk flicker screen overlay */}
          {scanlineOverlay && <div className="hologram-overlay" />}

          {interactionMode !== 'orbital' && <TopAppBar />}

          {/* Core viewport layouts: pt-12 leaves space for the 12-unit top app bar, cleared in spatial modes for full-screen floating HUD */}
          <div className={`relative z-10 flex h-full w-full pointer-events-none transition-all duration-300 ${interactionMode === 'orbital' ? 'pt-0' : 'pt-12'}`}>
            <DockedLayout />
          </div>

          {/* Dev harness overlay (rendered when ?mountharness is present) */}
          {showHarness && (
            <Suspense fallback={null}>
              <MountUnmountHarness />
            </Suspense>
          )}

          {/* Dev diagnostics overlay (rendered when ?diagnostics is present) */}
          {showDiagnostics && (
            <Suspense fallback={null}>
              <DiagnosticPanel />
            </Suspense>
          )}

          {/* AnimatePresence monitors settings page component mounting. When currentPage !== 'settings', it plays slide-out fade before removal. */}
          <AnimatePresence>
            {currentPage === 'settings' && (
              // Suspense fallback handles loading state while SettingsPage chunks are downloaded.
              <Suspense fallback={null}>
                <ErrorBoundary>
                  <SettingsPage />
                </ErrorBoundary>
              </Suspense>
            )}
          </AnimatePresence>
        </>
      )}
    </div>
      </MotionConfig>
    </ConfigProvider>
  );
}

import React from 'react';
import { useDiagnosticsStore } from '../store/diagnosticsStore';
import { AlertCircle, AlertTriangle, Info, Bug, Trash2, Download, Terminal } from 'lucide-react';

export function DiagnosticPanel() {
  const { entries, clear, export: exportLogs } = useDiagnosticsStore();

  const handleDownload = () => {
    const data = exportLogs();
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `silver-wolf-diagnostics-${new Date().toISOString()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col h-full font-mono text-[10px]">
      <div className="flex items-center justify-between mb-4 px-1">
        <div className="flex items-center gap-2 text-primary font-bold uppercase tracking-wider">
          <Bug size={14} />
          <span>Diagnostic Engine</span>
        </div>
        <div className="flex gap-2">
          <button
            onClick={handleDownload}
            className="p-1.5 rounded bg-white/5 hover:bg-white/10 text-white/50 hover:text-white transition-colors"
            title="Export Logs"
          >
            <Download size={14} />
          </button>
          <button
            onClick={clear}
            className="p-1.5 rounded bg-white/5 hover:bg-red-500/20 text-white/50 hover:text-red-400 transition-colors"
            title="Clear Logs"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-2 scroller pr-1">
        {entries.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-white/20">
            <Terminal size={32} className="mb-2 opacity-10" />
            <span>NO DIAGNOSTIC EVENTS</span>
          </div>
        ) : (
          entries.map((entry) => (
            <div
              key={entry.id}
              className={`p-3 rounded border bg-black/20 ${
                entry.level === 'error' ? 'border-red-500/30' :
                entry.level === 'warning' ? 'border-yellow-500/30' :
                entry.level === 'info' ? 'border-cyan-500/30' : 'border-white/10'
              }`}
            >
              <div className="flex items-start gap-3">
                <div className="mt-0.5">
                  {entry.level === 'error' && <AlertCircle size={14} className="text-red-400" />}
                  {entry.level === 'warning' && <AlertTriangle size={14} className="text-yellow-400" />}
                  {entry.level === 'info' && <Info size={14} className="text-cyan-400" />}
                  {entry.level === 'debug' && <Bug size={14} className="text-purple-400" />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-2 mb-1">
                    <span className={`font-bold uppercase tracking-tighter ${
                      entry.level === 'error' ? 'text-red-400' :
                      entry.level === 'warning' ? 'text-yellow-400' :
                      entry.level === 'info' ? 'text-cyan-400' : 'text-purple-400'
                    }`}>
                      {entry.level}
                    </span>
                    <span className="text-white/20 tabular-nums">
                      {new Date(entry.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                  <div className="text-white/80 leading-relaxed break-words whitespace-pre-wrap">
                    {entry.message}
                  </div>
                  {entry.suggestion && (
                    <div className="mt-2 p-2 rounded bg-primary/10 border border-primary/20 text-primary-hover">
                      <span className="font-bold mr-1">FIX:</span>
                      {entry.suggestion}
                    </div>
                  )}
                  {entry.metadata && Object.keys(entry.metadata).length > 0 && (
                    <details className="mt-2 group">
                      <summary className="cursor-pointer text-white/30 hover:text-white/50 transition-colors uppercase text-[8px] font-bold tracking-widest outline-none">
                        View Metadata
                      </summary>
                      <pre className="mt-2 p-2 rounded bg-black/40 text-[8px] text-white/50 overflow-x-auto scroller">
                        {JSON.stringify(entry.metadata, null, 2)}
                      </pre>
                    </details>
                  )}
                  {entry.stack && (
                    <details className="mt-1 group">
                      <summary className="cursor-pointer text-white/30 hover:text-white/50 transition-colors uppercase text-[8px] font-bold tracking-widest outline-none">
                        View Stack Trace
                      </summary>
                      <pre className="mt-2 p-2 rounded bg-red-950/20 text-[8px] text-red-400/50 overflow-x-auto scroller">
                        {entry.stack}
                      </pre>
                    </details>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Copy, Check } from 'lucide-react';

export function MarkdownMessage({ content }: { content: string }) {
  return (
    <ReactMarkdown
      remarkPlugins={[remarkGfm]}
      components={{
        code(props) {
          const { children, className, node, ref, ...rest } = props;
          const match = /language-(\w+)/.exec(className || '');
          const isInline = !match && !className?.includes('language-');
          
          if (isInline) {
            return (
              <code className="bg-black/20 px-1.5 py-0.5 rounded text-sm font-mono text-primary-text" {...rest}>
                {children}
              </code>
            );
          }

          return (
            <CodeBlock 
              language={match ? match[1] : 'text'} 
              value={String(children).replace(/\n$/, '')} 
            />
          );
        }
      }}
    >
      {content}
    </ReactMarkdown>
  );
}

function CodeBlock({ language, value }: { language: string, value: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    await navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="my-6 overflow-hidden rounded-lg border border-panel-border/70 bg-base/70 shadow-[0_10px_30px_rgba(0,0,0,0.5),inset_0_2px_10px_rgba(255,255,255,0.02)] backdrop-blur-md transition-transform duration-300 hover:-translate-y-0.5">
      <div className="flex items-center justify-between border-b border-panel-border/60 bg-panel/40 px-4 py-2">
        <span className="font-mono text-[10px] uppercase tracking-widest text-primary">{language}</span>
        <button 
          onClick={() => handleCopy().catch(() => undefined)}
          className="flex items-center gap-2 rounded bg-base/60 px-2 py-1 font-mono text-[10px] uppercase tracking-widest text-text-muted transition-colors hover:text-primary"
        >
          {copied ? <Check className="h-3 w-3 text-success" /> : <Copy className="h-3 w-3" />}
          {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <pre className="max-h-[400px] overflow-auto p-4 font-mono text-sm leading-relaxed text-text-main">
        <code className={`language-${language}`}>{value}</code>
      </pre>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { useUIStore } from '../store/uiStore';
import type { ParticleWorkerMessage, ParticleWorkerResponse } from '../types/particleWorker';

const PARTICLE_COUNT = 50;
const PARTICLE_SPEED = 0.5;

interface MainThreadParticle {
  x: number;
  y: number;
  r: number;
  dx: number;
  dy: number;
  alpha: number;
}

function createParticle(width: number, height: number): MainThreadParticle {
  return {
    x: Math.random() * width,
    y: Math.random() * height,
    r: Math.random() * 1.5 + 0.5,
    dx: (Math.random() - 0.5) * PARTICLE_SPEED,
    dy: (Math.random() - 0.5) * PARTICLE_SPEED,
    alpha: Math.random() * 0.5 + 0.1,
  };
}

export function ParticleOverlay() {
  const particleEffects = useUIStore((s) => s.particleEffects);

  const isHeadless = typeof window !== 'undefined' && (
    /HeadlessChrome/i.test(navigator.userAgent) ||
    navigator.webdriver ||
    window.location.search.includes('fallback')
  );

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameRef = useRef<Float32Array | null>(null);

  useEffect(() => {
    if (isHeadless || !particleEffects || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    let rafId = 0;
    let workerTickId = 0;
    let worker: Worker | null = null;
    let usingWorker = false;
    let disposed = false;
    let mainParticles: MainThreadParticle[] = [];
    let lastTime = performance.now();
    let themePrimary = '#A3E4D7';
    let themeReadCountdown = 0;

    const syncCanvasSize = () => {
      const pixelRatio = window.devicePixelRatio || 1;
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width * pixelRatio;
      canvas.height = height * pixelRatio;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
    };

    const drawFrame = () => {
      ctx.clearRect(0, 0, width, height);

      // Read CSS variable sparsely to avoid synchronous style lookups on every frame.
      if (themeReadCountdown <= 0) {
        themePrimary =
          getComputedStyle(document.documentElement).getPropertyValue('--theme-primary').trim() || '#A3E4D7';
        themeReadCountdown = 24;
      } else {
        themeReadCountdown -= 1;
      }
      ctx.fillStyle = themePrimary;

      const frame = frameRef.current;
      if (frame && frame.length > 0) {
        const count = frame.length / 4;
        for (let i = 0; i < count; i += 1) {
          const base = i * 4;
          ctx.globalAlpha = frame[base + 3];
          ctx.beginPath();
          ctx.arc(frame[base], frame[base + 1], frame[base + 2], 0, Math.PI * 2);
          ctx.fill();
        }
      }

      rafId = window.requestAnimationFrame(drawFrame);
    };

    const runMainThreadFallback = () => {
      mainParticles = Array.from({ length: PARTICLE_COUNT }, () => createParticle(width, height));

      const updateFallback = (now: number) => {
        const delta = Math.min(2.5, Math.max(0.5, (now - lastTime) / 16.6667));
        lastTime = now;

        for (const particle of mainParticles) {
          particle.x += particle.dx * delta;
          particle.y += particle.dy * delta;
          if (particle.x < 0) particle.x = width;
          if (particle.x > width) particle.x = 0;
          if (particle.y < 0) particle.y = height;
          if (particle.y > height) particle.y = 0;
        }

        const packed = new Float32Array(mainParticles.length * 4);
        for (let i = 0; i < mainParticles.length; i += 1) {
          const base = i * 4;
          const p = mainParticles[i];
          packed[base] = p.x;
          packed[base + 1] = p.y;
          packed[base + 2] = p.r;
          packed[base + 3] = p.alpha;
        }
        frameRef.current = packed;

        if (!disposed) {
          window.requestAnimationFrame(updateFallback);
        }
      };

      window.requestAnimationFrame(updateFallback);
    };

    syncCanvasSize();
    drawFrame();

    const onResize = () => {
      syncCanvasSize();
      if (worker) {
        const message: ParticleWorkerMessage = { type: 'resize', width, height };
        worker.postMessage(message);
      }
    };
    window.addEventListener('resize', onResize);

    if (isHeadless) {
      usingWorker = false;
      runMainThreadFallback();
    } else {
      try {
        worker = new Worker(new URL('../workers/particleWorker.ts', import.meta.url), { type: 'module' });
        usingWorker = true;
        const init: ParticleWorkerMessage = {
          type: 'init',
          width,
          height,
          count: PARTICLE_COUNT,
          speed: PARTICLE_SPEED,
        };
        worker.postMessage(init);

        worker.onmessage = (event: MessageEvent<ParticleWorkerResponse>) => {
          if (event.data.type === 'frame') {
            frameRef.current = new Float32Array(event.data.data);
          }
        };

        let lastTick = performance.now();
        const tickWorker = () => {
          if (!worker || disposed) return;
          const now = performance.now();
          const tick: ParticleWorkerMessage = {
            type: 'tick',
            deltaMs: now - lastTick,
            isVisible: document.visibilityState === 'visible',
          };
          lastTick = now;
          worker.postMessage(tick);
        };

        workerTickId = window.setInterval(tickWorker, 16);
      } catch {
        usingWorker = false;
        runMainThreadFallback();
      }
    }

    return () => {
      disposed = true;
      window.removeEventListener('resize', onResize);
      window.cancelAnimationFrame(rafId);
      if (workerTickId) window.clearInterval(workerTickId);
      if (worker && usingWorker) {
        const stop: ParticleWorkerMessage = { type: 'stop' };
        worker.postMessage(stop);
        worker.terminate();
      }
    };
  }, [particleEffects]);

  if (isHeadless || !particleEffects) return null;

  return <canvas ref={canvasRef} className="absolute inset-0 pointer-events-none z-0 opacity-50" />;
}

import React, { useState, type ChangeEvent, type ReactNode } from 'react';
import type { LucideIcon } from 'lucide-react';
import { Cpu, Database, Globe, Image as ImageIcon, Loader2, Palette, Sparkles, Type, Volume2, ChevronRight, Puzzle } from 'lucide-react';
import { SectionHeader } from './common/SectionHeader';
import { extractThemeFromImage } from '../lib/imageTheme';
import { formatPaletteName, palettes, type PaletteKey, type ThemeVars } from '../lib/themeEngine';
import { useUIStore, type AiModel } from '../store/uiStore';

const modelOptions: Array<{ label: string; value: AiModel }> = [
  { label: 'Gemini 3.1 Pro Preview', value: 'gemini-3.1-pro-preview' },
  { label: 'Gemini 1.5 Pro', value: 'gemini-1.5-pro' },
  { label: 'Gemini 1.5 Flash', value: 'gemini-1.5-flash' },
];

const paletteSwatches: Array<keyof ThemeVars> = [
  '--theme-bg-base',
  '--theme-primary',
  '--theme-accent-triad-1',
  '--theme-accent-triad-2',
  '--theme-accent-phi-1',
  '--theme-accent-phi-2',
];

interface SettingCardProps {
  icon: LucideIcon;
  title: string;
  description: string;
  children: ReactNode;
}

function SettingCard({ icon: Icon, title, description, children }: SettingCardProps) {
  return (
    <div className="flex items-center justify-between gap-4 rounded-lg border border-panel-border/60 bg-panel/55 p-4 transition-colors hover:border-primary/40">
      <div className="flex min-w-0 items-center gap-4">
        <Icon className="h-5 w-5 shrink-0 text-text-muted" />
        <div className="min-w-0">
          <div className="font-mono text-sm tracking-wide text-text-main">{title}</div>
          <div className="mt-1 text-xs text-text-muted">{description}</div>
        </div>
      </div>
      <div className="shrink-0">{children}</div>
    </div>
  );
}

interface ToggleSettingProps {
  icon: LucideIcon;
  title: string;
  description: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

function ToggleSetting({ icon, title, description, checked, onChange }: ToggleSettingProps) {
  const inputId = title.toLowerCase().replace(/\s+/g, '-');
  return (
    <label htmlFor={inputId} className="flex cursor-pointer items-center justify-between gap-4 rounded-lg border border-panel-border/60 bg-panel/55 p-4 transition-colors hover:border-primary/40">
      <div className="flex min-w-0 items-center gap-4">
        {(() => {
          const Icon = icon;
          return <Icon className="h-5 w-5 shrink-0 text-text-muted" />;
        })()}
        <div className="min-w-0">
          <div className="font-mono text-sm tracking-wide text-text-main">{title}</div>
          <div className="mt-1 text-xs text-text-muted">{description}</div>
        </div>
      </div>
      <input
        id={inputId}
        name={inputId}
        type="checkbox"
        className="h-4 w-4 shrink-0 accent-[var(--theme-primary)]"
        checked={checked}
        onChange={(event) => onChange(event.target.checked)}
      />
    </label>
  );
}

function PaletteOption({ paletteKey }: { paletteKey: PaletteKey }) {
  const activePalette = useUIStore((state) => state.activePalette);
  const setActivePalette = useUIStore((state) => state.setActivePalette);
  const palette = palettes[paletteKey];
  const isActive = activePalette === paletteKey;

  return (
    <button
      key={paletteKey}
      onClick={() => setActivePalette(paletteKey)}
      className={`flex items-center justify-between gap-4 rounded-lg border p-4 text-left transition-colors ${
        isActive
          ? 'border-primary bg-primary/10 text-primary shadow-[0_0_15px_color-mix(in_srgb,var(--theme-primary)_14%,transparent)]'
          : 'border-panel-border/60 bg-panel/55 text-text-muted hover:border-primary/40'
      }`}
    >
      <div className="flex min-w-0 items-center gap-4">
        <Palette className="h-5 w-5 shrink-0" style={{ color: palette['--theme-primary'] }} />
        <span className="truncate font-mono text-sm tracking-wide">{formatPaletteName(paletteKey)}</span>
      </div>
      <div className="flex max-w-[92px] flex-wrap justify-end gap-1.5">
        {paletteSwatches.map((token) => (
          <span
            key={token}
            className="h-3 w-3 rounded-full border border-black/20"
            style={{ background: palette[token] }}
            title={token.replace('--theme-', '')}
          />
        ))}
      </div>
    </button>
  );
}

import { IMAGERY_LAYERS } from '../core/globe/ImageryProviderFactory';
const PluginInspector = React.lazy(() => import('./dev/PluginInspector'));
const PluginSettingsList = React.lazy(() => import('./settings/PluginSettingsList'));

export function SettingsPane() {
  const [showInspector, setShowInspector] = useState(false);
  const customWallpaper = useUIStore((state) => state.customWallpaper);
  const setCustomWallpaper = useUIStore((state) => state.setCustomWallpaper);
  const setDynamicTheme = useUIStore((state) => state.setDynamicTheme);
  const particleEffects = useUIStore((state) => state.particleEffects);
  const setParticleEffects = useUIStore((state) => state.setParticleEffects);
  const audioFeedback = useUIStore((state) => state.audioFeedback);
  const setAudioFeedback = useUIStore((state) => state.setAudioFeedback);
  const terminalFontSize = useUIStore((state) => state.terminalFontSize);
  const setTerminalFontSize = useUIStore((state) => state.setTerminalFontSize);
  const aiModel = useUIStore((state) => state.aiModel);
  const setAiModel = useUIStore((state) => state.setAiModel);
  const systemInstructions = useUIStore((state) => state.systemInstructions);
  const setSystemInstructions = useUIStore((state) => state.setSystemInstructions);
  const satelliteSettings = useUIStore((state) => state.satelliteSettings);
  const updateSatelliteSettings = useUIStore((state) => state.updateSatelliteSettings);
  const personalisation = useUIStore((state) => state.personalisation);
  const updatePersonalisation = useUIStore((state) => state.updatePersonalisation);
  const scanlineOverlay = useUIStore((state) => state.scanlineOverlay);
  const setScanlineOverlay = useUIStore((state) => state.setScanlineOverlay);
  const imageryProvider = useUIStore((state) => state.imageryProvider);
  const setImageryProvider = useUIStore((state) => state.setImageryProvider);
  const forceFallback = useUIStore((state) => state.forceFallback);
  const setForceFallback = useUIStore((state) => state.setForceFallback);
  const [isExtracting, setIsExtracting] = useState(false);

  const clearWallpaper = () => {
    if (typeof customWallpaper === 'string' && customWallpaper.startsWith('blob:')) {
      try { URL.revokeObjectURL(customWallpaper); } catch (e) {}
    }

    setCustomWallpaper(null);
    setDynamicTheme(null);
  };

  const handleImageUpload = async (event: ChangeEvent<HTMLInputElement>) => {
    const input = event.currentTarget;
    const file = input.files?.[0];
    if (!file) return;

    if (typeof customWallpaper === 'string' && customWallpaper.startsWith('blob:')) {
      try { URL.revokeObjectURL(customWallpaper); } catch (e) {}
    }

    setIsExtracting(true);
    const url = URL.createObjectURL(file);
    setCustomWallpaper(url);

    try {
      setDynamicTheme(await extractThemeFromImage(url));
    } catch (error) {
      console.error('Theme extraction failed', error);
    } finally {
      setIsExtracting(false);
      try { input.value = ''; } catch (e) {}
    }
  };

  return (
    <div className="h-full w-full overflow-y-auto bg-transparent">
      <div className="flex max-w-2xl flex-col gap-10 p-5 text-[15px] text-text-main sm:p-8">
        <section>
          <SectionHeader title="Appearance" eyebrow="Theme" />
          <div className="relative z-20 mb-5 flex flex-col gap-3">
            {(Object.keys(palettes) as PaletteKey[]).map((paletteKey) => (
              <PaletteOption key={paletteKey} paletteKey={paletteKey} />
            ))}
          </div>

          <div className="flex items-center justify-between gap-4 rounded-lg border border-panel-border/60 bg-panel/55 p-4">
            <div className="flex min-w-0 items-center gap-4">
              <div
                className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-lg border border-panel-border/60 bg-base/50 ${
                  customWallpaper ? 'bg-cover bg-center' : ''
                }`}
                style={customWallpaper ? { backgroundImage: `url(${customWallpaper})` } : undefined}
              >
                {!customWallpaper && !isExtracting && <ImageIcon className="text-text-muted/40" size={20} />}
                {isExtracting && <Loader2 className="animate-spin text-primary" size={20} />}
              </div>
              <div className="min-w-0">
                <div className="font-mono text-sm tracking-wide text-text-main">Wallpaper</div>
                <div className="mt-1 text-xs text-text-muted">
                  {isExtracting ? 'Extracting matching colors...' : 'Use an image to tint the interface'}
                </div>
              </div>
            </div>

            <label className={`rounded-lg border border-primary/30 px-4 py-2 font-mono text-xs uppercase tracking-widest transition-colors ${
              isExtracting ? 'pointer-events-none opacity-50' : 'cursor-pointer bg-primary/10 text-primary hover:bg-primary/20'
            }`}
            >
              {isExtracting ? 'Reading' : 'Browse'}
              <input id="wallpaper-upload" name="wallpaper-upload" type="file" accept="image/*" className="hidden" onChange={handleImageUpload} disabled={isExtracting} />
            </label>
          </div>
          {customWallpaper && (
            <button
              onClick={clearWallpaper}
              className="mt-3 font-mono text-[10px] uppercase tracking-widest text-danger transition-colors hover:text-danger/80"
            >
              Remove wallpaper
            </button>
          )}
        </section>

        <section>
          <SectionHeader title="Personalisation" eyebrow="UI" />
          <div className="flex flex-col gap-3">
            <ToggleSetting
              icon={Sparkles}
              title="CRT Scanlines"
              description="Retro-futuristic holographic scanline overlay"
              checked={scanlineOverlay}
              onChange={setScanlineOverlay}
            />
            <SettingCard icon={Palette} title="Panel opacity" description="Transparency level for side panels">
              <div className="flex items-center gap-3">
                <input
                  id="panel-opacity"
                  name="panel-opacity"
                  type="range"
                  min="0.1"
                  max="1"
                  step="0.05"
                  value={personalisation.panelOpacity}
                  onChange={(event) => updatePersonalisation({ panelOpacity: Number(event.target.value) })}
                  className="w-36 accent-[var(--theme-primary)]"
                />
                <span className="w-8 text-right font-mono text-xs text-primary">{Math.round(personalisation.panelOpacity * 100)}%</span>
              </div>
            </SettingCard>
            <SettingCard icon={Sparkles} title="Blur intensity" description="Backdrop blur for glassmorphism">
              <div className="flex items-center gap-3">
                <input
                  id="blur-intensity"
                  name="blur-intensity"
                  type="range"
                  min="0"
                  max="40"
                  value={personalisation.blurIntensity}
                  onChange={(event) => updatePersonalisation({ blurIntensity: Number(event.target.value) })}
                  className="w-36 accent-[var(--theme-primary)]"
                />
                <span className="w-8 text-right font-mono text-xs text-primary">{personalisation.blurIntensity}px</span>
              </div>
            </SettingCard>
            <SettingCard icon={Sparkles} title="Corner radius" description="Roundness of UI elements">
              <div className="flex items-center gap-3">
                <input
                  id="corner-radius"
                  name="corner-radius"
                  type="range"
                  min="0"
                  max="24"
                  value={personalisation.cornerRadius}
                  onChange={(event) => updatePersonalisation({ cornerRadius: Number(event.target.value) })}
                  className="w-36 accent-[var(--theme-primary)]"
                />
                <span className="w-8 text-right font-mono text-xs text-primary">{personalisation.cornerRadius}px</span>
              </div>
            </SettingCard>
            <SettingCard icon={Sparkles} title="Shadow intensity" description="Depth of panel shadows">
              <div className="flex items-center gap-3">
                <input
                  id="shadow-intensity"
                  name="shadow-intensity"
                  type="range"
                  min="0"
                  max="1"
                  step="0.1"
                  value={personalisation.shadowIntensity}
                  onChange={(event) => updatePersonalisation({ shadowIntensity: Number(event.target.value) })}
                  className="w-36 accent-[var(--theme-primary)]"
                />
                <span className="w-8 text-right font-mono text-xs text-primary">{Math.round(personalisation.shadowIntensity * 100)}%</span>
              </div>
            </SettingCard>
          </div>
        </section>

        <section>
          <SectionHeader title="Interface" eyebrow="Controls" />
          <div className="flex flex-col gap-3">
            <ToggleSetting
              icon={Sparkles}
              title="Motion effects"
              description="Ambient particles and subtle visual movement"
              checked={particleEffects}
              onChange={setParticleEffects}
            />
            <ToggleSetting
              icon={Volume2}
              title="Sound feedback"
              description="Small confirmation sounds on actions"
              checked={audioFeedback}
              onChange={setAudioFeedback}
            />
            <ToggleSetting
              icon={Globe}
              title="Occlude orbital objects"
              description="Hide satellites and orbital assets when behind the Earth's disc"
              checked={satelliteSettings?.occludeByGlobe ?? true}
              onChange={(v) => updateSatelliteSettings({ occludeByGlobe: v })}
            />
            <SettingCard icon={Sparkles} title="Satellite trails" description="Customize orbital trail rendering">
              <div className="flex items-center gap-3">
                <input
                  id="satellite-trail-length"
                  name="satellite-trail-length"
                  type="range"
                  min="5"
                  max="120"
                  value={satelliteSettings?.trailLength ?? 40}
                  onChange={(event) => updateSatelliteSettings({ trailLength: Number(event.target.value) })}
                  className="w-36 accent-[var(--theme-primary)]"
                />
                <span className="w-8 text-right font-mono text-xs text-primary">{satelliteSettings?.trailLength ?? 40}</span>
              </div>
            </SettingCard>
            <SettingCard icon={Globe} title="Satellite icon size" description="Size of rendered satellite icons">
              <div className="flex items-center gap-3">
                <input
                  id="satellite-icon-size"
                  name="satellite-icon-size"
                  type="range"
                  min="12"
                  max="64"
                  value={satelliteSettings?.iconSize ?? 32}
                  onChange={(event) => updateSatelliteSettings({ iconSize: Number(event.target.value) })}
                  className="w-36 accent-[var(--theme-primary)]"
                />
                <span className="w-8 text-right font-mono text-xs text-primary">{satelliteSettings?.iconSize ?? 32}</span>
              </div>
            </SettingCard>
            <SettingCard icon={Type} title="Chat text size" description="Adjust message and input scale">
              <div className="flex items-center gap-3">
                <input
                  id="chat-text-size"
                  name="chat-text-size"
                  type="range"
                  min="12"
                  max="24"
                  value={terminalFontSize}
                  onChange={(event) => setTerminalFontSize(Number(event.target.value))}
                  className="w-24 accent-[var(--theme-primary)]"
                />
                <span className="w-6 text-right font-mono text-xs text-primary">{terminalFontSize}</span>
              </div>
            </SettingCard>
          </div>
        </section>

        <section>
          <SectionHeader title="Environment" eyebrow="Globe" />
          <div className="flex flex-col gap-3">
            <SettingCard icon={Globe} title="Imagery provider" description="Select the graphics source for the 3D globe">
              <select
                id="imagery-provider-select"
                name="imagery-provider-select"
                value={imageryProvider}
                onChange={(event) => setImageryProvider(event.target.value)}
                className="rounded-lg border border-panel-border bg-base px-3 py-1.5 text-sm text-text-main outline-none focus:border-primary"
              >
                {IMAGERY_LAYERS.map((layer) => (
                  <option key={layer.id} value={layer.id}>
                    {layer.name}
                  </option>
                ))}
              </select>
            </SettingCard>
          </div>
        </section>

        <section>
          <SectionHeader title="Developer" eyebrow="Diagnostics" />
          <div className="flex flex-col gap-3">
            <ToggleSetting
              icon={Cpu}
              title="Force Fallback"
              description="Manually trigger 2D vector globe fallback mode"
              checked={forceFallback}
              onChange={setForceFallback}
            />
            <button
              onClick={() => setShowInspector(!showInspector)}
              className="flex items-center justify-between gap-4 rounded-lg border border-panel-border/60 bg-panel/55 p-4 transition-colors hover:border-primary/40"
            >
              <div className="flex min-w-0 items-center gap-4">
                <Database className="h-5 w-5 shrink-0 text-text-muted" />
                <div className="min-w-0">
                  <div className="font-mono text-sm tracking-wide text-text-main">Inspect Runtime</div>
                  <div className="mt-1 text-xs text-text-muted">Visual telemetry and plugin entity buffers</div>
                </div>
              </div>
              <ChevronRight className={`h-4 w-4 transition-transform ${showInspector ? 'rotate-90' : ''}`} />
            </button>

            {showInspector && (
              <div className="rounded-lg border border-panel-border/60 bg-black/40 p-4">
                <React.Suspense fallback={<div className="font-mono text-[10px] text-white/40">Initialising Inspector...</div>}>
                  <PluginInspector />
                </React.Suspense>
              </div>
            )}
          </div>
        </section>

        <section>
          <SectionHeader title="Plugins" eyebrow="Extensions" />
          <div className="flex flex-col gap-3">
            <React.Suspense fallback={<div className="font-mono text-[10px] text-white/40 italic">Loading Plugin Registry...</div>}>
              <PluginSettingsList />
            </React.Suspense>
          </div>
        </section>

        <section>
          <SectionHeader title="AI" eyebrow="Agent" />
          <div className="flex flex-col gap-3">
            <SettingCard icon={Globe} title="Model" description="Choose the Gemini model used for chat responses">
              <select
                id="ai-model-select"
                name="ai-model-select"
                value={aiModel}
                onChange={(event) => setAiModel(event.target.value as AiModel)}
                className="rounded-lg border border-panel-border bg-base px-3 py-1.5 text-sm text-text-main outline-none focus:border-primary"
              >
                {modelOptions.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </SettingCard>

            <div className="rounded-lg border border-panel-border/60 bg-panel/55 p-4">
              <div className="mb-3 flex items-center gap-4">
                <Cpu className="h-5 w-5 shrink-0 text-text-muted" />
                <div>
                  <div className="font-mono text-sm tracking-wide text-text-main">System instructions</div>
                  <div className="mt-1 text-xs text-text-muted">Default guidance sent with each message</div>
                </div>
              </div>
              <textarea
                id="system-instructions-textarea"
                name="system-instructions-textarea"
                className="min-h-[96px] w-full resize-none rounded-lg border border-panel-border bg-base p-3 text-sm text-text-main outline-none focus:border-primary"
                value={systemInstructions}
                onChange={(event) => setSystemInstructions(event.target.value)}
              />
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

/**
 * MODULE: System Layout
 * PANES: DASHBOARD (Brainstem)
 * 
 * Clinical, radar-style dashboard tracking telemetry with 2.5D constraints.
 */
import { useEffect, useState } from 'react';
import { useUIStore } from '../store/uiStore';
import { Activity, Brain, ShieldCheck, Zap, AlertTriangle, Satellite, type LucideIcon } from 'lucide-react';
import { motion } from 'motion/react';
import { useIdleTask } from '../hooks/useIdleTask';

const SvgRing = ({ value, color, label }: { value: number, color: string, label: string }) => {
  const radius = 30;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - value * circumference;

  return (
    <div className="flex flex-col items-center gap-2">
      <div className="relative w-20 h-20 flex items-center justify-center">
        <svg className="absolute inset-0 w-full h-full transform -rotate-90">
          <circle cx="40" cy="40" r={radius} fill="transparent" stroke="var(--theme-bg-panel-border)" strokeWidth="4" />
          <motion.circle 
            cx="40" cy="40" r={radius} 
            fill="transparent" stroke={color} strokeWidth="4"
            strokeDasharray={circumference}
            initial={{ strokeDashoffset: circumference }}
            animate={{ strokeDashoffset: offset }}
            transition={{ type: "spring", stiffness: 100, damping: 20 }}
            strokeLinecap="round"
          />
        </svg>
        <span className="text-[10px] font-mono font-bold tracking-widest relative z-10 text-white shadow-black drop-shadow-md">
          {(value * 100).toFixed(0)}%
        </span>
      </div>
      <span className="text-[9px] uppercase tracking-widest text-text-muted">{label}</span>
    </div>
  );
};

export function SystemMonitor() {
  const { systemMetrics, cpuLoad, setCpuLoad, updateSystemMetrics } = useUIStore();
  const [lastUpdated, setLastUpdated] = useState(new Date());

  useIdleTask(
    () => {
      const volatility = cpuLoad > 0.8 ? 0.1 : 0.02;
      const currentMetrics = useUIStore.getState().systemMetrics;
      updateSystemMetrics({
        ramUsage: clampMetric(currentMetrics.ramUsage + (Math.random() * volatility * 2 - volatility)),
        networkLatency: clampMetric(currentMetrics.networkLatency + (Math.random() * volatility * 2 - volatility)),
        storageUsage: clampMetric(currentMetrics.storageUsage + (Math.random() * 0.03 - 0.015)),
        batteryLevel: clampMetric(currentMetrics.batteryLevel + (Math.random() * 0.05 - 0.025)),
      });
      setLastUpdated(new Date());
    },
    [cpuLoad, updateSystemMetrics],
    cpuLoad > 0.8 ? 500 : 2000,
  );

  return (
    <div className="flex flex-col h-full w-full p-6 relative font-mono overflow-y-auto scroller">
      {/* HUD Header */}
      <div className="flex items-center justify-between border-b border-primary/30 pb-2 mb-6">
        <div className="flex items-center gap-2 text-primary">
          <Brain className="w-4 h-4" />
          <span className="text-[10px] uppercase font-bold tracking-[0.2em]">SYSTEM // DASHBOARD</span>
        </div>
        <div className="flex gap-1">
          <div className="w-1.5 h-1.5 bg-primary rounded-full animate-pulse" />
          <div className={`w-1.5 h-1.5 rounded-full ${cpuLoad > 0.8 ? 'bg-danger' : 'bg-primary/30'}`} />
        </div>
      </div>

      {/* SVG Rings: RAM & Network */}
      <div className="flex justify-around items-center mb-8 bg-base/30 backdrop-blur-md rounded-lg p-4 shadow-[inset_0_4px_20px_rgba(0,0,0,0.3)] border border-primary/10 relative z-10">
        <SvgRing value={systemMetrics.ramUsage} color="var(--theme-accent-triad-1)" label="RAM" />
        <SvgRing value={systemMetrics.networkLatency} color="var(--theme-accent-phi-1)" label="Network" />
      </div>

      {/* CPU Load Controls (2.5D Style) */}
      <div className="mb-8 p-4 bg-base/30 backdrop-blur-md shadow-[var(--theme-shadow-2-5d)] rounded-lg relative overflow-hidden group border border-primary/10 transition-shadow hover:shadow-[var(--theme-shadow-2-5d-hover)]">
        <div className="absolute inset-0 bg-primary/5 opacity-0 group-hover:opacity-100 transition-opacity" />
        <h4 className="text-[9px] uppercase tracking-widest text-text-muted mb-3 flex items-center justify-between">
          <span>CPU Load</span>
          <AlertTriangle className={`w-4 h-4 ${cpuLoad > 0.8 ? 'text-danger animate-[pulse_0.4s_infinite]' : 'text-primary/50'}`} />
        </h4>
        <input 
          id="cpu-load-slider"
          name="cpu-load-slider"
          type="range" 
          min="0" max="1" step="0.01" 
          value={cpuLoad}
          onChange={(e) => setCpuLoad(Number(e.target.value))}
          className="w-full h-1 bg-primary/20 rounded-lg appearance-none cursor-pointer"
          style={{ accentColor: cpuLoad > 0.8 ? 'var(--theme-danger)' : 'var(--theme-primary)' }}
        />
        <div className="flex justify-between text-[8px] text-text-muted mt-2 uppercase tracking-widest">
          <span>Idle</span>
          <span>Max</span>
        </div>
      </div>

      {/* Telemetry Readouts */}
      <div className="space-y-6">
        <TelemetryRow label="Storage Usage" value={systemMetrics.storageUsage} icon={Activity} color="var(--theme-accent-triad-2)" />
        <TelemetryRow label="Battery Level" value={systemMetrics.batteryLevel} icon={Zap} color="var(--theme-accent-phi-2)" />
        <SatcomTelemetry />
        <TelemetryRow label="System Shield" value={1.0} icon={ShieldCheck} color="var(--theme-accent-comp)" isStatic />
      </div>
      
      {/* Forensic Marginalia */}
      <div className="mt-auto pt-6 flex flex-col gap-1 text-[8px] text-text-muted/50 border-t border-primary/20 relative z-10">
        <span className="tracking-[0.3em]">STATE: LOCAL SESSION</span>
        <span className="tracking-[0.3em]">UPDATED: {lastUpdated.toLocaleTimeString()}</span>
      </div>
    </div>
  );
}

function SatcomTelemetry() {
  const satelliteData = useUIStore((s) => s.satelliteData);
  const activeTracks = Object.keys(satelliteData).length;
  
  return (
    <div className="flex items-center justify-between group">
      <div className="flex items-center gap-2">
        <Satellite className="w-4 h-4 text-text-muted group-hover:text-white transition-colors" />
        <span className="text-[10px] tracking-widest text-text-muted group-hover:text-white transition-colors uppercase">Satcom Uplink</span>
      </div>
      <div className="flex items-center gap-2">
        <span className="text-[10px] font-mono text-primary font-bold">{activeTracks}</span>
        <span className="text-[8px] text-text-muted uppercase tracking-tighter">Active Tracks</span>
      </div>
    </div>
  );
}

function clampMetric(value: number) {
  return Math.max(0, Math.min(1, value));
}

function TelemetryRow({ label, value, icon: Icon, color = "var(--theme-primary)", isStatic = false }: { label: string, value: number, icon: LucideIcon, color?: string, isStatic?: boolean }) {
  return (
    <div className="flex items-center justify-between group">
      <div className="flex items-center gap-2">
        <Icon className="w-4 h-4 text-text-muted group-hover:text-white transition-colors" />
        <span className="text-[10px] tracking-widest text-text-muted group-hover:text-white transition-colors uppercase">{label}</span>
      </div>
      {!isStatic ? (
        <div className="flex items-center gap-3">
          <div className="w-16 h-1.5 bg-base rounded-full relative overflow-hidden shadow-[inset_0_1px_3px_rgba(0,0,0,0.5)]">
            <motion.div 
              className="absolute left-0 top-0 h-full rounded-full"
              style={{ backgroundColor: color }}
              initial={{ width: 0 }}
              animate={{ width: `${value * 100}%` }}
              transition={{ type: "spring", bounce: 0, damping: 20 }}
            />
          </div>
