              onClick={handleRecenter} 
              title="Fly to active location"
            >
              <Navigation size={20} />
            </button>
            <button 
              type="button" 
              className="earth-ctrl-btn compass-btn" 
              onClick={handleCompass} 
              title="Reset camera heading (North up)"
            >
              <Compass size={20} />
