                        <div>
                          <div className="text-[10px] text-white/80 font-bold">{layer.name}</div>
                          <div className="text-[8px] text-white/40 mt-0.5">{layer.desc}</div>
                        </div>
                        <Plus size={12} className="text-white/30" />
