                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <button
              onClick={() => setDrawerOpen(true)}
              className="glass-panel p-3 px-4 hover:bg-white/10 text-white/80 hover:text-white transition-colors rounded shadow-lg flex items-center gap-2 text-xs font-bold font-mono cursor-pointer border border-primary/20"
              title="Expand Control Panel"
            >
              <Compass className="w-4 h-4 text-primary animate-pulse" />
              <span>Show Space Array controls</span>
            </button>
          )}
        </div>

        {/* Floating Telemetry Timeline Playback Controller (Bottom Center) */}
        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-40 pointer-events-auto w-[620px] max-w-[95vw]">
          <div className="glass-panel border border-primary/20 shadow-2xl p-3 px-5 flex flex-col gap-2 font-mono text-white text-[10px]">
            
            {/* Timeline Header Row */}
            <div className="flex items-center justify-between border-b border-white/5 pb-2">
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setPlaybackMode(!isPlaybackMode)}
                  className={`px-2 py-0.5 rounded text-[8px] font-bold border transition-all cursor-pointer ${
                    isPlaybackMode 
                      ? 'border-cyan-500/30 bg-cyan-950/20 text-cyan-400' 
                      : 'border-green-500/30 bg-green-950/20 text-green-400'
                  }`}
                  title="Toggle Live vs Recorded Playback Mode"
                >
                  <div className="flex items-center gap-1.5">
                    <div className={`w-1.5 h-1.5 rounded-full ${isPlaybackMode ? 'bg-cyan-400' : 'bg-green-400 animate-pulse'}`} />
                    <span>{isPlaybackMode ? 'PLAYBACK MODE' : 'LIVE TELEMETRY'}</span>
                  </div>
                </button>

                {isPlaybackMode && (
                  <button
                    onClick={() => setPlaying(!isPlaying)}
                    className="flex items-center justify-center p-1 rounded hover:bg-white/5 text-primary hover:text-primary-hover cursor-pointer"
                    title={isPlaying ? 'Pause Playback' : 'Start Playback'}
                  >
                    {isPlaying ? <Pause size={13} /> : <Play size={13} />}
                  </button>
                )}
              </div>

              {/* DateTime Display */}
              <div className="flex items-center gap-2.5 text-white/80 text-[9px]">
                <div className="flex items-center gap-1 text-white/50">
                  <Calendar size={11} />
                  <span>
                    {safeCurrentTime ? safeCurrentTime.toLocaleDateString() : 'N/A'}
                  </span>
                </div>
                <div className="flex items-center gap-1 text-white/50">
                  <Clock size={11} />
                  <span className="text-cyan-400 font-bold tabular-nums">
                    {safeCurrentTime ? safeCurrentTime.toLocaleTimeString() : 'N/A'}
                  </span>
                </div>
              </div>
            </div>

            {/* Timeline slider and speed multipliers */}
            <div className="flex flex-col gap-2">
              <div className="px-1">
                <TimelineLanes timeStart={timeStart} timeEnd={timeEnd} />
              </div>

              <div className="flex items-center gap-4">
                <div className="flex-1 flex items-center gap-2">
                  <span className="text-[8px] text-white/30">START</span>
                  <input 
                    id="wwt-timeline-progress"
                    name="wwt-timeline-progress"
                    type="range"
                    min="0"
                    max="1"
                    step="0.0001"
                    value={progressPct}
                    onChange={handleSliderChange}
                    disabled={!isPlaybackMode}
                    className="w-full h-1 bg-black/45 border border-white/5 rounded-lg appearance-none cursor-pointer accent-primary disabled:opacity-30 disabled:cursor-not-allowed"
                    style={{
                      background: `linear-gradient(to right, var(--theme-primary) 0%, var(--theme-primary) ${progressPct * 100}%, rgba(255,255,255,0.05) ${progressPct * 100}%, rgba(255,255,255,0.05) 100%)`
                    }}
                  />
                  <span className="text-[8px] text-white/30">NOW</span>
                </div>

                {isPlaybackMode && (
                  <div className="flex items-center gap-1 bg-black/30 border border-white/5 p-0.5 rounded text-[8px]">
                    {['1', '10', '100', '1000'].map(spd => {
                      const s = parseInt(spd);
                      const isSpeed = playbackSpeed === s;
                      return (
                        <button
                          key={spd}
                          onClick={() => setPlaybackSpeed(s)}
                          className={`px-1.5 py-0.5 rounded transition-all cursor-pointer ${
                            isSpeed ? 'bg-primary/20 text-primary font-bold' : 'text-white/40 hover:text-white/70'
                          }`}
                        >
                          {spd}x
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>

          </div>
        </div>
      </div>
    );
  };

  // Branch return statements
  if (bgOnly) {
    return (
      <div className="absolute inset-0 w-full h-full bg-black select-none pointer-events-none">
        {typeof window !== 'undefined' && (window as any).__triggerTelescopeCrash && <CrashComponent />}
        <div className="w-full h-full flex items-center justify-center relative overflow-hidden">
          {renderIframe()}
        </div>
      </div>
    );
  }

  if (controlsOnly) {
    return renderHUDAndTimeline();
  }

  // Fallback: render both side-by-side / overlayed if no props passed (for safety)
  return (
    <div className="relative w-full h-full flex overflow-hidden bg-transparent select-none pointer-events-none">
      <div className="absolute inset-0 z-0">
        {renderIframe()}
      </div>
      {renderHUDAndTimeline()}
    </div>
  );
}

import React, { Suspense, useState, useEffect, useCallback } from 'react';
import { MessageSquare, Globe2, Sparkles, ChevronRight } from 'lucide-react';
import { useUIStore } from '@/store/uiStore';
import { ChatPanel } from '../ChatPanel';
import { useAIChat } from '../../hooks/useAIChat';
import GoogleEarthRemix from '../learning/GoogleEarthRemix';
import WorldWideTelescopeView from '../learning/WorldWideTelescopeView';
import { ErrorBoundary } from '../ErrorBoundary';


function SidebarTrigger() {
  const leftPanelOpen = useUIStore((s) => s.leftPanelOpen);
  const setLeftPanelOpen = useUIStore((s) => s.setLeftPanelOpen);
  const interactionMode = useUIStore((s) => s.interactionMode);

  if (leftPanelOpen) return null;

  const isOrbital = interactionMode === 'orbital';

  return (
    <button
      type="button"
      onClick={() => setLeftPanelOpen(true)}
      className={`absolute top-1/2 left-0 -translate-y-1/2 z-20 flex h-14 w-5 items-center justify-center rounded-r-lg bg-black/40 hover:bg-black/60 border-y border-r border-white/10 hover:border-white/20 text-white/40 hover:text-white/80 cursor-pointer group shadow-lg transition-all duration-300 ease-out pointer-events-auto ${
        isOrbital ? 'opacity-0 pointer-events-none -translate-x-full' : 'opacity-100 translate-x-0'
      }`}
      title="Expand Sidebar"
    >
      <ChevronRight className="h-4.5 w-4.5 transition-transform group-hover:translate-x-0.5" />
    </button>
  );
}

export function CenterPanel() {
  const interactionMode = useUIStore((s) => s.interactionMode);
  const setInteractionMode = useUIStore((s) => s.setInteractionMode);
  const isProcessing = useUIStore((s) => s.isProcessing);

  const { sendMessage } = useAIChat();

  // Track WWT error state for change log reporting
  const handleTelescopeError = useCallback((error: Error) => {
    console.warn('[CenterPanel] Telescope view error caught by boundary:', error.message);
    useUIStore.getState().addChangeLog(
      'TELESCOPE',
      `View error caught: ${error.message}`,
      'warning'
    );
  }, []);

  // Keyboard shortcut: Escape exits telescope mode back to orbital
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && interactionMode === 'telescope') {
        setInteractionMode('orbital');
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [interactionMode, setInteractionMode]);

  const isSpaceMode = interactionMode === 'orbital';

  return (
    // Root container: ALWAYS pointer-events-none to let Cesium globe receive drags underneath.
    // Each interactive child explicitly opts-in with pointer-events-auto.
    <div className="flex h-full flex-1 flex-col overflow-hidden relative pointer-events-none">

      {/* Sidebar trigger ΓÇö always interactive */}
      <SidebarTrigger />

      {/* Dynamic Segmented Mode Switcher (Pill Style) ΓÇö always interactive */}
      <div className="absolute top-[18px] left-1/2 z-30 -translate-x-1/2 pointer-events-auto">
        <div className="glass-panel flex items-center p-1 rounded-full border border-white/5 shadow-lg">
          <button
            type="button"
            onClick={() => setInteractionMode('chat')}
            className={`flex items-center gap-1.5 px-3 py-1 text-[10px] font-mono font-bold uppercase rounded-full tracking-wider transition-all cursor-pointer ${
              interactionMode === 'chat' ? 'bg-primary text-white' : 'text-white/40 hover:text-white/70'
            }`}
          >
            <MessageSquare className="h-3 w-3" />
            <span>Chat</span>
          </button>
          <button
            type="button"
            onClick={() => setInteractionMode('orbital')}
            className={`flex items-center gap-1.5 px-3 py-1 text-[10px] font-mono font-bold uppercase rounded-full tracking-wider transition-all cursor-pointer ${
              interactionMode === 'orbital' ? 'bg-primary text-white' : 'text-white/40 hover:text-white/70'
            }`}
          >
            <Globe2 className="h-3 w-3" />
            <span>Space</span>
          </button>
        </div>
      </div>

      {/* Center Panel Content with Slide Transitions */}
      <div className="flex-1 w-full relative overflow-hidden">
        {/* Chat View Container */}
        <div 
          className={`absolute inset-0 flex flex-col pt-12 transition-all duration-300 ease-out ${
            interactionMode === 'chat' 
              ? 'translate-x-0 opacity-100 pointer-events-auto z-10' 
              : '-translate-x-full opacity-0 pointer-events-none z-0'
          }`}
        >
          <div className="flex-1 w-full flex flex-col justify-between overflow-hidden">
            {/* Header Neural Indicator */}
            <div className="flex h-8 shrink-0 items-center justify-between px-6 border-b border-white/5 bg-black/10">
              <div className="flex items-center gap-2 text-primary">
                <Sparkles className="h-3.5 w-3.5 glow-pulse" />
                <span className="text-[9px] font-mono font-bold uppercase tracking-[0.25em]">Neural Interface active</span>
              </div>
            </div>

            {/* Scrollable messages */}
            <div className="flex-1 overflow-hidden">
              <ChatPanel />
            </div>

            {/* Input bar removed to prevent duplication (ChatPanel manages its own) */}
          </div>
        </div>

        {/* Combined Space & Telescope Viewport Container */}
        <div 
          className={`absolute inset-0 transition-all duration-300 ease-out ${
            isSpaceMode
              ? 'translate-x-0 opacity-100 z-10' 
              : 'translate-x-full opacity-0 pointer-events-none z-0'
          }`}
        >
          {/* WorldWide Telescope controls overlay ΓÇö wrapped in inline ErrorBoundary for graceful degradation */}
          {isSpaceMode && (
            <div className="absolute inset-0 pointer-events-none z-20">
              <ErrorBoundary
                variant="inline"
                fallbackMessage="Telescope Controls Error"
                onError={handleTelescopeError}
              >
                <WorldWideTelescopeView controlsOnly />
              </ErrorBoundary>
            </div>
          )}

          {/* GoogleEarthRemix overlay ΓÇö pointer-events-none so globe underneath gets drags */}
          {isSpaceMode && (
            <div className="absolute inset-0 pointer-events-none z-10">
              <GoogleEarthRemix />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

