import { type ChangeEvent, useState } from 'react';
import { ImageIcon, Loader2, Check, Sparkles, Layout, Type, Palette, Globe, Satellite, Map, ToggleLeft, ToggleRight } from 'lucide-react';
import { useUIStore } from '@/store/uiStore';
import { useStore } from '@/core/state/store';
import { palettes, type PaletteKey, formatPaletteName } from '../../lib/themeEngine';
import { extractThemeFromImage } from '../../lib/imageTheme';
import { IMAGERY_LAYERS } from '../../core/globe/ImageryProviderFactory';
import CURSOR_DESIGNS from '@/components/layout/cursorDesigns';
import { resolveCursorProfile, validateCursorProfile } from '@/core/cursor';

export function PersonalisationSettings() {
  const personalisation = useUIStore((s) => s.personalisation) || {
    accentColor: '',
    panelOpacity: 0.75,
    blurIntensity: 16,
    cornerRadius: 12,
    shadowIntensity: 0.5,
    borderStyle: 'subtle',
    uiDensity: 'comfortable',
    chatBubbleStyle: 'glass',
    iconStyle: 'outlined',
    panelTransitionStyle: 'slide',
    fontScale: 1.0,
    fontFamily: 'Outfit',
    animationIntensity: 0.7,
    motionReduced: false,
  };
  const updatePersonalisation = useUIStore((s) => s.updatePersonalisation);
  const activePalette = useUIStore((s) => s.activePalette);
  const updateSettings = useUIStore((s) => s.updateSettings);
  const scanlineOverlay = useUIStore((s) => s.scanlineOverlay);
  const setScanlineOverlay = useUIStore((s) => s.setScanlineOverlay);
  const cameraSensitivity = useUIStore((s) => s.cameraSensitivity ?? 1.0);
  const setCameraSensitivity = useUIStore((s) => s.setCameraSensitivity);
  
  const [uploadLoading, setUploadLoading] = useState(false);

  // Background atmosphere extractor
  const onUpload = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadLoading(true);
    const url = URL.createObjectURL(file);
    updateSettings({ customWallpaper: url });
    try {
      const theme = await extractThemeFromImage(url);
      updateSettings({ dynamicTheme: theme });
    } catch (err) {
      console.error('Failed to extract theme:', err);
    } finally {
      setUploadLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* SECTION 1: COLOR SYSTEMS */}
      <div className="glass-panel p-4 border border-white/5 space-y-4 rounded-xl">
        <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-primary flex items-center gap-1.5">
          <Palette className="h-4 w-4" />
          <span>Color & Theme Systems</span>
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Palette Selector */}
          <div className="space-y-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">Visual Profile Palette</label>
            <div className="grid grid-cols-2 gap-2">
              {(Object.keys(palettes) as PaletteKey[]).map((pk) => {
                const isSelected = activePalette === pk;
                const paletteColors = palettes[pk];
                return (
                  <button
                    key={pk}
                    type="button"
                    onClick={() => updateSettings({ activePalette: pk })}
                    className={`flex items-center justify-between px-3 py-2.5 rounded-lg border text-[9px] font-mono uppercase tracking-wider transition-all cursor-pointer ${
                      isSelected
                        ? 'border-primary bg-primary/10 text-primary font-bold'
                        : 'border-white/5 bg-white/5 text-white/50 hover:border-white/10 hover:text-white/80'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <div
                        className="h-3 w-3 rounded-full border border-white/10"
                        style={{ backgroundColor: paletteColors['--theme-primary'] }}
                      />
                      <span>{formatPaletteName(pk)}</span>
                    </div>
                    {isSelected && <Check className="h-3.5 w-3.5" />}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Accent Override */}
          <div className="space-y-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">Accent Color Override</label>
            <div className="flex gap-2">
              <input
                id="accent-color-picker"
                name="accent-color-picker"
                type="color"
                value={personalisation.accentColor || palettes[activePalette]['--theme-primary']}
                onChange={(e) => updatePersonalisation({ accentColor: e.target.value })}
                className="h-9 w-9 rounded-lg bg-white/5 border border-white/10 p-1 cursor-pointer"
              />
              <input
                id="accent-color-text"
                name="accent-color-text"
                type="text"
                value={personalisation.accentColor}
                onChange={(e) => updatePersonalisation({ accentColor: e.target.value })}
                placeholder="Hex override (e.g. #00ffff)"
                className="flex-1 rounded-lg bg-white/5 border border-white/5 px-3 text-xs text-text-main focus:outline-none focus:ring-1 focus:ring-primary/35 font-mono"
              />
              {personalisation.accentColor && (
                <button
                  type="button"
                  onClick={() => updatePersonalisation({ accentColor: '' })}
                  className="px-2.5 py-2 text-[9px] font-mono uppercase rounded bg-white/5 text-white/40 hover:bg-white/10"
                >
                  Reset
                </button>
              )}
            </div>
          </div>

          {/* Theme Profile Dropdown */}
          <div className="space-y-2 col-span-1 md:col-span-2 mt-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">Theme Profile Dropdown</label>
            <select
              id="theme-profile-select"
              name="theme-profile-select"
              value={activePalette}
              onChange={(e) => updateSettings({ activePalette: e.target.value as PaletteKey })}
              className="w-full bg-white/5 border border-white/5 rounded-lg px-3 py-2 text-xs font-mono text-white/70 focus:outline-none focus:ring-1 focus:ring-primary/35 cursor-pointer"
            >
              <option value="holographic" className="bg-neutral-900">Holographic (Silver Wolf)</option>
              <option value="coreHacker" className="bg-neutral-900">Core Hacker</option>
              <option value="glitchNeon" className="bg-neutral-900">Glitch Neon</option>
              <option value="silverPunk" className="bg-neutral-900">Silver Punk</option>
              <option value="randomFan" className="bg-neutral-900">Random Fan</option>
              <option value="pastelDream" className="bg-neutral-900">Pastel Dream</option>
            </select>
          </div>
        </div>

        {/* Wallpaper Image Upload */}
        <div className="p-3.5 rounded-lg bg-white/5 border border-white/5 flex items-center justify-between mt-2">
          <div className="flex items-center gap-3 text-white/40">
            {uploadLoading ? <Loader2 className="animate-spin text-cyan-400" size={16} /> : <ImageIcon size={16} />}
            <div className="flex flex-col">
              <span className="text-[10px] font-mono uppercase text-white/80">Atmosphere Wallpaper</span>
              <span className="text-[8px] text-white/30 font-mono">sampling colors from image background</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {useUIStore((s) => s.customWallpaper) && (
              <button
                type="button"
                onClick={() => updateSettings({ customWallpaper: null, dynamicTheme: null })}
                className="text-[9px] font-mono px-3 py-1.5 border border-white/5 rounded-lg uppercase bg-white/5 text-red-400 hover:bg-red-950/20"
              >
                Clear
              </button>
            )}
            <label className="text-[9px] font-mono px-3 py-1.5 bg-primary/20 border border-primary/20 text-primary hover:bg-primary-hover hover:text-white rounded-lg uppercase cursor-pointer transition-all">
              Upload
              <input id="personalisation-wallpaper-upload" name="personalisation-wallpaper-upload" type="file" hidden onChange={onUpload} />
            </label>
          </div>
        </div>
      </div>

      {/* SECTION 2: BLURS, OPACITIES, SHADOWS */}
      <div className="glass-panel p-4 border border-white/5 space-y-4 rounded-xl">
        <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-primary flex items-center gap-1.5">
          <Layout className="h-4 w-4" />
          <span>Layout & Depth Systems</span>
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          {/* Panel Opacity */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-[10px] font-mono">
              <span className="uppercase text-white/40">Panel Transparency</span>
              <span className="text-primary font-bold">{Math.round(personalisation.panelOpacity * 100)}%</span>
            </div>
            <input
              id="personalisation-panel-transparency"
              name="personalisation-panel-transparency"
              type="range"
              min={10}
              max={100}
              value={personalisation.panelOpacity * 100}
              onChange={(e) => updatePersonalisation({ panelOpacity: parseFloat(e.target.value) / 100 })}
              className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-primary"
            />
          </div>

          {/* Blur Intensity */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-[10px] font-mono">
              <span className="uppercase text-white/40">Background Blur</span>
              <span className="text-primary font-bold">{personalisation.blurIntensity}px</span>
            </div>
            <input
              id="personalisation-background-blur"
              name="personalisation-background-blur"
              type="range"
              min={0}
              max={40}
              value={personalisation.blurIntensity}
              onChange={(e) => updatePersonalisation({ blurIntensity: parseInt(e.target.value) })}
              className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-primary"
            />
          </div>

          {/* Corner Roundness */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-[10px] font-mono">
              <span className="uppercase text-white/40">Corner Roundness</span>
              <span className="text-primary font-bold">{personalisation.cornerRadius}px</span>
            </div>
            <input
              id="personalisation-corner-roundness"
              name="personalisation-corner-roundness"
              type="range"
              min={0}
              max={24}
              value={personalisation.cornerRadius}
              onChange={(e) => updatePersonalisation({ cornerRadius: parseInt(e.target.value) })}
              className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-primary"
            />
          </div>

          {/* Shadow Depth */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-[10px] font-mono">
              <span className="uppercase text-white/40">Shadow Intensity</span>
              <span className="text-primary font-bold">{Math.round(personalisation.shadowIntensity * 100)}%</span>
            </div>
            <input
              id="personalisation-shadow-intensity"
              name="personalisation-shadow-intensity"
              type="range"
              min={0}
              max={100}
              value={personalisation.shadowIntensity * 100}
              onChange={(e) => updatePersonalisation({ shadowIntensity: parseFloat(e.target.value) / 100 })}
              className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-primary"
            />
          </div>

          {/* Border Styles */}
          <div className="space-y-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">Border Style</label>
            <div className="flex bg-white/5 p-1 rounded-lg border border-white/5 gap-1 text-[9px] font-mono">
              {['subtle', 'glow', 'solid', 'none'].map((style) => (
                <button
                  key={style}
                  type="button"
                  onClick={() => updatePersonalisation({ borderStyle: style as any })}
                  className={`flex-1 py-1 rounded transition-colors uppercase cursor-pointer ${
                    personalisation.borderStyle === style ? 'bg-primary text-white font-bold' : 'text-white/40 hover:text-white/70'
                  }`}
                >
                  {style}
                </button>
              ))}
            </div>
          </div>

          {/* UI Density */}
          <div className="space-y-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">UI Spacing Density</label>
            <div className="flex bg-white/5 p-1 rounded-lg border border-white/5 gap-1 text-[9px] font-mono">
              {['compact', 'comfortable', 'spacious'].map((density) => (
                <button
                  key={density}
                  type="button"
                  onClick={() => updatePersonalisation({ uiDensity: density as any })}
                  className={`flex-1 py-1 rounded transition-colors uppercase cursor-pointer ${
                    personalisation.uiDensity === density ? 'bg-primary text-white font-bold' : 'text-white/40 hover:text-white/70'
                  }`}
                >
                  {density}
                </button>
              ))}
            </div>
          </div>

          {/* Chat Bubble Style */}
          <div className="space-y-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">Chat Bubble Appearance</label>
            <div className="flex bg-white/5 p-1 rounded-lg border border-white/5 gap-1 text-[9px] font-mono">
              {['glass', 'solid', 'minimal'].map((style) => (
                <button
                  key={style}
                  type="button"
                  onClick={() => updatePersonalisation({ chatBubbleStyle: style as any })}
                  className={`flex-1 py-1 rounded transition-colors uppercase cursor-pointer ${
                    personalisation.chatBubbleStyle === style ? 'bg-primary text-white font-bold' : 'text-white/40 hover:text-white/70'
                  }`}
                >
                  {style}
                </button>
              ))}
            </div>
          </div>

          {/* Icon Style */}
          <div className="space-y-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">System Icon Style</label>
            <div className="flex bg-white/5 p-1 rounded-lg border border-white/5 gap-1 text-[9px] font-mono">
              {['outlined', 'filled'].map((style) => (
                <button
                  key={style}
                  type="button"
                  onClick={() => updatePersonalisation({ iconStyle: style as any })}
                  className={`flex-1 py-1 rounded transition-colors uppercase cursor-pointer ${
                    personalisation.iconStyle === style ? 'bg-primary text-white font-bold' : 'text-white/40 hover:text-white/70'
                  }`}
                >
                  {style}
                </button>
              ))}
            </div>
          </div>

          {/* Panel Transition Style */}
          <div className="space-y-2 col-span-1 md:col-span-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">Panel Transition Animation</label>
            <div className="flex bg-white/5 p-1 rounded-lg border border-white/5 gap-1 text-[9px] font-mono">
              {[
                { key: 'slide', label: 'Slide Out' },
                { key: 'swing-3d', label: 'Swing 3D' },
                { key: 'fade', label: 'Fade Only' },
              ].map((style) => (
                <button
                  key={style.key}
                  type="button"
                  onClick={() => updatePersonalisation({ panelTransitionStyle: style.key as any })}
                  className={`flex-1 py-1 rounded transition-colors uppercase cursor-pointer ${
                    personalisation.panelTransitionStyle === style.key ? 'bg-primary text-white font-bold' : 'text-white/40 hover:text-white/70'
                  }`}
                >
                  {style.label}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* SECTION 3: TEXT & FONTS */}
      <div className="glass-panel p-4 border border-white/5 space-y-4 rounded-xl">
        <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-primary flex items-center gap-1.5">
          <Type className="h-4 w-4" />
          <span>Text & Typography</span>
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Text size scaling */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-[10px] font-mono">
              <span className="uppercase text-white/40">Text Size Scale</span>
              <span className="text-primary font-bold">{Math.round(personalisation.fontScale * 100)}%</span>
            </div>
            <input
              id="personalisation-font-scale"
              name="personalisation-font-scale"
              type="range"
              min={80}
              max={140}
              value={personalisation.fontScale * 100}
              onChange={(e) => updatePersonalisation({ fontScale: parseFloat(e.target.value) / 100 })}
              className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-primary"
            />
          </div>

          {/* Font Family selection */}
          <div className="space-y-2">
            <label className="text-[10px] font-mono uppercase text-white/40 block">Font Family</label>
            <select
              id="personalisation-font-family"
              name="personalisation-font-family"
              value={personalisation.fontFamily}
              onChange={(e) => updatePersonalisation({ fontFamily: e.target.value as any })}
              className="w-full bg-white/5 border border-white/5 rounded-lg px-3 py-2 text-xs font-mono text-white/70 focus:outline-none focus:ring-1 focus:ring-primary/35"
            >
              <option value="Outfit" className="bg-neutral-900">Outfit (Default)</option>
              <option value="Inter" className="bg-neutral-900">Inter (Modern)</option>
              <option value="system-ui" className="bg-neutral-900">System UI</option>
            </select>
          </div>
        </div>
      </div>

      {/* SECTION 4: MOTION & EFFECTS */}
      <div className="glass-panel p-4 border border-white/5 space-y-4 rounded-xl">
        <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-primary flex items-center gap-1.5">
          <Sparkles className="h-4 w-4" />
          <span>Performance & Animation Effects</span>
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Animation speed slider */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-[10px] font-mono">
              <span className="uppercase text-white/40">Animation Speed</span>
              <span className="text-primary font-bold">{Math.round(personalisation.animationIntensity * 100)}%</span>
            </div>
            <input
              id="personalisation-animation-speed"
              name="personalisation-animation-speed"
              type="range"
              min={0}
              max={100}
              value={personalisation.animationIntensity * 100}
              onChange={(e) => updatePersonalisation({ animationIntensity: parseFloat(e.target.value) / 100 })}
              className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-primary"
            />
          </div>

          {/* Camera sensitivity slider */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-[10px] font-mono">
              <span className="uppercase text-white/40">Camera Sensitivity</span>
              <span className="text-primary font-bold">{Math.round(cameraSensitivity * 100)}%</span>
            </div>
            <input
              id="personalisation-camera-sensitivity"
              name="personalisation-camera-sensitivity"
              type="range"
              min={50}
              max={200}
              value={cameraSensitivity * 100}
              onChange={(e) => setCameraSensitivity(parseFloat(e.target.value) / 100)}
              className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-primary"
            />
          </div>

          {/* Motion reduced toggle */}
          <div className="flex items-center justify-between p-2.5 rounded-lg bg-white/5 border border-white/5">
            <div className="flex flex-col">
              <span className="text-[10px] font-mono uppercase text-white/80 font-bold">Reduce Motion</span>
              <span className="text-[8px] text-white/30 font-mono mt-0.5">Disables animated canvas particles</span>
            </div>
            <input
              id="personalisation-reduce-motion"
              name="personalisation-reduce-motion"
              type="checkbox"
              checked={personalisation.motionReduced}
              onChange={(e) => updatePersonalisation({ motionReduced: e.target.checked })}
              className="h-4 w-4 accent-primary cursor-pointer"
            />
          </div>

          {/* Scanline / CRT overlay toggle */}
          <div className="flex items-center justify-between p-2.5 rounded-lg bg-white/5 border border-white/5">
            <div className="flex flex-col">
              <span className="text-[10px] font-mono uppercase text-white/80 font-bold">Scanline Overlay</span>
              <span className="text-[8px] text-white/30 font-mono mt-0.5">Enable CRT-style scanline overlay across the workspace</span>
            </div>
            <input
              id="personalisation-scanline-overlay"
              name="personalisation-scanline-overlay"
              type="checkbox"
              checked={scanlineOverlay}
              onChange={(e) => setScanlineOverlay(e.target.checked)}
              className="h-4 w-4 accent-primary cursor-pointer"
            />
          </div>
        </div>
      </div>

      {/* SECTION: IMAGERY PROVIDER SELECTOR */}
      <CursorDesignSelector />
      <ImageryProviderSelector />

      {/* SECTION: SATELLITE TRACKER SETTINGS */}
      <SatelliteTrackerSettings />
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
   Imagery Provider Selector ΓÇö card grid for globe imagery layers
   ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function CursorDesignSelector() {
  const cursorDesign = useUIStore((s) => s.cursorDesign);
  const setCursorDesign = useUIStore((s) => s.setCursorDesign);
  const personalisation = useUIStore((s) => s.personalisation);
  const particleEffects = useUIStore((s) => s.particleEffects);
  const profile = resolveCursorProfile({
    enabled: true,
    cursorDesign,
    reducedMotion: personalisation.motionReduced,
    appHighLoad: false,
    animationIntensity: personalisation.animationIntensity,
    accentColor: personalisation.accentColor,
    particleEffects,
  });
  const diagnostic = validateCursorProfile(profile);

  return (
    <div className="glass-panel p-4 border border-white/5 space-y-3 rounded-xl">
      <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-primary flex items-center gap-1.5">
        <Map className="h-4 w-4" />
        <span>Cursor & Pointer</span>
      </h3>
      <p className="text-[9px] font-mono text-white/30 uppercase">Choose a pointer design optimized for responsiveness.</p>

      <div className="rounded-lg border border-white/5 bg-white/[0.03] p-3 font-mono">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <span className="text-[10px] uppercase text-white/45">Active Profile</span>
          <span className="text-[10px] font-bold uppercase text-primary">{profile.label}</span>
        </div>
        <div className="mt-1 text-[9px] uppercase text-white/35">{diagnostic.tier}</div>
        <div className="mt-1 text-[9px] leading-relaxed text-white/45">{diagnostic.message}</div>
      </div>

      <div className="grid grid-cols-3 md:grid-cols-6 gap-2 mt-2">
        {CURSOR_DESIGNS.map((d) => {
          const isSelected = cursorDesign === d.id;
          return (
            <button
              key={d.id}
              type="button"
              onClick={() => setCursorDesign(d.id)}
              className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-all cursor-pointer text-[9px] text-white/70 ${
                isSelected ? 'border-primary bg-primary/12 shadow-[0_0_10px_rgba(138,91,199,0.08)]' : 'border-white/5 bg-white/5 hover:border-white/10 hover:bg-white/8'
              }`}
            >
              <div className="w-12 h-12 flex items-center justify-center">{d.preview}</div>
              <span className={`truncate w-full text-[9px] font-mono uppercase ${isSelected ? 'text-primary font-bold' : 'text-white/60'}`}>{d.name}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ImageryProviderSelector() {
  const imageryProvider = useUIStore((s) => s.imageryProvider);
  const setImageryProvider = useUIStore((s) => s.setImageryProvider);
  const updateMapConfig = useStore((s) => s.updateMapConfig);

  const handleSelect = (layerId: string) => {
    setImageryProvider(layerId);
    // Bridge to the configSlice store so useImageryManager picks it up
    updateMapConfig({ baseLayerId: layerId });
  };

  return (
    <div className="glass-panel p-4 border border-white/5 space-y-4 rounded-xl">
      <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-primary flex items-center gap-1.5">
        <Globe className="h-4 w-4" />
        <span>Globe Imagery Provider</span>
      </h3>
      <p className="text-[9px] font-mono text-white/30 uppercase">
        Select the base imagery layer for the 3D globe rendering engine.
      </p>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
        {IMAGERY_LAYERS.map((layer) => {
          const isSelected = (imageryProvider || 'cesium') === layer.id;
          return (
            <button
              key={layer.id}
              type="button"
              onClick={() => handleSelect(layer.id)}
              className={`group relative flex flex-col overflow-hidden rounded-lg border transition-all duration-300 ${
                isSelected
                  ? 'border-primary bg-primary/10 shadow-[0_0_15px_color-mix(in_srgb,var(--theme-primary)_20%,transparent)] scale-[1.02]'
                  : 'border-white/5 bg-white/5 hover:border-white/20 hover:bg-white/10'
              }`}
            >
              {/* Thumbnail Container */}
              <div className="relative h-20 w-full overflow-hidden bg-black/40">
                {layer.thumbnail ? (
                  <img 
                    src={layer.thumbnail} 
                    alt={layer.name}
                    className={`h-full w-full object-cover transition-transform duration-500 group-hover:scale-110 ${
                      isSelected ? 'opacity-100' : 'opacity-60 grayscale-[40%]'
                    }`}
                  />
                ) : (
                  <div className="flex h-full w-full items-center justify-center text-white/10">
                    <Map size={24} />
                  </div>
                )}
                
                {/* Selection Overlay */}
                {isSelected && (
                  <div className="absolute inset-0 bg-primary/20 backdrop-blur-[1px] flex items-center justify-center">
                    <div className="bg-primary rounded-full p-1 shadow-lg">
                      <Check size={14} className="text-white" />
                    </div>
                  </div>
                )}
              </div>

              {/* Label Area */}
              <div className="p-2.5 space-y-0.5">
                <div className={`text-[10px] font-mono font-bold uppercase tracking-wider truncate ${
                  isSelected ? 'text-primary' : 'text-white/70 group-hover:text-white'
                }`}>
                  {layer.name}
                </div>
                <div className="text-[8px] font-mono text-white/30 uppercase leading-tight line-clamp-1">
                  {layer.description}
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
   Satellite Tracker Settings ΓÇö category toggles & trail config
   ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function SatelliteTrackerSettings() {
  const satelliteCategories = useUIStore((s) => s.satelliteCategories);
  const toggleSatelliteCategory = useUIStore((s) => s.toggleSatelliteCategory);
  const satelliteSettings = useUIStore((s) => s.satelliteSettings);
  const updateSatelliteSettings = useUIStore((s) => s.updateSatelliteSettings);

  const categories = [
    { key: 'spaceStations', label: 'Space Stations', icon: '≡ƒÅá', color: '#00FFF7' },
    { key: 'brightest', label: 'Brightest', icon: 'Γ£¿', color: '#F0ABFC' },
    { key: 'weather', label: 'Weather', icon: '≡ƒîñ∩╕Å', color: '#A78BFA' },
    { key: 'gps', label: 'GPS / GNSS', icon: '≡ƒôí', color: '#22C55E' },
    { key: 'earthObs', label: 'Earth Observation', icon: '≡ƒîì', color: '#F97316' },
    { key: 'starlink', label: 'Starlink', icon: '≡ƒô╢', color: '#FFFFFF' },
    { key: 'military', label: 'Military', icon: '≡ƒ¢í∩╕Å', color: '#3B82F6' },
    { key: 'other', label: 'Other', icon: '≡ƒ¢░∩╕Å', color: '#94A3B8' },
  ];

  return (
    <div className="glass-panel p-4 border border-white/5 space-y-4 rounded-xl">
      <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-primary flex items-center gap-1.5">
        <Satellite className="h-4 w-4" />
        <span>Satellite Tracker Categories</span>
      </h3>
      <p className="text-[9px] font-mono text-white/30 uppercase">
        Toggle visibility of satellite categories on the orbital display.
      </p>

      {/* Category grid */}
      <div className="grid grid-cols-2 gap-2">
        {categories.map(({ key, label, icon, color }) => {
          const isActive = satelliteCategories[key] !== false;
          return (
            <button
              key={key}
              type="button"
              onClick={() => toggleSatelliteCategory(key)}
              className={`flex items-center justify-between px-3 py-2.5 rounded-lg border text-left transition-all cursor-pointer ${
                isActive
                  ? 'border-white/10 bg-white/8'
                  : 'border-white/5 bg-white/3 opacity-50'
              }`}
            >
              <div className="flex items-center gap-2">
                <span className="text-xs">{icon}</span>
                <span className={`text-[9px] font-mono font-bold uppercase tracking-wider ${
                  isActive ? 'text-white/80' : 'text-white/30'
                }`}>
                  {label}
                </span>
              </div>
              <div
                className="h-2.5 w-2.5 rounded-full shrink-0"
                style={{
                  backgroundColor: isActive ? color : 'transparent',
                  border: `1.5px solid ${isActive ? color : 'rgba(255,255,255,0.15)'}`,
                  boxShadow: isActive ? `0 0 6px ${color}60` : 'none',
                }}
              />
            </button>
          );
        })}
      </div>

      {/* Trail settings */}
      <div className="border-t border-white/5 pt-3 space-y-2">
        <div className="flex items-center justify-between p-2.5 rounded-lg bg-white/5 border border-white/5">
          <div className="flex flex-col">
            <span className="text-[10px] font-mono uppercase text-white/80 font-bold">Show Selected Trail</span>
            <span className="text-[8px] text-white/30 font-mono mt-0.5">Display orbital path trail for the selected satellite</span>
          </div>
          <div
            onClick={() => updateSatelliteSettings({ showTrails: !satelliteSettings.showTrails })}
            className="cursor-pointer"
          >
            {satelliteSettings.showTrails ? (
              <ToggleRight className="h-5 w-5 text-primary" />
            ) : (
              <ToggleLeft className="h-5 w-5 text-white/20" />
            )}
          </div>
        </div>

        <div className="flex items-center justify-between p-2.5 rounded-lg bg-white/5 border border-white/5">
          <div className="flex flex-col">
            <span className="text-[10px] font-mono uppercase text-white/80 font-bold">Show All Trails</span>
            <span className="text-[8px] text-white/30 font-mono mt-0.5">Display trails for all visible satellites simultaneously</span>
          </div>
          <div
            onClick={() => updateSatelliteSettings({ showAllTrails: !satelliteSettings.showAllTrails })}
            className="cursor-pointer"
          >
            {satelliteSettings.showAllTrails ? (
              <ToggleRight className="h-5 w-5 text-primary" />
            ) : (
              <ToggleLeft className="h-5 w-5 text-white/20" />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { pluginManager } from '@/core/plugins/PluginManager';
import { Settings, Puzzle, AlertCircle } from 'lucide-react';

export default function PluginSettingsList() {
  const plugins = pluginManager.getAllPlugins();
  const pluginsWithSettings = plugins.filter(p => p.plugin.getSettingsComponent);

  if (pluginsWithSettings.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-8 border border-dashed border-white/10 rounded-xl bg-white/5 text-center">
        <Puzzle className="h-8 w-8 text-white/20 mb-3" />
        <p className="text-xs text-text-muted">No active plugins require custom configuration.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {pluginsWithSettings.map(({ plugin, enabled }) => {
        const SettingsComponent = plugin.getSettingsComponent!();
        
        return (
          <div key={plugin.id} className={`p-4 rounded-xl border transition-all ${
            enabled ? 'border-primary/20 bg-primary/5' : 'border-white/5 bg-black/20 opacity-60'
          }`}>
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-white/5">
                  {typeof plugin.icon === 'string' ? (
                    <img src={plugin.icon} className="w-5 h-5" alt="" />
                  ) : (
                    <plugin.icon size={20} className="text-primary" />
                  )}
                </div>
                <div>
                  <h4 className="text-sm font-bold text-white/90">{plugin.name}</h4>
                  <p className="text-[10px] text-white/40 uppercase tracking-wider">{plugin.id} v{plugin.version}</p>
                </div>
              </div>
              {!enabled && (
                <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-amber-500/10 border border-amber-500/20 text-amber-500 text-[9px] font-bold">
                  <AlertCircle size={10} />
                  DISABLED
                </div>
              )}
            </div>
            
            <div className="pl-12">
              <SettingsComponent pluginId={plugin.id} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

import React, { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import { loadConfig, type AppConfig as Config } from '../lib/config';

interface ConfigContextValue {
  config: Config | null;
  isLoading: boolean;
  error: Error | null;
}

const ConfigContext = createContext<ConfigContextValue | undefined>(undefined);

export function ConfigProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<ConfigContextValue>({
    config: null,
    isLoading: true,
    error: null,
  });

  useEffect(() => {
    let active = true;
    
    loadConfig()
      .then((config) => {
        if (active) {
          setState({ config, isLoading: false, error: null });
        }
      })
      .catch((err) => {
        if (active) {
          setState({ config: null, isLoading: false, error: err instanceof Error ? err : new Error(String(err)) });
        }
      });

    return () => {
      active = false;
    };
  }, []);

  return (
    <ConfigContext.Provider value={state}>
      {children}
    </ConfigContext.Provider>
  );
}

export function useConfig() {
  const context = useContext(ConfigContext);
  if (context === undefined) {
    throw new Error('useConfig must be used within a ConfigProvider');
  }
  return context;
}

import { CursorTargetRegistry } from "./TargetRegistry";
import { deriveRuntimePolicy, resolveCursorProfile } from "./profiles";
import { validateCursorProfile } from "./diagnostics";
import { setActiveCursorEngine } from "./runtime";
import type {
  CursorEngineConfig,
  CursorEngineLifecycle,
  CursorFrameState,
  CursorIntent,
  CursorMode,
  CursorPointerModality,
  CursorRuntimePolicy,
  CursorTarget,
  CursorTargetSource,
  CursorVector,
} from "./types";

type TrailSample = {
  x: number;
  y: number;
  life: number;
  width: number;
};

const DEFAULT_CONFIG: CursorEngineConfig = {
  enabled: true,
  cursorDesign: "reticle-v1",
  reducedMotion: false,
  appHighLoad: false,
  animationIntensity: 0.7,
  particleEffects: true,
};

const MAX_DRIFT_PX = 110;
const DRAG_THRESHOLD_PX = 6;
const WATCHDOG_MS = 500;

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function isTextInputElement(element: Element | null): boolean {
  if (!(element instanceof HTMLElement)) return false;
  if (element.isContentEditable) return true;
  const closest = element.closest("input, textarea, [contenteditable='true']");
  if (!(closest instanceof HTMLElement)) return false;
  if (closest instanceof HTMLInputElement) {
    const type = closest.type || "text";
    return !["button", "checkbox", "color", "file", "image", "radio", "range", "reset", "submit"].includes(type);
  }
  return true;
}

function getInteractiveTarget(element: Element | null): HTMLElement | null {
  if (!(element instanceof HTMLElement)) return null;
  return element.closest("button, a, input, textarea, select, [role='button'], [role='link'], [data-cursor-target]") as HTMLElement | null;
}

function cssColorWithAlpha(color: string, alpha: number): string {
  if (/^#[0-9a-f]{6}$/i.test(color)) {
    const r = parseInt(color.slice(1, 3), 16);
    const g = parseInt(color.slice(3, 5), 16);
    const b = parseInt(color.slice(5, 7), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }
  return `rgba(125, 227, 201, ${alpha})`;
}

export class CursorEngine implements CursorEngineLifecycle {
  private config: CursorEngineConfig;
  private mount: HTMLElement | null = null;
  private reticle: HTMLDivElement | null = null;
  private canvas: HTMLCanvasElement | null = null;
  private ctx: CanvasRenderingContext2D | null = null;
  private debug: HTMLDivElement | null = null;
  private raf = 0;
  private attached = false;
  private pointerActual: CursorVector = { x: typeof window !== "undefined" ? window.innerWidth / 2 : 0, y: typeof window !== "undefined" ? window.innerHeight / 2 : 0 };
  private reticleVisual: CursorVector = { ...this.pointerActual };
  private velocity: CursorVector = { x: 0, y: 0 };
  private lastPointer: CursorVector = { ...this.pointerActual };
  private pressOrigin: CursorVector = { ...this.pointerActual };
  private recoil = 0;
  private recoilVelocity = 0;
  private lockStrength = 0;
  private measuredFrameMs = 16.7;
  private lastTs = performance.now();
  private lastMoveTs = performance.now();
  private modality: CursorPointerModality = "mouse";
  private pointerInsideViewport = true;
  private documentVisible = typeof document === "undefined" ? true : !document.hidden;
  private pressing = false;
  private dragging = false;
  private overTextInput = false;
  private readonly registry = new CursorTargetRegistry();
  private readonly trailPool: TrailSample[] = Array.from({ length: 96 }, () => ({ x: 0, y: 0, life: 0, width: 1 }));
  private trailIndex = 0;

  constructor(config: Partial<CursorEngineConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  init(): void {
    setActiveCursorEngine(this);
  }

  attach(mount: HTMLElement): void {
    if (this.attached) this.detach();
    this.mount = mount;
    this.createDom();
    this.bindEvents();
    this.resizeCanvas();
    this.setDocumentCursor();
    this.attached = true;
    this.lastTs = performance.now();
    this.raf = requestAnimationFrame(this.tick);
  }

  detach(): void {
    cancelAnimationFrame(this.raf);
    this.unbindEvents();
    this.restoreDocumentCursor();
    this.registry.clear();
    this.mount?.replaceChildren();
    this.mount = null;
    this.reticle = null;
    this.canvas = null;
    this.ctx = null;
    this.debug = null;
    this.attached = false;
  }

  destroy(): void {
    this.detach();
    setActiveCursorEngine(null);
  }

  setEnabled(enabled: boolean): void {
    this.updateConfig({ enabled });
  }

  updateConfig(config: Partial<CursorEngineConfig>): void {
    const designChanged = config.cursorDesign !== undefined && config.cursorDesign !== this.config.cursorDesign;
    this.config = { ...this.config, ...config };
    this.setDocumentCursor();
    if (designChanged && this.reticle) {
      this.updateReticleSvg();
    }
  }

  publishTarget(target: Omit<Partial<CursorTarget>, "createdAt" | "hoverDwellMs"> & Pick<CursorTarget, "id" | "kind" | "source">): void {
    if (!this.config.enabled) return;
    this.registry.publish(target);
  }

  clearSourceTargets(source: CursorTargetSource): void {
    this.registry.clearSource(source);
  }

  private createDom(): void {
    if (!this.mount) return;
    this.mount.replaceChildren();
    Object.assign(this.mount.style, {
      position: "fixed",
      inset: "0",
      zIndex: "9999",
      pointerEvents: "none",
      overflow: "hidden",
      contain: "layout style paint",
    });

    this.canvas = document.createElement("canvas");
    Object.assign(this.canvas.style, {
      position: "absolute",
      inset: "0",
      width: "100%",
      height: "100%",
      pointerEvents: "none",
    });
    this.ctx = this.canvas.getContext("2d", { alpha: true });

    this.reticle = document.createElement("div");
    this.reticle.setAttribute("aria-hidden", "true");
    Object.assign(this.reticle.style, {
      position: "absolute",
      left: "0",
      top: "0",
      width: "42px",
      height: "42px",
      pointerEvents: "none",
      willChange: "transform, opacity, filter",
      transform: `translate3d(${this.reticleVisual.x - 21}px, ${this.reticleVisual.y - 21}px, 0)`,
      opacity: "0",
      transition: "opacity 90ms linear, filter 120ms linear",
    });
    this.updateReticleSvg();

    this.debug = document.createElement("div");
    Object.assign(this.debug.style, {
      position: "absolute",
      left: "8px",
      top: "8px",
      zIndex: "1",
      padding: "6px 8px",
      borderRadius: "6px",
      background: "rgba(0,0,0,.62)",
      color: "#fff",
      font: "11px/1.35 monospace",
      whiteSpace: "pre",
      pointerEvents: "none",
      display: this.config.debug || (typeof window !== "undefined" && window.localStorage && localStorage.getItem("wwv-debug-cursor") === "1") ? "block" : "none",
    });

    this.mount.append(this.canvas, this.reticle, this.debug);
  }

  private bindEvents(): void {
    window.addEventListener("pointermove", this.onPointerMove, { passive: true });
    window.addEventListener("pointerdown", this.onPointerDown, { passive: true });
    window.addEventListener("pointerup", this.onPointerUp, { passive: true });
    window.addEventListener("pointercancel", this.onPointerUp, { passive: true });
    window.addEventListener("pointerleave", this.onPointerLeave, { passive: true });
    window.addEventListener("pointerenter", this.onPointerEnter, { passive: true });
    window.addEventListener("blur", this.onWindowBlur);
    window.addEventListener("focus", this.onWindowFocus);
    window.addEventListener("resize", this.resizeCanvas);
    document.addEventListener("visibilitychange", this.onVisibilityChange);
    document.addEventListener("focusin", this.onFocusChange);
    document.addEventListener("focusout", this.onFocusChange);
  }

  private unbindEvents(): void {
    window.removeEventListener("pointermove", this.onPointerMove);
    window.removeEventListener("pointerdown", this.onPointerDown);
    window.removeEventListener("pointerup", this.onPointerUp);
    window.removeEventListener("pointercancel", this.onPointerUp);
    window.removeEventListener("pointerleave", this.onPointerLeave);
    window.removeEventListener("pointerenter", this.onPointerEnter);
    window.removeEventListener("blur", this.onWindowBlur);
    window.removeEventListener("focus", this.onWindowFocus);
    window.removeEventListener("resize", this.resizeCanvas);
    document.removeEventListener("visibilitychange", this.onVisibilityChange);
    document.removeEventListener("focusin", this.onFocusChange);
    document.removeEventListener("focusout", this.onFocusChange);
  }

  private onPointerMove = (event: PointerEvent): void => {
    const samples = typeof event.getCoalescedEvents === "function" ? event.getCoalescedEvents() : [event];
    for (const sample of samples) {
      this.samplePointer(sample.clientX, sample.clientY, event.pointerType);
    }
    this.overTextInput = isTextInputElement(event.target as Element | null);
    this.publishUiTarget(event.target as Element | null);
    this.setDocumentCursor();
  };

  private onPointerDown = (event: PointerEvent): void => {
    this.samplePointer(event.clientX, event.clientY, event.pointerType);
    this.pressing = true;
    this.dragging = false;
    this.pressOrigin = { ...this.pointerActual };
    this.recoilVelocity += 1.2;
  };

  private onPointerUp = (event: PointerEvent): void => {
    this.samplePointer(event.clientX, event.clientY, event.pointerType);
    this.pressing = false;
    this.dragging = false;
    this.registry.clearSource("system");
  };

  private onPointerLeave = (): void => {
    this.pointerInsideViewport = false;
    this.restoreDocumentCursor();
  };

  private onPointerEnter = (event: PointerEvent): void => {
    this.pointerInsideViewport = true;
    this.samplePointer(event.clientX, event.clientY, event.pointerType);
    this.reticleVisual = { ...this.pointerActual };
    this.setDocumentCursor();
  };

  private onWindowBlur = (): void => {
    this.pointerInsideViewport = false;
    this.pressing = false;
    this.dragging = false;
    this.registry.clear();
    this.restoreDocumentCursor();
  };

  private onWindowFocus = (): void => {
    this.pointerInsideViewport = true;
    this.setDocumentCursor();
  };

  private onVisibilityChange = (): void => {
    this.documentVisible = !document.hidden;
    if (!this.documentVisible) {
      this.pressing = false;
      this.dragging = false;
      this.registry.clear();
      this.restoreDocumentCursor();
    } else {
      this.reticleVisual = { ...this.pointerActual };
      this.setDocumentCursor();
    }
  };

  private onFocusChange = (): void => {
    this.overTextInput = isTextInputElement(document.activeElement);
    this.setDocumentCursor();
  };

  private samplePointer(x: number, y: number, pointerType: string): void {
    this.lastPointer = { ...this.pointerActual };
    this.pointerActual.x = x;
    this.pointerActual.y = y;
    this.reticleVisual.x = x;
    this.reticleVisual.y = y;
    this.lastMoveTs = performance.now();
    this.pointerInsideViewport = x >= 0 && y >= 0 && x <= window.innerWidth && y <= window.innerHeight;
    this.modality = pointerType === "pen" ? "pen" : pointerType === "touch" ? "touch" : "mouse";
    if (this.pressing && Math.hypot(x - this.pressOrigin.x, y - this.pressOrigin.y) > DRAG_THRESHOLD_PX) this.dragging = true;
  }

  private publishUiTarget(element: Element | null): void {
    const target = getInteractiveTarget(element);
    if (!target || isTextInputElement(target)) {
      this.registry.clearSource("ui");
      return;
    }
    const rect = target.getBoundingClientRect();
    this.registry.publish({
      id: target.dataset.cursorTarget || target.id || `${target.tagName.toLowerCase()}-${Math.round(rect.left)}-${Math.round(rect.top)}`,
      kind: "ui",
      source: "ui",
      rect,
      priority: 125,
      confidence: 0.95,
      expiresAt: performance.now() + 120,
    });
  }

  private tick = (ts: number): void => {
    const rawDt = ts - this.lastTs;
    const dtMs = clamp(rawDt || 16.7, 1, 50);
    const dt = dtMs / 1000;
    this.lastTs = ts;
    this.measuredFrameMs = this.measuredFrameMs * 0.9 + dtMs * 0.1;

    const frame = this.updateFrame(ts, dt, dtMs);
    this.render(frame);
    this.raf = requestAnimationFrame(this.tick);
  };

  private updateFrame(now: number, dt: number, dtMs: number): CursorFrameState {
    const profile = resolveCursorProfile(this.config);
    const diagnostic = validateCursorProfile(profile);
    const policy = deriveRuntimePolicy(this.config, profile, this.measuredFrameMs, this.documentVisible);
    const resolved = this.registry.resolve(this.pointerActual, now, dtMs);

    const intent: CursorIntent = {
      pressing: this.pressing,
      dragging: this.dragging,
      overTextInput: this.overTextInput,
      wantsNativeCursor: this.overTextInput || this.modality === "touch" || !this.pointerInsideViewport || !this.documentVisible,
      pointerInsideViewport: this.pointerInsideViewport,
      documentVisible: this.documentVisible,
      modality: this.modality,
    };

    if (this.pressing && now - this.lastMoveTs > WATCHDOG_MS) {
      this.pressing = false;
      this.dragging = false;
      this.lockStrength = 0;
      this.registry.clearSource("cesium");
    }

    const lockedTarget = resolved.lockedTarget;
    const targetPoint = lockedTarget?.screenPosition ?? (lockedTarget?.rect ? {
      x: lockedTarget.rect.left + lockedTarget.rect.width / 2,
      y: lockedTarget.rect.top + lockedTarget.rect.height / 2,
    } : null);

    const targetLockStrength = lockedTarget && policy.lockAssistEnabled && !intent.dragging
      ? clamp(1 - lockedTarget.distance / 120, 0, 1) * policy.lockAssistStrength
      : 0;
    this.lockStrength += (targetLockStrength - this.lockStrength) * (1 - Math.exp(-18 * dt));

    // The custom reticle must remain centered on the real pointer position.
    // Lock assist can still influence visual emphasis, but it must not push the pointer skin off the cursor.
    this.reticleVisual.x = this.pointerActual.x;
    this.reticleVisual.y = this.pointerActual.y;

    this.velocity.x = (this.pointerActual.x - this.lastPointer.x) / Math.max(dtMs, 1);
    this.velocity.y = (this.pointerActual.y - this.lastPointer.y) / Math.max(dtMs, 1);

    const omega = 22;
    const recoilAcceleration = -2 * omega * this.recoilVelocity - omega * omega * this.recoil;
    this.recoilVelocity += recoilAcceleration * dt;
    this.recoil += this.recoilVelocity * dt;
    this.recoil = clamp(this.recoil, 0, 1.2);

    if (policy.trailsEnabled && !intent.dragging && Math.hypot(this.velocity.x, this.velocity.y) > 0.35) {
      this.spawnTrail(policy);
    }

    let mode = this.resolveMode(intent, resolved.selectedTarget, lockedTarget, policy);
    if (diagnostic.blocking) mode = "disabled";

    return {
      mode,
      pointerActual: { ...this.pointerActual },
      reticleVisual: { ...this.reticleVisual },
      velocity: { ...this.velocity },
      selectedTarget: resolved.selectedTarget,
      lockedTarget,
      lockStrength: this.lockStrength,
      recoil: this.recoil,
      effectsEnabled: policy.visualEffectsAllowed,
      policy,
      intent,
      debugReason: policy.disabledReason ?? diagnostic.message,
    };
  }

  private resolveMode(intent: CursorIntent, selectedTarget: CursorTarget | null, lockedTarget: CursorTarget | null, policy: CursorRuntimePolicy): CursorMode {
    if (!this.config.enabled || policy.disabledReason === "engine disabled") return "disabled";
    if (this.config.reducedMotion) return "reducedMotion";
    if (intent.wantsNativeCursor) return "disabled";
    if (intent.dragging) return "drag";
    if (intent.pressing) return "press";
    if (lockedTarget) return "lock";
    if (selectedTarget) return "hover";
    return "idle";
  }

  private spawnTrail(policy: CursorRuntimePolicy): void {
    const sample = this.trailPool[this.trailIndex % this.trailPool.length];
    this.trailIndex += 1;
    sample.x = this.reticleVisual.x;
    sample.y = this.reticleVisual.y;
    sample.life = Math.max(8, policy.trailBudget);
    sample.width = 1 + clamp(Math.hypot(this.velocity.x, this.velocity.y) * 3, 0, 5);
  }

  private render(frame: CursorFrameState): void {
    const hidden = frame.intent.wantsNativeCursor || frame.mode === "disabled";
    const accent = this.config.accentColor || "#7de3c9";
    if (this.reticle) {
      const speed = clamp(Math.hypot(frame.velocity.x, frame.velocity.y), 0, 2.4);
      const scale = 1 + speed * 0.05 - frame.recoil * frame.policy.recoilStrength * 0.08 + frame.lockStrength * 0.08;
      const rotation = Math.atan2(frame.velocity.y, frame.velocity.x) || 0;
      this.reticle.style.opacity = hidden ? "0" : frame.mode === "idle" ? "0.82" : "1";
      const centeredX = frame.reticleVisual.x - 21;
      const centeredY = frame.reticleVisual.y - 21;
      this.reticle.style.transform = `translate3d(${centeredX}px, ${centeredY}px, 0) rotate(${rotation * 0.08}rad) scale(${scale})`;
      this.reticle.style.filter = `drop-shadow(0 0 ${8 + frame.lockStrength * 18}px ${cssColorWithAlpha(accent, 0.34 + frame.lockStrength * 0.24)})`;
      this.reticle.style.color = accent;
      const ring = this.reticle.querySelector("[data-cursor-ring]");
      if (ring) ring.setAttribute("stroke", cssColorWithAlpha(accent, 0.76 + frame.lockStrength * 0.22));
    }

    this.renderCanvas(frame, accent);

    if (this.debug && (this.config.debug || (typeof window !== "undefined" && window.localStorage && localStorage.getItem("wwv-debug-cursor") === "1"))) {
      this.debug.style.display = "block";
      this.debug.textContent = [
        `mode: ${frame.mode}`,
        `target: ${frame.selectedTarget?.id ?? "none"}`,
        `locked: ${frame.lockedTarget?.id ?? "none"}`,
        `velocity: ${frame.velocity.x.toFixed(2)},${frame.velocity.y.toFixed(2)}`,
        `lock: ${frame.lockStrength.toFixed(2)} recoil: ${frame.recoil.toFixed(2)}`,
        `budget: t${frame.policy.trailBudget}/p${frame.policy.particleBudget}`,
        `reason: ${frame.debugReason ?? "nominal"}`,
      ].join("\n");
    }
  }

  private renderCanvas(frame: CursorFrameState, accent: string): void {
    if (!this.canvas || !this.ctx) return;
    const ctx = this.ctx;
    const dpr = window.devicePixelRatio || 1;
    ctx.clearRect(0, 0, this.canvas.width / dpr, this.canvas.height / dpr);
    if (!frame.effectsEnabled || frame.intent.wantsNativeCursor) return;

    for (const sample of this.trailPool) {
      if (sample.life <= 0) continue;
      const alpha = clamp(sample.life / Math.max(1, frame.policy.trailBudget), 0, 1);
      ctx.beginPath();
      ctx.fillStyle = cssColorWithAlpha(accent, alpha * 0.24);
      ctx.shadowColor = cssColorWithAlpha(accent, alpha * 0.38);
      ctx.shadowBlur = 12 * alpha;
      ctx.arc(sample.x, sample.y, sample.width * alpha, 0, Math.PI * 2);
      ctx.fill();
      sample.life -= 1 + (1 - resolveCursorProfile(this.config).bleedRate) * 4;
    }

    if (frame.lockedTarget && frame.lockStrength > 0.1) {
      const point = frame.lockedTarget.screenPosition ?? (frame.lockedTarget.rect ? {
        x: frame.lockedTarget.rect.left + frame.lockedTarget.rect.width / 2,
        y: frame.lockedTarget.rect.top + frame.lockedTarget.rect.height / 2,
      } : null);
      if (point) {
        ctx.beginPath();
        ctx.strokeStyle = cssColorWithAlpha(accent, frame.lockStrength * 0.26);
        ctx.lineWidth = 1;
        ctx.arc(point.x, point.y, 18 + frame.lockStrength * 10, 0, Math.PI * 2);
        ctx.stroke();
      }
    }
  }

  private resizeCanvas = (): void => {
    if (!this.canvas || !this.ctx) return;
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = Math.max(1, Math.floor(window.innerWidth * dpr));
    this.canvas.height = Math.max(1, Math.floor(window.innerHeight * dpr));
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  };

  private setDocumentCursor(): void {
    if (!this.config.enabled || this.overTextInput || !this.pointerInsideViewport || !this.documentVisible || this.modality === "touch") {
      this.restoreDocumentCursor();
      return;
    }
    document.documentElement.style.cursor = "none";
    document.body.style.cursor = "none";
  }

  private restoreDocumentCursor(): void {
    document.documentElement.style.cursor = "";
    document.body.style.cursor = "";
  }

  private updateReticleSvg(): void {
    if (!this.reticle) return;
    const design = this.config.cursorDesign || "reticle-v1";
    let svgContent = "";

    switch (design) {
      case "dot-trail":
        svgContent = `
          <svg width="42" height="42" viewBox="0 0 42 42" fill="none" xmlns="http://www.w3.org/2000/svg">
            <circle cx="21" cy="21" r="4.5" fill="currentColor"/>
            <circle cx="13" cy="21" r="2.5" fill="currentColor" opacity="0.35"/>
            <circle cx="29" cy="21" r="2.5" fill="currentColor" opacity="0.35"/>
          </svg>
        `;
        break;
      case "comet-tail":
        svgContent = `
          <svg width="42" height="42" viewBox="0 0 42 42" fill="none" xmlns="http://www.w3.org/2000/svg">
            <defs>
