import type { DataBusEvents } from "@/core/plugins/PluginTypes";

type EventHandler<T> = (data: T) => void;

/**
 * Typed event bus for cross-component and cross-plugin communication.
 * Singleton pattern ΓÇö import and use directly.
 */
class DataBus {
    private listeners: Map<string, Set<EventHandler<unknown>>> = new Map();
    public history: Array<{ event: string; timestamp: number; data: any }> = [];

    on<K extends keyof DataBusEvents>(
        event: K,
        handler: EventHandler<DataBusEvents[K]>
    ): () => void {
        if (!this.listeners.has(event)) {
            this.listeners.set(event, new Set());
        }
        this.listeners.get(event)!.add(handler as EventHandler<unknown>);

        // Return unsubscribe function
        return () => {
            this.listeners.get(event)?.delete(handler as EventHandler<unknown>);
        };
    }

    emit<K extends keyof DataBusEvents>(event: K, data: DataBusEvents[K]): void {
        // Record event in history log
        this.history.unshift({ event, timestamp: Date.now(), data });
        if (this.history.length > 50) {
            this.history.pop();
        }

        this.listeners.get(event)?.forEach((handler) => {
            try {
                handler(data);
            } catch (err) {
                console.error(`[DataBus] Error in handler for "${event}":`, err);
            }
        });
    }

    off<K extends keyof DataBusEvents>(
        event: K,
        handler: EventHandler<DataBusEvents[K]>
    ): void {
        this.listeners.get(event)?.delete(handler as EventHandler<unknown>);
    }

    removeAllListeners(event?: keyof DataBusEvents): void {
        if (event) {
            this.listeners.delete(event);
        } else {
            this.listeners.clear();
        }
    }
}

export const dataBus = new DataBus();

/**
 * Manages polling intervals for each plugin.
 * Supports start, stop, pause, and exponential backoff on errors.
 */
import { useStore } from "@/core/state/store";

interface PollingTask {
    pluginId: string;
    intervalMs: number;
    callback: () => Promise<void>;
    timerId: ReturnType<typeof setTimeout> | null;
    isPaused: boolean;
    errorCount: number;
    maxBackoff: number;
}

class PollingManager {
    private tasks: Map<string, PollingTask> = new Map();

    constructor() {
        this.initStoreSubscription();
    }

    private initStoreSubscription() {
        // Subscribe to store changes to update intervals on the fly
        useStore.subscribe((state, prevState) => {
            if (state.dataConfig.pollingIntervals === prevState.dataConfig.pollingIntervals) return;

            this.tasks.forEach((task, pluginId) => {
                const newInterval = state.dataConfig.pollingIntervals[pluginId];
                if (newInterval && newInterval !== task.intervalMs) {
                    console.log(`[PollingManager] Updating interval for ${pluginId} to ${newInterval}ms`);
                    task.intervalMs = newInterval;
                    // If already running, restart with new interval
                    if (task.timerId) {
                        this.stop(pluginId);
                        this.start(pluginId);
                    }
                }
            });
        });
    }

    register(
        pluginId: string,
        intervalMs: number,
        callback: () => Promise<void>
    ): void {
        const storeInterval = useStore.getState().dataConfig.pollingIntervals[pluginId];
        this.tasks.set(pluginId, {
            pluginId,
            intervalMs: storeInterval || intervalMs,
            callback,
            timerId: null,
            isPaused: false,
            errorCount: 0,
            maxBackoff: 60000, // max 60s backoff
        });
    }

    start(pluginId: string): void {
        const task = this.tasks.get(pluginId);
        if (!task || task.timerId) return;

        const runNext = async () => {
            if (task.isPaused || !task.timerId) return;

            try {
                await task.callback();
                task.errorCount = 0;
            } catch (err) {
                task.errorCount++;
                console.warn(
                    `[PollingManager] Error in ${pluginId} (attempt ${task.errorCount}):`,
                    err
                );
            }

            // Schedule the next execution if not stopped or paused during callback execution
            if (task.timerId && !task.isPaused) {
                const effectiveInterval = this.getEffectiveInterval(task);
                if (effectiveInterval > 0) {
                    task.timerId = setTimeout(runNext, effectiveInterval);
                } else {
                    task.timerId = "ws-push-only" as any;
                }
            }
        };

        const initialInterval = this.getEffectiveInterval(task);
        if (initialInterval > 0) {
            // Set a temporary timerId to block concurrent start calls and allow stop/pause to interrupt
            task.timerId = setTimeout(runNext, 0);
        } else {
            task.timerId = "ws-push-only" as any;
        }
    }

    stop(pluginId: string): void {
        const task = this.tasks.get(pluginId);
        if (!task || !task.timerId) return;
        if (task.timerId !== ("ws-push-only" as any)) {
            clearTimeout(task.timerId);
        }
        task.timerId = null;
        task.errorCount = 0;
    }

    pause(pluginId: string): void {
        const task = this.tasks.get(pluginId);
        if (task) {
            task.isPaused = true;
            if (task.timerId && task.timerId !== ("ws-push-only" as any)) {
                clearTimeout(task.timerId);
                task.timerId = null;
            }
        }
    }

    resume(pluginId: string): void {
        const task = this.tasks.get(pluginId);
        if (task) {
            task.isPaused = false;
            // Restart with fresh interval if not running
            if (!task.timerId) {
                this.start(pluginId);
            }
        }
    }

    stopAll(): void {
        this.tasks.forEach((_, pluginId) => this.stop(pluginId));
    }

    unregister(pluginId: string): void {
        this.stop(pluginId);
        this.tasks.delete(pluginId);
    }

    private getEffectiveInterval(task: PollingTask): number {
        if (task.errorCount === 0) return task.intervalMs;
        // Exponential backoff: interval * 2^errorCount, capped at maxBackoff
        const backoff = Math.min(
            task.intervalMs * Math.pow(2, task.errorCount),
            task.maxBackoff
        );
        return backoff;
    }
}

export const pollingManager = new PollingManager();

/**
 * SmartFetcher
 * Encapsulates a robust, tiered fetching strategy to bypass CORS and handle large payloads.
 *
 * Strategy:
 * 1. Direct fetch (Browser GET)
 * 2. Public Proxy check (Browser HEAD via corsproxy)
 *    -> If < 1MB, Public Proxy GET
 *    -> If > 1MB or check fails, Local Server Proxy GET
 */

export class SmartFetcher {
    /**
     * Attempts to fetch JSON data from a cross-origin URL.
     * Strategy:
     * 1. Direct fetch (Browser GET)
     * 2. Local Server Proxy (Last resort, handles CORS or large payloads)
     */
    static async fetchJson(url: string): Promise<any> {
        // Step 1: Try Direct Fetch (Fastest)
        try {
            const res = await fetch(url);
            if (res.ok) {
                return await this.parseResponse(res);
            }
        } catch (e) {
            // Direct fetch failed (likely CORS). Fall through to Local Server Proxy.
        }

        // Step 2: Local Server Proxy
        const localProxyUrl = `/api/camera/proxy?url=${encodeURIComponent(url)}`;
        const localRes = await fetch(localProxyUrl);
        if (!localRes.ok) {
            throw new Error(`[SmartFetcher] Local proxy failed to load URL: ${url} (Status: ${localRes.status})`);
        }

        return await localRes.json();
    }

    private static async parseResponse(res: Response): Promise<any> {
        // Read as text to support both direct JSON HTTP responses and file download streams
        const text = await res.text();
        try {
            return JSON.parse(text);
        } catch (e) {
            throw new Error("Target URL did not return a valid JSON format.");
        }
    }
}

import type { WsStreamPayload, GeoEntity } from "../../wwv-sdk/index";
import { dataBus } from "./DataBus";
import { pluginManager } from "../plugins/PluginManager";
import { useStore } from "../state/store";
import { ticketAuthEnabledForPlugin } from "../edition";
import type { PluginTicket } from "../../wwv-sdk/index";
import { useDiagnosticsStore } from "../../store/diagnosticsStore";

async function fetchPluginTicket(pluginId: string): Promise<PluginTicket> {
  const res = await fetch(`/api/auth/ticket?pluginId=${encodeURIComponent(pluginId)}`);
  if (!res.ok) throw new Error(`[WSClient] Ticket fetch failed (${res.status}) for ${pluginId}`);
  const data = await res.json() as { token?: string };
  if (!data.token) throw new Error(`[WSClient] Ticket response missing token for ${pluginId}`);
  return data.token as PluginTicket;
}

interface EngineConnection {
  ws: WebSocket | null;
  reconnectTimer: NodeJS.Timeout | null;
  subscriptions: Set<string>;
  /** Grace period timer ΓÇö closes the connection if no plugins remain subscribed */
  cleanupTimer: NodeJS.Timeout | null;
  /** Backoff attempt counter ΓÇö resets after a stable connection (>5s open) */
  reconnectAttempts: number;
  /** Timer that resets the backoff counter once a connection has been stable */
  stableConnectionTimer: NodeJS.Timeout | null;
  /** True while waiting for the server's welcome after sending an auth message */
  awaitingWelcome: boolean;
  /** Closes the connection if the server doesn't send welcome within 3s */
  authTimeoutTimer: NodeJS.Timeout | null;
}

const RECONNECT_BASE_MS = 5000;
const RECONNECT_MAX_MS = 60000; // Cap at 1 minute
const RECONNECT_JITTER_MS = 4000;
const STABLE_CONNECTION_MS = 5000; // Reset backoff after 5s of stable connection
const CLEANUP_GRACE_MS = 30000;

/** Normalizes underscore-based pluginIds to kebab-case (e.g. `my_plugin` ΓåÆ `my-plugin`). */
function normalizePluginId(id: string): string {
  return id.replace(/_/g, "-");
}

class WebSocketClient {
  private engines = new Map<string, EngineConnection>();

  private getOrCreateEngine(engineUrl: string): EngineConnection {
    let engine = this.engines.get(engineUrl);
    if (!engine) {
      engine = {
        ws: null,
        reconnectTimer: null,
        subscriptions: new Set(),
        cleanupTimer: null,
        reconnectAttempts: 0,
        stableConnectionTimer: null,
        awaitingWelcome: false,
        authTimeoutTimer: null,
      };
      this.engines.set(engineUrl, engine);
    }
    return engine;
  }

  private connectEngine(engineUrl: string) {
    const engine = this.getOrCreateEngine(engineUrl);

    if (engine.ws && (engine.ws.readyState === WebSocket.CONNECTING || engine.ws.readyState === WebSocket.OPEN)) {
      return;
    }

    const wsStart = performance.now();
    engine.ws = new WebSocket(engineUrl);

    engine.ws.onopen = () => {
      console.debug(`[WSClient] ≡ƒƒó Connected to ${engineUrl}. WS Handshake took ${(performance.now() - wsStart).toFixed(2)}ms`);
      // Only reset backoff if the connection stays open for a non-trivial time ΓÇö
      // an immediate close (e.g. server-side rejection) shouldn't be treated as success.
      if (engine.stableConnectionTimer) clearTimeout(engine.stableConnectionTimer);
      engine.stableConnectionTimer = setTimeout(() => {
        engine.reconnectAttempts = 0;
      }, STABLE_CONNECTION_MS);

      // Check whether any subscription on this engine requires ticket auth.
      const ticketPlugin = [...engine.subscriptions].find((id) => ticketAuthEnabledForPlugin(id));
      if (ticketPlugin) {
        engine.awaitingWelcome = true;
        fetchPluginTicket(ticketPlugin)
          .then((ticket) => {
            this.send(engine, { type: "auth", v: 1, token: ticket });
            // 3s timeout ΓÇö if the server doesn't send welcome, close and trigger reconnect.
            engine.authTimeoutTimer = setTimeout(() => {
              if (engine.awaitingWelcome) {
                console.warn(`[WSClient] Auth timeout waiting for welcome from ${engineUrl}. Closing to reconnect.`);
                engine.ws?.close();
              }
            }, 3000);
          })
          .catch((err: unknown) => {
            console.error(`[WSClient] Failed to get ticket for ${ticketPlugin}:`, err instanceof Error ? err.message : err);
            engine.ws?.close();
          });
      } else {
        // No ticket auth required ΓÇö subscribe immediately.
        for (const pluginId of engine.subscriptions) {
          this.send(engine, { action: "subscribe", pluginId });
        }
      }
    };

    engine.ws.onmessage = (event) => {
      try {
        const msgTime = performance.now();
        console.debug(`[WSClient] ≡ƒôÑ Received raw message at +${(msgTime - wsStart).toFixed(2)}ms from start:`, event.data.substring(0, 150) + (event.data.length > 150 ? '...' : ''));
        const data = JSON.parse(event.data);

        if (data.type === "welcome") {
          console.debug(`[WSClient] ≡ƒæï Engine ${engineUrl} serves: ${data.plugins?.join(", ")}`);
          if (engine.awaitingWelcome) {
            engine.awaitingWelcome = false;
            if (engine.authTimeoutTimer) { clearTimeout(engine.authTimeoutTimer); engine.authTimeoutTimer = null; }
            for (const pluginId of engine.subscriptions) {
              this.send(engine, { action: "subscribe", pluginId });
            }
          }
          return;
        }

        if (data.type === "data" && data.pluginId && data.payload) {
          this.handleDataMessage(data as WsStreamPayload);
        }
      } catch (err) {
        console.error("[WSClient] Error parsing message:", err);
      }
    };

    engine.ws.onerror = () => {
      const errMsg = `Connection to ${engineUrl} failed. Retrying in background...`;
      console.warn(`[WSClient] ${errMsg}`);
      try {
        useDiagnosticsStore.getState().add({
          level: 'error',
          message: `[WSClient] ${errMsg}`,
          suggestion: 'Ensure that the local backend service or engine is reachable at the specified address, or check for network connectivity issues.',
          metadata: { engineUrl }
        });
      } catch (e) {
        // ignore diagnostics errors
      }
    };

    engine.ws.onclose = () => {
      engine.ws = null;
      engine.awaitingWelcome = false;
      if (engine.authTimeoutTimer) { clearTimeout(engine.authTimeoutTimer); engine.authTimeoutTimer = null; }
      if (engine.stableConnectionTimer) {
        clearTimeout(engine.stableConnectionTimer);
        engine.stableConnectionTimer = null;
      }
      if (engine.reconnectTimer) clearTimeout(engine.reconnectTimer);
      // Only reconnect if there are still active subscriptions
      if (engine.subscriptions.size > 0) {
        // Exponential backoff with jitter to prevent thundering herd on engine restart.
        // 5s -> 10s -> 20s -> 40s -> 60s (cap), plus ┬▒4s of jitter so simultaneous
        // sessions don't all reconnect at the same instant.
        const expDelay = Math.min(
          RECONNECT_BASE_MS * Math.pow(2, engine.reconnectAttempts),
          RECONNECT_MAX_MS
        );
        const delay = expDelay + Math.random() * RECONNECT_JITTER_MS;
        engine.reconnectAttempts++;
        const reconnectMessage = `Disconnected from ${engineUrl}. Reconnecting in ${Math.round(delay / 1000)}s (attempt ${engine.reconnectAttempts})...`;
        console.warn(`[WSClient] ${reconnectMessage}`);
        
        try {
          useDiagnosticsStore.getState().add({
            level: 'warning',
            message: `[WSClient] ${reconnectMessage}`,
            suggestion: 'Verify that the engine server is running at the configured URL and that there are no local firewall or routing blockers.',
            metadata: { engineUrl, reconnectAttempts: engine.reconnectAttempts, delay }
          });
        } catch (e) {
          // ignore diagnostics errors
        }

        engine.reconnectTimer = setTimeout(() => this.connectEngine(engineUrl), delay);
      }
    };
  }

  private handleDataMessage(data: WsStreamPayload) {
    const pluginId = normalizePluginId(data.pluginId!);
    const plugin = pluginManager.getPlugin(pluginId)?.plugin;
    let finalEntities = data.payload as GeoEntity[];
    const existingEntities = useStore.getState().entitiesByPlugin[pluginId] || [];

    if (plugin && typeof (plugin as any).mapWebsocketPayload === "function") {
      finalEntities = (plugin as any).mapWebsocketPayload(data.payload, existingEntities);
    } else if (!Array.isArray(data.payload)) {
      console.warn(`[WsClient] Payload for ${pluginId} is an object but no mapWebsocketPayload exists. Ignoring.`);
      return;
    } else {
      finalEntities = finalEntities.map((e) => ({
        ...e,
        timestamp: new Date(e.timestamp || Date.now()),
      }));
    }

    console.debug(`[WSClient] ≡ƒöä Dispatching ${finalEntities.length} entities for ${pluginId} to DataBus`);

    dataBus.emit("dataUpdated", {
      pluginId,
      entities: finalEntities,
    });
  }

  private send(engine: EngineConnection, msg: any) {
    if (engine.ws && engine.ws.readyState === WebSocket.OPEN) {
      engine.ws.send(JSON.stringify(msg));
    }
  }

  public subscribe(pluginId: string, engineUrl: string) {
    console.debug(`[WSClient] ≡ƒôí Subscribing to ${pluginId} at ${engineUrl}`);
    const engine = this.getOrCreateEngine(engineUrl);

    // Cancel any pending cleanup
    if (engine.cleanupTimer) {
      clearTimeout(engine.cleanupTimer);
      engine.cleanupTimer = null;
    }

    engine.subscriptions.add(pluginId);
    this.connectEngine(engineUrl);
    this.send(engine, { action: "subscribe", pluginId });
  }

  public unsubscribe(pluginId: string, engineUrl: string) {
    const engine = this.engines.get(engineUrl);
    if (!engine) return;

    engine.subscriptions.delete(pluginId);
    this.send(engine, { action: "unsubscribe", pluginId });

    // If no more subscriptions for this engine, schedule cleanup
    if (engine.subscriptions.size === 0) {
      engine.cleanupTimer = setTimeout(() => {
        if (engine.subscriptions.size === 0) {
          console.log(`[WSClient] No subscriptions remain for ${engineUrl}. Closing connection.`);
          if (engine.reconnectTimer) clearTimeout(engine.reconnectTimer);
          if (engine.stableConnectionTimer) clearTimeout(engine.stableConnectionTimer);
          if (engine.authTimeoutTimer) { clearTimeout(engine.authTimeoutTimer); engine.authTimeoutTimer = null; }
          engine.ws?.close();
          this.engines.delete(engineUrl);
        }
      }, CLEANUP_GRACE_MS);
    }
  }

  public printConnections() {
    const table: any[] = [];
    this.engines.forEach((engine, url) => {
      table.push({
        'Engine URL': url,
        Status: engine.ws ? ['CONNECTING', 'OPEN', 'CLOSING', 'CLOSED'][engine.ws.readyState] || 'UNKNOWN' : 'DISCONNECTED',
        'Plugins Subscribed': Array.from(engine.subscriptions).join(", ") || "(None)",
      });
    });
    console.groupCollapsed("[WSClient] Active Engine Connections Matrix");
    console.table(table);
    console.groupEnd();
  }
}

