/** Interval (in frames) between horizon-culling passes for static entities. */
const STATIC_HORIZON_INTERVAL = 30;

// ΓöÇΓöÇ DOD: Pre-sorted entity buckets ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
interface AnimationBuckets {
    dynamic: AnimatableItem[];
    staticBatch: AnimatableItem[];
}

let cachedBuckets: AnimationBuckets = { dynamic: [], staticBatch: [] };
let bucketSourceRef: AnimatableItem[] = [];

/** Rebuild buckets when the animatables array identity changes. */
function ensureBuckets(animatables: AnimatableItem[]): AnimationBuckets {
    if (animatables === bucketSourceRef && (cachedBuckets.dynamic.length + cachedBuckets.staticBatch.length > 0)) {
        return cachedBuckets;
    }
    bucketSourceRef = animatables;
    const dynamic: AnimatableItem[] = [];
    const staticBatch: AnimatableItem[] = [];
    for (let i = 0; i < animatables.length; i++) {
        const {speed} = animatables[i].entity;
        (speed !== undefined && speed > 0) ? dynamic.push(animatables[i]) : staticBatch.push(animatables[i]);
    }
    cachedBuckets = { dynamic, staticBatch };
    return cachedBuckets;
}

/**
 * Creates the per-frame update function.
 * DOD: Entities are split into dynamic/static buckets so each
 * sub-loop processes homogeneous data without branching on type.
 */
export function createUpdateLoop(
    viewer: CesiumViewer,
    animatablesRef: { current: AnimatableItem[] },
    hoveredEntityIdRef: React.MutableRefObject<string | null>
): () => void {
    let frameCount = 0;
    let prevSelectedId: string | null = null;
    let prevHoveredId: string | null = null;
    let prevAnyExpanded = false;
    let prevStackVersion = -1;

    let lastPerfTime = performance.now();
    let smoothedSimMs = Date.now();
    let lastStoreUpdatePerf = lastPerfTime;
    let performanceOrigin = Date.now() - lastPerfTime;

    return () => {
        if (!viewer || viewer.isDestroyed()) return;

        const state = useStore.getState();
        const nowPerf = performance.now();
        const deltaPerf = nowPerf - lastPerfTime;
        lastPerfTime = nowPerf;

        let nowMs: number;
        if (state.isPlaybackMode) {
            const storeTimeMs = state.currentTime.getTime();

            // If the store time jumped (user scrubbing) or we lost sync:
            if (Math.abs(smoothedSimMs - storeTimeMs) > 100) {
                smoothedSimMs = storeTimeMs;
            } else if (state.isPlaying) {
                smoothedSimMs += deltaPerf * state.playbackSpeed;

                if (smoothedSimMs >= state.timeRange.end.getTime()) {
                    smoothedSimMs = state.timeRange.end.getTime();
                    state.setPlaying(false);
                }
            }
            nowMs = smoothedSimMs;

            // Throttle store updates to ~15fps (66ms) so React UI re-renders don't overload CPU
            if (state.isPlaying && (nowPerf - lastStoreUpdatePerf > 66)) {
                lastStoreUpdatePerf = nowPerf;
                state.setCurrentTime(new Date(smoothedSimMs));
            }
        } else {
            // Protect against Date.now() 15ms coarse OS resolution jitter!
            // We use high-res continuous timeline mapping, but re-anchor
            // if the system clock drifts significantly over long standby periods.
            const systemNow = Date.now();
            const perfNowUnix = performanceOrigin + nowPerf;
            if (Math.abs(systemNow - perfNowUnix) > 50) {
                performanceOrigin = systemNow - nowPerf;
            }
            nowMs = performanceOrigin + nowPerf;
            smoothedSimMs = nowMs;
        }

        const animatables = animatablesRef.current;
        const { labels: labelsCollection, billboards } = getCollections(viewer);

        // Always run stack animation tick so that ghost hubs can be cleaned up
        // even if the user toggles all layers off!
        let isAnimatingStack = false;
        if (billboards) {
            isAnimatingStack = tickStackAnimation(labelsCollection ?? null, billboards);
        }

        if (animatables.length === 0) {
            if (isAnimatingStack || state.isPlaybackMode) viewer.scene.requestRender();
            return;
        }

        const camPos = viewer.camera.positionWC;
        const camDistSqr = Cartesian3.magnitudeSquared(camPos);
        if (camDistSqr <= R2) return;

        const Dh = Math.sqrt(camDistSqr - R2);
        const frame = frameCount++;
        window._wwvFrameCount = frame;
        const isStaticCullFrame = frame % STATIC_HORIZON_INTERVAL === 0;
        const selectedId = state.selectedEntity?.id ?? null;
        const hoveredId = hoveredEntityIdRef.current;
        const anyExpanded = isAnyStackExpanded();

        let forceFullPass = false;

        const currentStackVersion = getStackStateVersion();
        if (currentStackVersion !== prevStackVersion) {
            forceFullPass = true;
            prevStackVersion = currentStackVersion;
        }

        if (anyExpanded !== prevAnyExpanded) {
            forceFullPass = true;
            prevAnyExpanded = anyExpanded;
        }

        const { dynamic, staticBatch } = ensureBuckets(animatables);

        // Pass 1: Dynamic entities ΓÇö every frame
        for (let i = 0; i < dynamic.length; i++) {
            const isFaded = anyExpanded && !isEntityInExpandedStack(dynamic[i].entity.id);
            processEntity(dynamic[i], camPos, Dh, nowMs, selectedId, hoveredId, labelsCollection, true, i, isFaded);
        }

        // Pass 2: Static entities ΓÇö cull frames only (unless interactive)
        if (isStaticCullFrame || forceFullPass) {
            for (let i = 0; i < staticBatch.length; i++) {
                const isFaded = anyExpanded && !isEntityInExpandedStack(staticBatch[i].entity.id);
                processEntity(staticBatch[i], camPos, Dh, nowMs, selectedId, hoveredId, labelsCollection, false, i, isFaded);
            }
        } else {
            for (let i = 0; i < staticBatch.length; i++) {
                const {id} = staticBatch[i].entity;
                if (id === selectedId || id === hoveredId || id === prevSelectedId || id === prevHoveredId) {
                    const isFaded = anyExpanded && !isEntityInExpandedStack(id);
                    processEntity(staticBatch[i], camPos, Dh, nowMs, selectedId, hoveredId, labelsCollection, false, i, isFaded);
                }
            }
        }

        prevSelectedId = selectedId;
        prevHoveredId = hoveredId;

        if (isAnimatingStack || dynamic.length > 0 || state.isPlaybackMode) {
            viewer.scene.requestRender();
        }
    };
}

function processEntity(
    item: AnimatableItem,
camPos: Cartesian3,
Dh: number,
nowMs: number,
    selectedId: string | null,
hoveredId: string | null,
labelsCollection: any,
isDynamic: boolean,
    entityIndex: number,
isFaded: boolean
): void {
    const { primitive, entity, posRef } = item;
    if (!primitive || primitive.isDestroyed?.()) return;

    const isSelected = selectedId === entity.id;
    const isHovered = hoveredId === entity.id;

    if (isDynamic && entity.timestamp && entity.heading !== undefined) {
        extrapolatePosition(item, nowMs);
        if (item.options.type === "model") updateModelTransform(item, item.posRef, entity.heading);
        // Do NOT re-assign item.polylinePrimitive.positions here at 60fps.
        // It triggers a massive synchronous WebGL vertex buffer rewrite in Cesium.
        // This is handled at 4Hz in useTrailRendering.ts instead.
    }

    const showLabel = isSelected || isHovered;

    const applyLabel = () => {
        if (showLabel) {
            if (!item.labelPrimitive && labelsCollection) createLabel(item, labelsCollection);
            if (item.labelPrimitive && !item.labelPrimitive.isDestroyed?.()) {
                if (item.labelPrimitive.show !== true) item.labelPrimitive.show = true;
                const fill = isSelected ? HIGHLIGHT_COLOR_SELECTED : Color.WHITE;
                if (!Color.equals(item.labelPrimitive.fillColor, fill)) item.labelPrimitive.fillColor = fill;
            }
        } else {
            hideLabel(item, labelsCollection);
        }
    };

    if (item._modelPromoted) {
        if (item.promotedModel && !item.promotedModel.isDestroyed?.()) {
            if (isSelected && item.promotedModel.silhouetteSize !== 2) item.promotedModel.silhouetteSize = 2;
            else if (isHovered && item.promotedModel.silhouetteSize !== 1) item.promotedModel.silhouetteSize = 1;
            else if (!isSelected && !isHovered && item.promotedModel.silhouetteSize !== 0) item.promotedModel.silhouetteSize = 0;
        }
        applyLabel();
        return;
    }

    if (!item.options.disableManualHorizonCulling || primitive.disableDepthTestDistance === Number.POSITIVE_INFINITY) {
        // Mathematical horizon culling scaled to WGS84 ellipsoid
        // Transforms the ellipsoid to a unit sphere, making culling 100% precise at all latitudes.
        const px = posRef.x * (1.0 / 6378137.0);
        const py = posRef.y * (1.0 / 6378137.0);
        const pz = posRef.z * (1.0 / 6356752.314245);

        const cx = camPos.x * (1.0 / 6378137.0);
        const cy = camPos.y * (1.0 / 6378137.0);
        const cz = camPos.z * (1.0 / 6356752.314245);

        item._occluded = (px * cx + py * cy + pz * cz) <= 1.0;

        if (item._occluded) {
            if (primitive.show !== false) primitive.show = false;
            hideLabel(item, labelsCollection);
            return;
        }
    }

    // Force rendering pos to hub if clustered, so pixelOffset originates from the hub
    const targetPos = getEntityTargetPosition(entity.id) ?? posRef;
    if (primitive.position && !Cartesian3.equals(primitive.position, targetPos)) {
        primitive.position = targetPos;
        if (item.labelPrimitive && !item.labelPrimitive.isDestroyed?.()) {
            item.labelPrimitive.position = targetPos;
        }
    }

    // Delegate visibility to stackAnimation if the entity is clustered
    // This prevents the data points from flickering over the cluster badge.
    if (!isEntityClustered(entity.id) && primitive.show !== true) {
        primitive.show = true;
    }

    // Highlight styling handles fallback billboard vs point directly inside applyHighlight
    applyHighlight(item, isSelected, isHovered, isFaded);

    applyLabel();
}

/** Hide label to save render time, but do NOT remove it. Creating/Removing labels triggers massive WebGL buffer rewrites. */
function hideLabel(item: AnimatableItem, labelsCollection: any): void {
    if (!item.labelPrimitive || item.labelPrimitive.isDestroyed?.()) return;
    if (item.labelPrimitive.show !== false) item.labelPrimitive.show = false;
    // We intentionally do NOT call removeLabel here. Let Cesium use the 'show' boolean
    // to skip rendering, which is O(1).
}

import {
    Cartesian3, Cartographic, Color, Ellipsoid,
    PointPrimitiveCollection, BillboardCollection, LabelCollection, PolylineCollection,
    VerticalOrigin, DistanceDisplayCondition, NearFarScalar, HeightReference,
} from "cesium";
import type { Viewer as CesiumViewer } from "cesium";
import type { GeoEntity, CesiumEntityOptions } from "@/core/plugins/PluginTypes";
import { globalChunkedProcessor } from "./ChunkedProcessor";
import {
    scratchPosition, getEntityColor, getCachedColor,
    markAnimatablesDirty, getStableAnimatables,
} from "./renderCaches";
import {
 updateExistingItem, createNewItem, cleanupRemovedEntities, getDefaultDotIcon
} from "./primitiveOps";
import { rebuildStacks, calculateGridSizeDegrees } from "./StackManager";

// Re-export for existing consumers
export {
 getEntityColor, getCachedColor, markAnimatablesDirty, getStableAnimatables
} from "./renderCaches";

export interface AnimatableItem {
    primitive: any;
    labelPrimitive?: any;
    entity: GeoEntity;
    posRef: Cartesian3;
    options: CesiumEntityOptions;
    basePosition?: Cartesian3;
    velocityVector?: Cartesian3;
    baseColor?: Color;
    baseOutlineColor?: Color;
    lastHighlightState?: 'normal' | 'hovered' | 'selected';
    /** Set by LOD hook ΓÇö when true, billboard is hidden because a 3D model replaced it */
    _modelPromoted?: boolean;
    /** Set by AnimationLoop - true if hidden by mathematical horizon culling */
    _occluded?: boolean;
    polylinePrimitive?: any; // Reference to the trail polyline in the collection
    trailPositions?: Cartesian3[]; // Cached position array to avoid GC pressure
    _lastHistoryTs?: number; // Timestamp of the latest history point processed
    promotedModel?: any; // Reference to 3D model when promoted
}

/** Global render kickstarter for deeply nested async operations. */
export let globalRequestRender: () => void = () => { };

export interface PrimitiveCollections {
    points: PointPrimitiveCollection;
    billboards: BillboardCollection;
    labels: LabelCollection;
    polylines: PolylineCollection;
}

const collectionsByViewer = new WeakMap<CesiumViewer, PrimitiveCollections>();

/** Initialize primitive collections on the viewer. */
export function initPrimitiveCollections(viewer: CesiumViewer): void {
    if (!viewer?.scene?.primitives) {
        console.warn("[EntityRenderer] initPrimitiveCollections called before viewer.scene was ready ΓÇö skipping.");
        return;
    }
    const points = new PointPrimitiveCollection();
    points.blendOption = 2; // TRANSLUCENT
    viewer.scene.primitives.add(points);

    const billboards = new BillboardCollection({ scene: viewer.scene });
    billboards.blendOption = 2; // TRANSLUCENT
    viewer.scene.primitives.add(billboards);

    const labels = new LabelCollection({ scene: viewer.scene });
    viewer.scene.primitives.add(labels);

    const polylines = new PolylineCollection();
    viewer.scene.primitives.add(polylines);

    collectionsByViewer.set(viewer, {
 points, billboards, labels, polylines
});

    globalRequestRender = () => {
        if (viewer && !viewer.isDestroyed()) {
            viewer.scene.requestRender();
        }
    };
}

/** Get the primitive collections for a viewer. Returns an empty shape if init hasn't run. */
export function getCollections(viewer: CesiumViewer): Partial<PrimitiveCollections> {
    return collectionsByViewer.get(viewer) ?? {};
}

/** Creates a label primitive for an item (lazy evaluation). */
export function createLabel(item: AnimatableItem, labels: LabelCollection): void {
    if (!item.options.labelText || item.labelPrimitive) return;
    const clickId = { _wwvEntity: item.entity };
    item.labelPrimitive = labels.add({
        position: item.posRef,
        text: item.options.labelText,
        font: item.options.labelFont || "12px Inter, sans-serif",
        fillColor: Color.WHITE,
outlineColor: Color.BLACK,
outlineWidth: 2,
        verticalOrigin: VerticalOrigin.BOTTOM,
pixelOffset: { x: 0, y: -12 } as any,
        show: true,
id: clickId,
        // WARNING: Do NOT use heightReference: HeightReference.CLAMP_TO_GROUND here.
        // It causes severe lag/performance drops with thousands of dynamic entities.
        disableDepthTestDistance: item.options.disableDepthTestDistance !== undefined 
            ? item.options.disableDepthTestDistance 
            : ((item.entity.altitude || 0) < 100 ? Number.POSITIVE_INFINITY : 0),
        translucencyByDistance: new NearFarScalar(1e3, 1.0, 5e5, 0.0),
        distanceDisplayCondition: item.options.distanceDisplayCondition
            ? new DistanceDisplayCondition(item.options.distanceDisplayCondition.near, item.options.distanceDisplayCondition.far)
            : undefined,
    });
}

/** Removes a label primitive for an item. */
export function removeLabel(item: AnimatableItem, labels: LabelCollection): void {
    if (!item.labelPrimitive) return;
    labels.remove(item.labelPrimitive);
    item.labelPrimitive = undefined;
}

/** Core rendering logic for a single entity. */
function renderSingleEntity(
    { entity, options }: { entity: GeoEntity; options: CesiumEntityOptions },
    existingMap: Map<string, AnimatableItem>,
    points: PointPrimitiveCollection,
billboards: BillboardCollection,
    labels: LabelCollection,
currentIds: Set<string>
) {
    currentIds.add(entity.id);
    Cartesian3.fromDegrees(entity.longitude, entity.latitude, entity.altitude || 0, Ellipsoid.WGS84, scratchPosition);

    const baseColor = getEntityColor(options);

    // Auto-upgrade missing icons to SVG Billboards so pixelOffsets (spiderifier) will work.
    // Only clone when the auto-SVG branch actually mutates ΓÇö otherwise pass `options` through.
    let effectiveOptions: CesiumEntityOptions = options;
    if (!options.iconUrl && options.type !== "model") {
        const baseOutlineColor = getCachedColor(options.outlineColor) || Color.BLACK;
        const outWidth = options.outlineWidth || 1;
        const pSize = options.size || (typeof window !== "undefined" && window.matchMedia("(pointer: coarse)").matches ? 12 : 8);
        effectiveOptions = {
            ...options,
            iconUrl: getDefaultDotIcon(baseColor, baseOutlineColor, outWidth, pSize),
            iconScale: 1.0,
        };
        (effectiveOptions as any)._isAutoSVG = true;
    }

    const clickId = { _wwvEntity: entity };
    let item = existingMap.get(entity.id);

    if (item && item.options.type !== effectiveOptions.type) {
        if (item.options.iconUrl) billboards.remove(item.primitive); else points.remove(item.primitive);
        if (item.labelPrimitive) labels.remove(item.labelPrimitive);
        existingMap.delete(entity.id);
        item = undefined;
    }

    if (item) {
        updateExistingItem(item, entity, effectiveOptions, baseColor);
    } else {
        createNewItem(entity, effectiveOptions, baseColor, clickId, existingMap, points, billboards);
    }
}

/** Chunked rendering for large datasets (10k+). */
export async function renderEntitiesChunked(
    viewer: CesiumViewer,
    visibleEntities: Array<{ entity: GeoEntity; options: CesiumEntityOptions }>,
    existingMap: Map<string, AnimatableItem>,
    onChunkProcessed?: () => void
): Promise<AnimatableItem[]> {
    const {
 points, billboards, labels, polylines
} = getCollections(viewer);
    if (!points || !billboards || !labels) return getStableAnimatables(existingMap);
    const currentIds = new Set<string>();
    const completed = await globalChunkedProcessor.processChunked(visibleEntities, 500, (chunk) => {
        if (viewer.isDestroyed()) return;
        for (let i = 0; i < chunk.length; i++) renderSingleEntity(chunk[i], existingMap, points, billboards, labels, currentIds);
        if (onChunkProcessed) onChunkProcessed();
    });

    if (!completed || viewer.isDestroyed()) {
        return getStableAnimatables(existingMap);
    }

    cleanupRemovedEntities(existingMap, currentIds, points, billboards, labels, polylines);
    markAnimatablesDirty();

    let altitude = 1000000;
    if (viewer.camera && viewer.camera.positionCartographic) {
        altitude = viewer.camera.positionCartographic.height;
    } else if (viewer.camera && viewer.camera.positionWC) {
        const carto = Cartographic.fromCartesian(viewer.camera.positionWC);
        if (carto) altitude = carto.height;
    }

    rebuildStacks(existingMap, calculateGridSizeDegrees(altitude), true);
    return getStableAnimatables(existingMap);
}

/** Synchronous render for smaller datasets or instant updates. */
export function renderEntities(
    viewer: CesiumViewer,
    visibleEntities: Array<{ entity: GeoEntity; options: CesiumEntityOptions }>,
    existingMap: Map<string, AnimatableItem>
): AnimatableItem[] {
    globalChunkedProcessor.cancel();
    const {
 points, billboards, labels, polylines
} = getCollections(viewer);
    if (!points || !billboards || !labels) return getStableAnimatables(existingMap);
    const currentIds = new Set<string>();
    for (const item of visibleEntities) renderSingleEntity(item, existingMap, points, billboards, labels, currentIds);
    cleanupRemovedEntities(existingMap, currentIds, points, billboards, labels, polylines);
    markAnimatablesDirty();

    let altitude = 1000000;
    if (viewer.camera && viewer.camera.positionCartographic) {
        altitude = viewer.camera.positionCartographic.height;
    } else if (viewer.camera && viewer.camera.positionWC) {
        const carto = Cartographic.fromCartesian(viewer.camera.positionWC);
        if (carto) altitude = carto.height;
    }

    rebuildStacks(existingMap, calculateGridSizeDegrees(altitude), true);
    return getStableAnimatables(existingMap);
}

/**
 * Manages Cesium Entity polylines for camera frustum outlines.
 *
 * Draws 4 side-edge lines from the camera apex to the 4 far
 * corners of the view pyramid. No far-plane rectangle is drawn
 * (it would clip the earth surface).
 *
 * Architecture: corners come from frustumGeometry.ts so a future
 * ground-projection step can replace the far-plane corners with
 * terrain-intersection points without changing this renderer.
 */

import {
    Cartesian3,
    Color,
    Entity,
    PolylineGlowMaterialProperty,
} from "cesium";
import type { Viewer as CesiumViewer } from "cesium";
import type { GeoEntity } from "../../wwv-sdk/index";
import {
    computeFrustumEdges,
    FRUSTUM_DEFAULTS,
    type FrustumEdges,
    type Point3D,
} from "./frustumGeometry";

const FRUSTUM_COLOR = Color.fromCssColorString("#00ccff").withAlpha(0.6);
const EDGE_WIDTH = 2;

export class FrustumRenderer {
    /** Map from entity id ΓåÆ array of 4 Cesium.Entity polylines */
    private entityMap = new Map<string, Entity[]>();

    /**
     * Sync frustum outlines with the current set of camera entities.
     * Only draws for entities whose `properties` include heading.
     */
    update(viewer: CesiumViewer, entities: GeoEntity[]): void {
        if (!viewer || viewer.isDestroyed()) return;
        const activeIds = new Set<string>();

        for (const geo of entities) {
            if (geo.pluginId !== "camera") continue;

            const heading = this.resolveHeading(geo);
            if (heading === undefined) continue;

            activeIds.add(geo.id);
            const edges = this.buildEdges(geo, heading);

            if (this.entityMap.has(geo.id)) {
                this.updateExisting(viewer, geo.id, edges);
            } else {
                this.createNew(viewer, geo.id, edges);
            }
        }

        this.removeStale(viewer, activeIds);
    }

    /** Remove all frustum entities from the viewer. */
    clear(viewer: CesiumViewer): void {
        if (!viewer || viewer.isDestroyed()) {
            this.entityMap.clear();
            return;
        }
        for (const [, lines] of this.entityMap) {
            for (const line of lines) {
                viewer.entities.remove(line);
            }
        }
        this.entityMap.clear();
    }

    // ΓöÇΓöÇΓöÇ Private helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    private resolveHeading(geo: GeoEntity): number | undefined {
        const p = geo.properties;
        if (typeof p.heading === "number") return p.heading;
        if (typeof p.azimuth === "number") return p.azimuth;
        if (typeof p.heading === "string") {
            return parseFloat(p.heading) || undefined;
        }
        return geo.heading;
    }

    private buildEdges(geo: GeoEntity, heading: number): FrustumEdges {
        const p = geo.properties;
        return computeFrustumEdges({
            lat: geo.latitude,
            lon: geo.longitude,
            alt: toNum(p.altitude, toNum(p.alt, FRUSTUM_DEFAULTS.alt)),
            headingDeg: heading,
            pitchDeg: toNum(p.pitch, FRUSTUM_DEFAULTS.pitchDeg),
            hFovDeg: toNum(p.fov, toNum(p.hFov, FRUSTUM_DEFAULTS.hFovDeg)),
            vFovDeg: toNum(p.vFov, FRUSTUM_DEFAULTS.vFovDeg),
            rangeMtrs: toNum(p.range, FRUSTUM_DEFAULTS.rangeMtrs),
        });
    }

    private createNew(viewer: CesiumViewer, id: string, edges: FrustumEdges): void {
        const corners = [edges.topLeft, edges.topRight, edges.bottomLeft, edges.bottomRight];
        const lines = corners.map((corner) => this.addEdgeLine(viewer, id, edges.apex, corner),);
        this.entityMap.set(id, lines);
    }

    private updateExisting(viewer: CesiumViewer, id: string, edges: FrustumEdges): void {
        const corners = [edges.topLeft, edges.topRight, edges.bottomLeft, edges.bottomRight];
        const existing = this.entityMap.get(id)!;
        for (let i = 0; i < 4; i++) {
            existing[i].polyline!.positions = toPositions(edges.apex, corners[i]) as any;
        }
    }

    private removeStale(viewer: CesiumViewer, activeIds: Set<string>): void {
        for (const [id, lines] of this.entityMap) {
            if (!activeIds.has(id)) {
                for (const line of lines) viewer.entities.remove(line);
                this.entityMap.delete(id);
            }
        }
    }

    private addEdgeLine(
        viewer: CesiumViewer,
parentId: string,
        from: Point3D,
to: Point3D,
    ): Entity {
        return viewer.entities.add({
            id: `frustum-${parentId}-${Math.random().toString(36).slice(2, 8)}`,
            polyline: {
                positions: toPositions(from, to),
                width: EDGE_WIDTH,
                material: new PolylineGlowMaterialProperty({
                    glowPower: 0.15,
                    color: FRUSTUM_COLOR,
                }),
                clampToGround: false,
            },
        });
    }
}

// ΓöÇΓöÇΓöÇ Utilities ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function toPositions(a: Point3D, b: Point3D): Cartesian3[] {
    return [
        Cartesian3.fromDegrees(a.lon, a.lat, a.alt),
        Cartesian3.fromDegrees(b.lon, b.lat, b.alt),
    ];
}

function toNum(val: unknown, fallback: number): number {
    if (typeof val === "number" && !Number.isNaN(val)) return val;
    if (typeof val === "string") {
        const n = parseFloat(val);
        if (!Number.isNaN(n)) return n;
    }
    return fallback;
}

import {
    ScreenSpaceEventHandler,
    ScreenSpaceEventType,
    defined,
    SceneMode,
    SceneTransforms,
} from "cesium";
import type { Viewer as CesiumViewer, Cartesian2 } from "cesium";
import type { GeoEntity } from "@/core/plugins/PluginTypes";
import { useStore } from "@/core/state/store";
import { useUIStore } from "@/store/uiStore";
import { clearCursorSourceTargets, publishCursorTarget } from "@/core/cursor";
import {
    findStackByEntityId, expandStack, collapseStack, getStacks
} from "./StackManager";

/**
 * Pick a WorldWideView entity at a screen position using the Cesium pick API.
 */
function findEntityAtPosition(viewer: CesiumViewer, position: { x: number; y: number }): GeoEntity | null {
    if (!viewer || viewer.isDestroyed()) return null;
    const picked = viewer.scene.pick(position as Cartesian2);
    if (defined(picked) && picked.id && picked.id._wwvEntity) {
        return picked.id._wwvEntity as GeoEntity;
    }
    return null;
}

/**
 * Sets up click and hover handlers on the viewer canvas.
 * Returns a cleanup function that destroys the handler and resets the cursor.
 */
export function setupInteractionHandlers(
    viewer: CesiumViewer,
    hoveredEntityIdRef: React.MutableRefObject<string | null>
): () => void {
    if (!viewer || viewer.isDestroyed() || !viewer.scene) {
        return () => { };
    }
    const {canvas} = viewer.scene;
    const handler = new ScreenSpaceEventHandler(canvas);

    /** Currently expanded stack id (only one at a time). */
    let expandedStackId: string | null = null;

    let latestMousePos = { x: 0, y: 0 };

    // Click ΓåÆ select entity or expand stack
    handler.setInputAction(
        (event: { position: { x: number; y: number } }) => {
            if (!viewer || viewer.isDestroyed()) return;
            const entity = findEntityAtPosition(viewer, event.position);

            if (entity) {
                const stack = findStackByEntityId(entity.id);
                // If clicked entity is in a stack
                if (stack && stack.children.length > 1) {
                    if (stack.state === "collapsed" || stack.state === "collapsing") {
                        // Expand the stack and select the hub
                        expandStack(stack.id);
                        if (expandedStackId && expandedStackId !== stack.id) {
                            collapseStack(expandedStackId);
                        }
                        expandedStackId = stack.id;
                        useStore.getState().setSelectedEntity(entity);
                    } else {
                        // Stack is already expanded, user clicked a leaf node -> select it
                        useStore.getState().setSelectedEntity(entity);
                    }
                } else {
                    // Clicked a standalone entity -> select it and close any open stack
                    useStore.getState().setSelectedEntity(entity);
                    if (expandedStackId) {
                        collapseStack(expandedStackId);
                        expandedStackId = null;
                    }
                }
                
                // Clear activeLocation in UI Store and open the context panel
                useUIStore.getState().setActiveLocation(null);
                useUIStore.getState().setRightPanelTab('context');
                useUIStore.getState().setRightPanelOpen(true);
            } else {
                // Clicked empty space -> clear selection and close any open stack
                useStore.getState().setSelectedEntity(null);
                if (expandedStackId) {
                    collapseStack(expandedStackId);
                    expandedStackId = null;
                }
            }

            if (entity) {
                useStore.getState().setHoveredEntity(null, null);
                hoveredEntityIdRef.current = null;
                clearCursorSourceTargets("cesium");
            }

            // Immediately request a render frame to apply highlight changes
            // or to kickstart the CSS spiderifier animation loop
            viewer.scene.requestRender();
        },
        ScreenSpaceEventType.LEFT_CLICK
    );

    let latestHoverRequestId = 0;
    let hoverTimeout: ReturnType<typeof setTimeout> | null = null;
    let isDragging = false;

    // Track camera movement to avoid expensive picking during camera pan
    const onMoveStart = () => { isDragging = true; };
    const onMoveEnd = () => {
        isDragging = false;
        clearCursorSourceTargets("system");
    };
    viewer.camera.moveStart.addEventListener(onMoveStart);
    viewer.camera.moveEnd.addEventListener(onMoveEnd);

    // Hover ΓåÆ show tooltip card only
    handler.setInputAction(
        (event: { endPosition: { x: number; y: number } }) => {
            // Canvas-local coordinates used for Cesium picking
            const canvasPos = { x: event.endPosition.x, y: event.endPosition.y };
            latestMousePos = canvasPos;

            // Convert canvas-local coords to viewport/client coords for UI placement
            const rect = canvas.getBoundingClientRect();
            const screenPos = { x: Math.round(rect.left + canvasPos.x), y: Math.round(rect.top + canvasPos.y) };

            if (hoveredEntityIdRef.current) {
                useStore.getState().setHoveredEntity(useStore.getState().hoveredEntity, screenPos);
                const hovered = useStore.getState().hoveredEntity;
                if (hovered) {
                    publishCursorTarget({
                        id: `cesium-${hovered.id}`,
                        kind: "cesiumEntity",
                        source: "cesium",
                        screenPosition: screenPos,
                        priority: 84,
                        confidence: 0.86,
                        explicitLock: true,
                        expiresAt: performance.now() + 220,
                    });
                }
            }

            if (!viewer || viewer.isDestroyed()) return;
            if (viewer.scene.mode === SceneMode.MORPHING) return;

            if (isDragging) return;

            latestHoverRequestId++;
            const currentRequestId = latestHoverRequestId;

            if (hoverTimeout) clearTimeout(hoverTimeout);

            hoverTimeout = setTimeout(() => {
                if (currentRequestId !== latestHoverRequestId) return;
                if (!viewer || viewer.isDestroyed() || isDragging) return;

                // Use canvas-local coords for picking
                const entity = findEntityAtPosition(viewer, canvasPos);

                const prevId = hoveredEntityIdRef.current;
                const newId = entity ? entity.id : null;

                if (prevId !== newId) {
                    hoveredEntityIdRef.current = newId;
                    useStore.getState().setHoveredEntity(entity, entity ? screenPos : null);
                    if (entity) {
                        publishCursorTarget({
                            id: `cesium-${entity.id}`,
                            kind: "cesiumEntity",
                            source: "cesium",
                            screenPosition: screenPos,
                            priority: 84,
                            confidence: 0.88,
                            explicitLock: true,
                            expiresAt: performance.now() + 220,
                        });
                    } else {
                        clearCursorSourceTargets("cesium");
                    }
                    // Trigger render to apply hover highlights immediately
                    viewer.scene.requestRender();
                }
            }, 60);
        },
        ScreenSpaceEventType.MOUSE_MOVE
    );

    return () => {
        if (hoverTimeout) clearTimeout(hoverTimeout);
        if (viewer && !viewer.isDestroyed()) {
            viewer.camera.moveStart.removeEventListener(onMoveStart);
            viewer.camera.moveEnd.removeEventListener(onMoveEnd);
        }
        if (handler && !handler.isDestroyed()) {
            handler.destroy();
        }
        clearCursorSourceTargets("cesium");
        clearCursorSourceTargets("system");
    };
}

/**
 * Manages 3D glTF model primitives on the Cesium viewer.
 * Models are loaded asynchronously and cached by URL to avoid re-downloading.
 */
import {
    Cartesian3,
    Color,
    HeadingPitchRoll,
    Math as CesiumMath,
    Model,
    Transforms,
    Matrix4,
} from "cesium";
import type { Scene } from "cesium";
import type { GeoEntity, CesiumEntityOptions } from "@/core/plugins/PluginTypes";
import type { AnimatableItem } from "./EntityRenderer";

/** Track pending model loads to prevent duplicate async loads for the same entity */
const pendingLoads = new Set<string>();

/** Scratch objects reused every frame to avoid heap allocations */
const scratchHPR = new HeadingPitchRoll();
const scratchMatrix = new Matrix4();

/**
 * Create a 3D model primitive for an entity and attach it to the scene.
 * This is async because Model.fromGltfAsync needs to download/parse the glTF.
 */
export async function createModelPrimitive(
    scene: Scene,
    item: AnimatableItem
): Promise<void> {
    const { entity, options, posRef } = item;
    if (!options.modelUrl || pendingLoads.has(entity.id)) return;

    pendingLoads.add(entity.id);

    try {
        const offset = options.modelHeadingOffset || 0;
        const headingRad = CesiumMath.toRadians((entity.heading || 0) + offset);
        const hpr = new HeadingPitchRoll(headingRad, 0, 0);
        const modelMatrix = Transforms.headingPitchRollToFixedFrame(posRef, hpr);

        const scale = options.modelScale || 1.0;
        Matrix4.multiplyByUniformScale(modelMatrix, scale, modelMatrix);

        const model = await Model.fromGltfAsync({
            url: options.modelUrl,
            modelMatrix,
            scale: 1.0, // Scale is baked into the modelMatrix
            minimumPixelSize: options.modelMinPixelSize ?? 24,
            maximumScale: scale * 5,
            color: options.color ? Color.fromCssColorString(options.color) : undefined,
            silhouetteColor: Color.CYAN,
            silhouetteSize: 0,
            id: { _wwvEntity: entity },
        });

        if (scene.isDestroyed()) return;

        scene.primitives.add(model);
        item.primitive = model;
    } catch (err) {
        console.warn(`[ModelManager] Failed to load model for ${entity.id}:`, err);
    } finally {
        pendingLoads.delete(entity.id);
    }
}

/**
 * Update the position and heading of an existing model primitive.
 * Uses scratch allocations to avoid per-frame heap pressure.
 */
export function updateModelTransform(
    item: AnimatableItem,
    position: Cartesian3,
    heading?: number
): void {
    const modelsToUpdate: any[] = [];
    if (item.primitive && item.primitive.modelMatrix) {
        modelsToUpdate.push(item.primitive);
    }
    if (item.promotedModel && item.promotedModel.modelMatrix) {
        modelsToUpdate.push(item.promotedModel);
    }

    if (modelsToUpdate.length === 0) return;

    const offset = item.options.modelHeadingOffset || 0;
    scratchHPR.heading = CesiumMath.toRadians((heading || 0) + offset);
    scratchHPR.pitch = 0;
    scratchHPR.roll = 0;
    Transforms.headingPitchRollToFixedFrame(
position,
scratchHPR,
        undefined,
undefined,
scratchMatrix
);

    const scale = item.options.modelScale || 1.0;
    Matrix4.multiplyByUniformScale(scratchMatrix, scale, scratchMatrix);

    for (const model of modelsToUpdate) {
        Matrix4.clone(scratchMatrix, model.modelMatrix);
    }
}

/**
 * Remove a model primitive from the scene.
 */
export function removeModelPrimitive(scene: Scene, item: AnimatableItem): void {
    if (!item.primitive) return;
    try {
        scene.primitives.remove(item.primitive);
    } catch { /* Already removed or destroyed */ }
}

import {
    Cartesian3,
    Color,
    Math as CesiumMath,
    PolylineDashMaterialProperty,
    Entity as CesiumEntity,
} from "cesium";
import type { Viewer as CesiumViewer } from "cesium";
import type { GeoEntity } from "@/core/plugins/PluginTypes";
import { pluginManager } from "@/core/plugins/PluginManager";
import type { AnimatableItem } from "./EntityRenderer";

/**
 * Fly camera to a selected entity and optionally render a motion trail.
 * Uses the extrapolated posRef from the animatables map as the trail origin
 * so it matches the visually interpolated aircraft position.
 */
export function handleEntitySelection(
    viewer: CesiumViewer,
    selectedEntity: GeoEntity,
    trailEntityRef: React.MutableRefObject<CesiumEntity | null>,
    animatablesMap: Map<string, AnimatableItem>
): void {
    // Clean up previous trail
    if (trailEntityRef.current && !viewer.isDestroyed()) {
        viewer.entities.remove(trailEntityRef.current);
        trailEntityRef.current = null;
    }

    // Get selection behavior from plugin
    const managed = pluginManager.getPlugin(selectedEntity.pluginId);
    const behavior = managed?.plugin.getSelectionBehavior?.(selectedEntity) ?? null;

    // Render trail if plugin opts in
    if (behavior?.showTrail && selectedEntity.heading !== undefined) {
        const trailDuration = behavior.trailDurationSec ?? 60;
        const trailStep = behavior.trailStepSec ?? 5;
        const trailColor = behavior.trailColor ?? "#00fff7";

        // Use extrapolated position if available, otherwise raw polled position
        const item = animatablesMap.get(selectedEntity.id);
        const originLon = selectedEntity.longitude;
        const originLat = selectedEntity.latitude;
        const entityAlt = (selectedEntity.altitude || 0) + 10;

        const positions: Cartesian3[] = [];
        const speed = selectedEntity.speed ?? 200;
        const headingRad = CesiumMath.toRadians(selectedEntity.heading);

        for (let t = trailDuration; t >= 0; t -= trailStep) {
            const dist = speed * t;
            const dLat = -Math.cos(headingRad) * dist / 111320;
            const dLon = -Math.sin(headingRad) * dist / (111320 * Math.cos(CesiumMath.toRadians(originLat)));
            positions.push(Cartesian3.fromDegrees(
                originLon + dLon,
                originLat + dLat,
                entityAlt
            ));
        }

        // Add the current extrapolated position as the trail tip so it
        // connects to the visually interpolated aircraft position
        if (item) {
            positions.push(Cartesian3.clone(item.posRef));
        }

        if (viewer.isDestroyed()) return;
        trailEntityRef.current = viewer.entities.add({
            polyline: {
                positions,
                width: 2,
                material: new PolylineDashMaterialProperty({
                    color: Color.fromCssColorString(trailColor).withAlpha(0.6),
                    dashLength: 16,
                }),
                depthFailMaterial: new PolylineDashMaterialProperty({
                    color: Color.fromCssColorString(trailColor).withAlpha(0.2),
                    dashLength: 16,
                }),
            } as any,
        });
    }
}

/**
 * Clean up trail entity on deselection.
 */
export function cleanupTrail(
    viewer: CesiumViewer,
    trailEntityRef: React.MutableRefObject<CesiumEntity | null>
): void {
    if (trailEntityRef.current && !viewer.isDestroyed()) {
        viewer.entities.remove(trailEntityRef.current);
        trailEntityRef.current = null;
    }
}

/**
 * DOD: Position extrapolation and highlight styling helpers.
 *
 * Extracted from AnimationLoop.ts for modularity.
 * These are the per-entity processing functions used by the
 * batched animation loop.
 */
import {
 Cartesian3, Color, Math as CesiumMath, Ellipsoid
} from "cesium";
import type { AnimatableItem } from "./EntityRenderer";

/** Returns a touch-friendly default point size: larger on mobile. */
function defaultPointSize(): number {
    if (typeof window !== "undefined" && window.matchMedia("(pointer: coarse)").matches) return 12;
    return 8;
}

export const HIGHLIGHT_COLOR_SELECTED = Color.fromCssColorString("#00fff7");
export const HIGHLIGHT_COLOR_HOVERED = Color.YELLOW;

// Pre-allocate scratch objects for zero-allocation math
const scratchDisplacement = new Cartesian3();
const scratchNorth = new Cartesian3();
const scratchEast = new Cartesian3();
const scratchVelocity = new Cartesian3();
const scratchNorthPole = new Cartesian3(0, 0, 1);
const scratchSurfaceNormal = new Cartesian3();

const SELECTED_SCALE_FACTOR = 1.35;
const HOVER_SCALE_FACTOR = 1.25;

/** Overall background opacity for unclustered entities when a spiderifier is open */
export const FADED_OPACITY = 0.4;

/** Extrapolate entity position forward/backward in time (zero-allocation). */
export function extrapolatePosition(item: AnimatableItem, nowMs: number): void {
    const { entity, posRef } = item;
    if (!entity.timestamp) return;
    const timestamp = typeof entity.timestamp === 'string' ? new Date(entity.timestamp) : entity.timestamp;

    const dtSec = (nowMs - timestamp.getTime()) / 1000;
    // Cap extrapolation at 30s (~2 polling cycles) to prevent ghost planes
    if (Math.abs(dtSec) > 30) return;

    if (!entity.speed) {
        if (item.primitive && !item.primitive.isDestroyed?.() && !Cartesian3.equals(item.primitive.position, posRef)) {
            item.primitive.position = posRef;
            if (item.labelPrimitive && !item.labelPrimitive.isDestroyed?.()) item.labelPrimitive.position = posRef;
        }
        return;
    }

    if (!item.velocityVector) {
        const headingRad = CesiumMath.toRadians(entity.heading!);
        Ellipsoid.WGS84.geodeticSurfaceNormal(posRef, scratchSurfaceNormal);

        Cartesian3.cross(scratchNorthPole, scratchSurfaceNormal, scratchNorth);
        Cartesian3.cross(scratchSurfaceNormal, scratchNorth, scratchNorth);
        Cartesian3.normalize(scratchNorth, scratchNorth);

        Cartesian3.cross(scratchNorth, scratchSurfaceNormal, scratchEast);
        Cartesian3.normalize(scratchEast, scratchEast);

        Cartesian3.multiplyByScalar(scratchNorth, Math.cos(headingRad), scratchVelocity);
        Cartesian3.multiplyByScalar(scratchEast, Math.sin(headingRad), scratchEast);
        Cartesian3.add(scratchVelocity, scratchEast, scratchVelocity);
        Cartesian3.multiplyByScalar(scratchVelocity, entity.speed, scratchVelocity);

        item.basePosition = Cartesian3.clone(posRef);
        item.velocityVector = Cartesian3.clone(scratchVelocity);
    }

    Cartesian3.multiplyByScalar(item.velocityVector, dtSec, scratchDisplacement);
    Cartesian3.add(item.basePosition!, scratchDisplacement, posRef);

    if (item.primitive && !item.primitive.isDestroyed?.()) item.primitive.position = posRef;
    if (item.labelPrimitive && !item.labelPrimitive.isDestroyed?.()) item.labelPrimitive.position = posRef;
}

/** Apply selected/hovered/normal highlight styling. */
export function applyHighlight(item: AnimatableItem, isSelected: boolean, isHovered: boolean, isFaded: boolean = false): void {
    const { primitive, options } = item;

    let targetState: 'selected' | 'hovered' | 'normal' | 'faded' = 'normal';
    if (isSelected) targetState = 'selected';
    else if (isHovered) targetState = 'hovered';
    else if (isFaded) targetState = 'faded';

    if (item.lastHighlightState === targetState) return;
    item.lastHighlightState = targetState as any;

    const isBillboard = !!options.iconUrl || (options as any)._isAutoSVG;
    const baseScale = options.iconScale ?? 0.7;

    if (targetState === 'selected') {
        primitive.color = HIGHLIGHT_COLOR_SELECTED;
        if (isBillboard) {
            primitive.scale = baseScale * 1.4;
        } else {
            primitive.pixelSize = (options.size || defaultPointSize()) * 2.0;
            primitive.outlineColor = HIGHLIGHT_COLOR_SELECTED;
            primitive.outlineWidth = 3;
        }
    } else if (targetState === 'hovered') {
        primitive.color = HIGHLIGHT_COLOR_HOVERED;
        if (isBillboard) {
            primitive.scale = baseScale * 1.2;
        } else {
            primitive.pixelSize = (options.size || defaultPointSize()) * 1.5;
            primitive.outlineColor = HIGHLIGHT_COLOR_HOVERED;
            primitive.outlineWidth = 2;
        }
    } else if (targetState === 'faded') {
        // Drop alpha to defined faded opacity for an ethereal fade
        primitive.color = item.baseColor ? item.baseColor.withAlpha(FADED_OPACITY * item.baseColor.alpha) : undefined;
        if (isBillboard) {
            primitive.scale = baseScale;
        } else {
            primitive.pixelSize = options.size || defaultPointSize();
            primitive.outlineColor = item.baseOutlineColor ? item.baseOutlineColor.withAlpha(FADED_OPACITY * item.baseOutlineColor.alpha) : undefined;
            primitive.outlineWidth = options.outlineWidth || 1;
        }
    } else {
        primitive.color = item.baseColor;
        if (isBillboard) {
            primitive.scale = baseScale;
        } else {
            primitive.pixelSize = options.size || defaultPointSize();
            primitive.outlineColor = item.baseOutlineColor;
            primitive.outlineWidth = options.outlineWidth || 1;
        }
    }
}

import type { Viewer as CesiumViewer } from "cesium";
import {
 Cartesian3, Cartesian2, Color, HeightReference
} from "cesium";

/** Duration of the full animation sequence in ms */
const TOTAL_DURATION_MS = 2500;
/** Duration of the drop bounce phase in ms */
const DROP_DURATION_MS = 600;
/** Starting Y offset in pixels (above the target) */
const DROP_START_PX = -80;
/** Billboard image: gold map-pin SVG encoded as data URI */
const PIN_IMAGE = buildPinDataUri();
/** Scratch offset reused every animation frame to avoid GC churn */
const scratchOffset = new Cartesian2();

let _pinEntity: ReturnType<CesiumViewer["entities"]["add"]> | null = null;
let _animFrameId: number | null = null;

/**
 * Shows a temporary animated map-pin billboard at the given lat/lon.
 * Pin drops from above, bounces, then fades out.
 */
export function showSearchPin(viewer: CesiumViewer, lat: number, lon: number) {
    if (viewer.isDestroyed()) return;

    // Clean up previous pin if still active
    cleanup(viewer);

    const position = Cartesian3.fromDegrees(lon, lat, 0);

    _pinEntity = viewer.entities.add({
        position,
        billboard: {
            image: PIN_IMAGE,
            width: 36,
            height: 48,
            // Anchor at bottom-center of the pin so the tip points at the location
            verticalOrigin: 1, // BOTTOM
            horizontalOrigin: 0, // CENTER
            pixelOffset: new Cartesian2(0, DROP_START_PX),
            color: Color.WHITE,
            heightReference: HeightReference.CLAMP_TO_GROUND,
            disableDepthTestDistance: Number.POSITIVE_INFINITY,
        },
    });

    const entity = _pinEntity;
    const startTime = performance.now();

    const animate = (now: number) => {
        if (!entity.billboard || viewer.isDestroyed()) return;

        const elapsed = now - startTime;

        // Phase 1: Drop + bounce (0 ΓåÆ DROP_DURATION_MS)
        if (elapsed < DROP_DURATION_MS) {
            const t = elapsed / DROP_DURATION_MS;
            const y = easeOutBounce(t) * DROP_START_PX * -1 + DROP_START_PX;
            scratchOffset.x = 0; scratchOffset.y = y;
            entity.billboard.pixelOffset = scratchOffset as any;
        }
        // Phase 2: Hold visible (DROP_DURATION_MS ΓåÆ TOTAL_DURATION_MS - 600)
        else if (elapsed < TOTAL_DURATION_MS - 600) {
            scratchOffset.x = 0; scratchOffset.y = 0;
            entity.billboard.pixelOffset = scratchOffset as any;
        }
        // Phase 3: Fade out (last 600ms)
        else if (elapsed < TOTAL_DURATION_MS) {
            const fadeT = (elapsed - (TOTAL_DURATION_MS - 600)) / 600;
            scratchOffset.x = 0; scratchOffset.y = 0;
            entity.billboard.pixelOffset = scratchOffset as any;
            entity.billboard.color = Color.fromAlpha(Color.WHITE, 1 - fadeT) as any;
        }
        // Done
        else {
            cleanup(viewer);
            return;
        }

        _animFrameId = requestAnimationFrame(animate);
    };

    _animFrameId = requestAnimationFrame(animate);
}

function cleanup(viewer: CesiumViewer) {
    if (_animFrameId !== null) {
        cancelAnimationFrame(_animFrameId);
        _animFrameId = null;
    }
    if (_pinEntity && !viewer.isDestroyed()) {
        viewer.entities.remove(_pinEntity);
        _pinEntity = null;
    }
}

/** Standard ease-out-bounce: t Γêê [0,1] ΓåÆ [0,1] */
function easeOutBounce(t: number): number {
    if (t < 1 / 2.75) return 7.5625 * t * t;
    if (t < 2 / 2.75) { t -= 1.5 / 2.75; return 7.5625 * t * t + 0.75; }
    if (t < 2.5 / 2.75) { t -= 2.25 / 2.75; return 7.5625 * t * t + 0.9375; }
    t -= 2.625 / 2.75;
    return 7.5625 * t * t + 0.984375;
}

/** Builds a gold map-pin SVG as a data URI */
function buildPinDataUri(): string {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="40" height="52" viewBox="0 0 40 52">
    <path d="M20 0C8.954 0 0 8.954 0 20C0 34 20 52 20 52C20 52 40 34 40 20C40 8.954 31.046 0 20 0Z"
          fill="rgba(255, 220, 60, 0.95)"/>
    <circle cx="20" cy="20" r="8" fill="rgba(0,0,0,0.55)"/>
  </svg>`;
    return `data:image/svg+xml;base64,${btoa(svg)}`;
}

import { useEffect } from "react";
import type { Viewer as CesiumViewer } from "cesium";
import {
 Cartesian3, EasingFunction, Ellipsoid, Math as CesiumMath, Transforms, Matrix4
} from "cesium";
import { dataBus } from "@/core/data/DataBus";
import { showSearchPin } from "./searchPinAnimation";

export function useCameraActions(viewer: CesiumViewer | null, isReady: boolean) {
    useEffect(() => {
        if (!viewer || !isReady) return;

        const unsubFace = dataBus.on("cameraFaceTowards", ({ lat, lon, alt }) => {
            if (!viewer || viewer.isDestroyed()) return;
            console.log("[GlobeView] Native faceTowards", lat, lon, alt);
            const target = Cartesian3.fromDegrees(lon, lat, alt);
            const offset = Cartesian3.subtract(
                viewer.camera.positionWC,
                target,
                new Cartesian3()
            );
            // lookAt sets the view relative to the target's ENU frame
            viewer.camera.lookAt(target, offset);
            // Immediately release the transform to allow free camera movement again
            // while preserving the orientation
            viewer.camera.lookAtTransform(Matrix4.IDENTITY);
        });

        const unsubGoTo = dataBus.on("cameraGoTo", ({
 lat, lon, alt, distance, maxPitch, heading
}) => {
            // Add a slight delay to avoid any immediate state-change cancellations from React
            setTimeout(() => {
                if (!viewer || viewer.isDestroyed()) return;
                const targetPosition = Cartesian3.fromDegrees(lon, lat, alt || 0);
                const cameraPosition = viewer.camera.positionWC;

                // Calculate direction from camera to the target object
                const direction = Cartesian3.subtract(targetPosition, cameraPosition, new Cartesian3());
                Cartesian3.normalize(direction, direction);

                // Enforce maximum pitch (default -30 degrees)
                const targetLocalUp = Ellipsoid.WGS84.geodeticSurfaceNormal(targetPosition, new Cartesian3());
                const pitchDot = Cartesian3.dot(direction, targetLocalUp);
                let pitch = Math.asin(pitchDot);
                const maxPitchRad = CesiumMath.toRadians(maxPitch !== undefined ? maxPitch : -30);

                if (pitch > maxPitchRad) {
                    pitch = maxPitchRad;
                    // Extract the horizontal component of the direction to reconstruct it
                    const vertComponent = Cartesian3.multiplyByScalar(targetLocalUp, pitchDot, new Cartesian3());
                    const horiz = Cartesian3.subtract(direction, vertComponent, new Cartesian3());

                    if (Cartesian3.magnitude(horiz) > 0.0001) {
                        Cartesian3.normalize(horiz, horiz);
                        const cosP = Math.cos(pitch);
                        const sinP = Math.sin(pitch);
                        const newHoriz = Cartesian3.multiplyByScalar(horiz, cosP, new Cartesian3());
                        const newVert = Cartesian3.multiplyByScalar(targetLocalUp, sinP, new Cartesian3());
                        Cartesian3.add(newHoriz, newVert, direction);
                        Cartesian3.normalize(direction, direction);
                    }
                }

                const viewDistance = distance !== undefined ? distance : Math.max(10000, (alt || 0) * 2 + 20000);

                let destination: Cartesian3;
                let orientation: any;

                if (heading !== undefined) {
                    const headingRad = CesiumMath.toRadians(heading);

                    // Offset in ENU frame at the target
                    const x_dir = Math.cos(pitch) * Math.sin(headingRad);
                    const y_dir = Math.cos(pitch) * Math.cos(headingRad);
                    const z_dir = Math.sin(pitch);

                    const offsetENU = new Cartesian3(
                        -x_dir * viewDistance,
                        -y_dir * viewDistance,
                        -z_dir * viewDistance
                    );

                    const enuTransform = Transforms.eastNorthUpToFixedFrame(targetPosition);
                    const offsetWC = Matrix4.multiplyByPointAsVector(enuTransform, offsetENU, new Cartesian3());
                    destination = Cartesian3.add(targetPosition, offsetWC, new Cartesian3());

                    orientation = {
                        heading: headingRad,
                        pitch,
                        roll: 0
                    };
                } else {
                    // Offset backwards by its looking direction
                    const offset = Cartesian3.multiplyByScalar(direction, -viewDistance, new Cartesian3());
                    destination = Cartesian3.add(targetPosition, offset, new Cartesian3());

                    // Keep roll at 0 by using the Earth's local normal to force a horizontal right vector
                    const localUp = Ellipsoid.WGS84.geodeticSurfaceNormal(destination, new Cartesian3());
                    const right = Cartesian3.cross(direction, localUp, new Cartesian3());
                    Cartesian3.normalize(right, right);

                    // The new 'up' vector will be perpendicular to both, ensuring 0 roll
                    const up = Cartesian3.cross(right, direction, new Cartesian3());
                    Cartesian3.normalize(up, up);

                    orientation = {
                        direction,
                        up,
                    };
                }

                let finalDestination = destination;
                let finalOrientation = orientation;

                if (!Matrix4.equals(viewer.camera.transform, Matrix4.IDENTITY)) {
                    // During tracking locks, the camera operates in a custom transform.
                    // We must convert the WGS84 destination into the target's local coordinate frame.
                    const invTransform = Matrix4.inverseTransformation(viewer.camera.transform, new Matrix4());
                    finalDestination = Matrix4.multiplyByPoint(invTransform, destination, new Cartesian3());

                    if (orientation && orientation.direction) {
                        finalOrientation = {
                            direction: Matrix4.multiplyByPointAsVector(invTransform, orientation.direction, new Cartesian3()),
                            up: Matrix4.multiplyByPointAsVector(invTransform, orientation.up, new Cartesian3()),
                        }
                    }
                    // HPR is intrinsically bound to the local reference frame so it passes through cleanly
                }

                viewer.camera.flyTo({
                    destination: finalDestination,
                    orientation: finalOrientation,
                    duration: 2.0,
                    easingFunction: EasingFunction.QUINTIC_IN_OUT,
                    complete: () => {
                        showSearchPin(viewer, lat, lon);
                    },
                });
            }, 50);
        });

        return () => {
            unsubFace();
            unsubGoTo();
        };
    }, [viewer, isReady]);
}

