source:
/* eslint-disable react-hooks/immutability */
import { useEffect, useRef } from "react";
import type { Viewer as CesiumViewer } from "cesium";
import { Cartographic, Cartesian3 } from "cesium";
import type { GeoEntity, CesiumEntityOptions } from "@/core/plugins/PluginTypes";
import {
 renderEntities, renderEntitiesChunked, AnimatableItem, getCollections
} from "../EntityRenderer";
import { createUpdateLoop } from "../AnimationLoop";
import { rebuildStacks, calculateGridSizeDegrees } from "../StackManager";

export function useEntityRendering(
    viewer: CesiumViewer | null,
    isReady: boolean,
    visibleEntities: Array<{ entity: GeoEntity; options: CesiumEntityOptions }>,
    animatablesMapRef: React.MutableRefObject<Map<string, AnimatableItem>>,
    hoveredEntityIdRef: React.MutableRefObject<string | null>,
    sceneSettings: {
        showFps: boolean;
        resolutionScale: number;
        antiAliasing: string;
        maxScreenSpaceError: number;
        shadowsEnabled: boolean;
        enableLighting: boolean;
    }
) {
    // Cached array ref ΓÇö rebuilt only after renderEntities, not every frame
    const cachedAnimatablesRef = useRef<{ current: AnimatableItem[] }>({ current: [] });

    // Handle scene settings updates separately to avoid tearing down the animation loop
    useEffect(() => {
        if (!viewer || !isReady || viewer.isDestroyed()) return;

        viewer.scene.debugShowFramesPerSecond = sceneSettings.showFps;
        viewer.resolutionScale = sceneSettings.resolutionScale;

        // Apply Anti-Aliasing Mode
        viewer.scene.postProcessStages.fxaa.enabled = sceneSettings.antiAliasing === "fxaa";

        switch (sceneSettings.antiAliasing) {
            case "none":
            case "fxaa":
                viewer.scene.msaaSamples = 1;
                break;
            case "msaa2x":
                viewer.scene.msaaSamples = 2;
                break;
            case "msaa4x":
                viewer.scene.msaaSamples = 4;
                break;
            case "msaa8x":
                viewer.scene.msaaSamples = 8;
                break;
            default:
                viewer.scene.msaaSamples = 1;
        }
        viewer.shadowMap.enabled = sceneSettings.shadowsEnabled;
        viewer.scene.globe.enableLighting = sceneSettings.enableLighting;
        const primitives = viewer.scene.primitives as any;
        for (let i = 0; i < primitives.length; i++) {
            const p = primitives.get(i);
            if (p?.maximumScreenSpaceError !== undefined) {
                p.maximumScreenSpaceError = sceneSettings.maxScreenSpaceError;
            }
        }
        viewer.scene.requestRender();
    }, [
        viewer,
        isReady,
        sceneSettings.showFps,
        sceneSettings.resolutionScale,
        sceneSettings.antiAliasing,
        sceneSettings.maxScreenSpaceError,
        sceneSettings.shadowsEnabled,
        sceneSettings.enableLighting
    ]);

    // Handle initial entity rendering and animation loop
    useEffect(() => {
        if (!viewer || !isReady || viewer.isDestroyed()) return;

        // Attach animation loop with cached array ref (no per-frame allocation)
        const updatePositions = createUpdateLoop(
            viewer,
            cachedAnimatablesRef.current,
            hoveredEntityIdRef
        );

        // Root Cause Fix: Attach physics loop to clock.onTick instead of scene.preUpdate.
        // By forcing this to index 0, physics calculates the *current* frame's position
        // BEFORE Cesium's Camera Tracking (which also runs on clock.onTick) asks for it.
        // This eliminates the 1-frame lag that caused brutal plane jittering against the camera.
        viewer.clock.onTick.addEventListener(updatePositions);
        const tickListeners = (viewer.clock.onTick as any)._listeners;
        if (tickListeners && tickListeners.length > 1) {
            const loopListener = tickListeners.pop();
            tickListeners.unshift(loopListener);
        }

        let isActive = true;

        if (visibleEntities.length > 500) {
            renderEntitiesChunked(viewer, visibleEntities, animatablesMapRef.current).then(() => {
                if (!isActive || viewer.isDestroyed()) return;
                cachedAnimatablesRef.current.current = Array.from(animatablesMapRef.current.values());
                viewer.scene.requestRender();
            });
        } else {
            // Synchronous render ΓÇö all entities processed atomically in a single frame
            renderEntities(viewer, visibleEntities, animatablesMapRef.current);

            // Rebuild cached array after render
            cachedAnimatablesRef.current.current = Array.from(animatablesMapRef.current.values());
        }

        // Camera distance-based dynamic clustering
        let lastAltitude = 0;
        if (viewer.camera && viewer.camera.positionCartographic) lastAltitude = Math.max(0, viewer.camera.positionCartographic.height);

        const R_WGS84 = 6356752.0;
        const handlePreUpdateClustering = () => {
            if (viewer.isDestroyed() || !viewer.camera) return;

            let altitude = 0;
            if (viewer.camera.positionCartographic) {
                altitude = Math.max(0, viewer.camera.positionCartographic.height);
            } else if (viewer.camera.positionWC) {
                const distSqr = Cartesian3.magnitudeSquared(viewer.camera.positionWC);
                altitude = Math.max(0, Math.sqrt(distSqr) - R_WGS84);
            }

            // Re-cluster if altitude changed significantly (15%)
            if (Math.abs(altitude - lastAltitude) / Math.max(lastAltitude, 1) > 0.15) {
                lastAltitude = altitude;
                rebuildStacks(animatablesMapRef.current, calculateGridSizeDegrees(altitude));
                // Call requestRender to ensure the new offsets are drawn in the very next frame
                viewer.scene.requestRender();
            }
        };
        viewer.scene.preUpdate.addEventListener(handlePreUpdateClustering);

        // Signal Cesium that the scene needs a re-render (requestRenderMode is on)
        viewer.scene.requestRender();

        return () => {
            isActive = false;
            if (!viewer.isDestroyed()) {
                viewer.clock.onTick.removeEventListener(updatePositions);
                viewer.scene.preUpdate.removeEventListener(handlePreUpdateClustering);
                // Synchronously flush all labels to prevent stale labels persisting
                const { labels } = getCollections(viewer);
                if (labels) {
                    for (const item of animatablesMapRef.current.values()) {
                        if (item.labelPrimitive && !item.labelPrimitive.isDestroyed?.()) {
                            labels.remove(item.labelPrimitive);
                            item.labelPrimitive = undefined;
                        }
                    }
                }
            }
        };
    }, [
        viewer,
        isReady,
        visibleEntities,
        animatablesMapRef,
        hoveredEntityIdRef
    ]);
}

import { useEffect, useRef } from "react";
import { Cartesian3, Color, Entity as CesiumEntity } from "cesium";
import type { Viewer as CesiumViewer } from "cesium";
import type { GeoEntity, CesiumEntityOptions } from "@/core/plugins/PluginTypes";

/**
 * Renders glowing 3D hexagons (cylinders with 6 slices) for seismic events
 * or other data points configured with options.type === "hexagon".
 */
export function useHexagonRendering(
    viewer: CesiumViewer | null,
    isReady: boolean,
    hexagonEntities: Array<{ entity: GeoEntity; options: CesiumEntityOptions }>
) {
    const activeHexagonsRef = useRef<Map<string, CesiumEntity>>(new Map());

    useEffect(() => {
        if (!viewer || !isReady || viewer.isDestroyed()) return;

        const activeHexagons = activeHexagonsRef.current;
        const currentIds = new Set<string>();

        for (const { entity, options } of hexagonEntities) {
            const id = entity.id;
            currentIds.add(id);

            const mag = (entity.properties.mag as number) || 1.0;
            const size = options.size || 10;
            
            // Refined UI dimensions to prevent oversized prisms and overlapping clutter
            let height = mag * 10000;
            let radius = size * 1500;
            
            if (entity.pluginId === "entity-density" || id.startsWith("hexfeed-")) {
                // Density columns should be uniform in radius to prevent overlapping in their grid cells
                radius = 35000; // 35km constant radius fits elegantly on the globe grid
                height = Math.min(120000, mag * 8000); // Max height 120km (down from 450km)
            } else {
                // Earthquakes or other point hexagons
                height = Math.min(80000, mag * 10000); // Max height 80km (down from 300km)
                radius = Math.min(20000, size * 1500);   // Max radius 20km (down from 80km)
            }
            const colorStr = options.color || "#ff8800";
            const color = Color.fromCssColorString(colorStr).withAlpha(0.65);
            const outlineColor = Color.WHITE.withAlpha(0.85);

            // Center of cylinder is height / 2 above ground
            const position = Cartesian3.fromDegrees(entity.longitude, entity.latitude, height / 2);

            const existing = activeHexagons.get(id);
            if (existing) {
                // Update existing entity
                existing.position = position as any;
                if (existing.cylinder) {
                    existing.cylinder.length = height as any;
                    existing.cylinder.topRadius = radius as any;
                    existing.cylinder.bottomRadius = radius as any;
                    existing.cylinder.material = color as any;
                }
                continue;
            }

            // Create new entity
            const hexagonEntity = viewer.entities.add({
                id: `hexagon-${id}`,
                position: position,
                cylinder: {
                    length: height,
                    topRadius: radius,
                    bottomRadius: radius,
                    slices: 6, // 6 slices = Hexagon
                    material: color,
                    outline: true,
                    outlineColor: outlineColor,
                    outlineWidth: 1.5,
                },
                label: options.labelText ? {
                    text: options.labelText,
                    font: options.labelFont || "10px monospace",
                    fillColor: Color.WHITE,
                    outlineColor: Color.BLACK,
                    outlineWidth: 2,
                    pixelOffset: { x: 0, y: -20 } as any,
                    disableDepthTestDistance: Number.POSITIVE_INFINITY,
                } : undefined,
            });

            activeHexagons.set(id, hexagonEntity);
        }

        // Cleanup removed hexagons
        for (const [id, entity] of activeHexagons.entries()) {
            if (!currentIds.has(id)) {
                if (!viewer.isDestroyed()) {
                    viewer.entities.remove(entity);
                }
                activeHexagons.delete(id);
            }
        }

        viewer.scene.requestRender();

        return () => {
            if (!viewer.isDestroyed()) {
                for (const entity of activeHexagons.values()) {
                    viewer.entities.remove(entity);
                }
            }
            activeHexagons.clear();
        };
    }, [viewer, isReady, hexagonEntities]);
}

/**
 * LOD hook: renders nearby model-type entities as 3D glTF models,
 * while distant ones fall back to the billboard/point pipeline.
 *
 * Strategy: All model-type entities ALSO go through useEntityRendering
 * as billboards (fallback). This hook promotes nearby ones to 3D models
 * and hides their billboard, capping GPU model count to ~MAX_MODELS.
 */
import { useEffect, useRef } from "react";
import {
    Cartesian3,
    Color,
    HeadingPitchRoll,
    Math as CesiumMath,
    Model,
    Transforms,
    Matrix4,
} from "cesium";
import type { Viewer as CesiumViewer } from "cesium";
import type { GeoEntity, CesiumEntityOptions } from "@/core/plugins/PluginTypes";
import type { AnimatableItem } from "../EntityRenderer";

/** Maximum concurrent 3D models to keep GPU happy */
const MAX_MODELS = 30;
/** Distance threshold in meters ΓÇö closer than this gets a 3D model */
const MODEL_DISTANCE_M = 80_000; // 80km

/** Scratch objects reused per LOD update to avoid heap allocations */
const lodScratchHPR = new HeadingPitchRoll();
const lodScratchMatrix = new Matrix4();

interface ActiveModel {
    model: any;
    entityId: string;
    distance: number;
}

function buildModelMatrix(position: Cartesian3, heading: number, scale: number, headingOffset: number = 0): Matrix4 {
    lodScratchHPR.heading = CesiumMath.toRadians(heading + headingOffset);
    lodScratchHPR.pitch = 0;
    lodScratchHPR.roll = 0;
    Transforms.headingPitchRollToFixedFrame(
position,
lodScratchHPR,
        undefined,
undefined,
lodScratchMatrix
);
    Matrix4.multiplyByUniformScale(lodScratchMatrix, scale, lodScratchMatrix);
    // Return a clone since the caller stores this in the model
    return Matrix4.clone(lodScratchMatrix);
}

export function useModelRendering(
    viewer: CesiumViewer | null,
    isReady: boolean,
    animatablesMapRef: React.MutableRefObject<Map<string, AnimatableItem>>
) {
    const activeModelsRef = useRef<Map<string, ActiveModel>>(new Map());
    const loadingRef = useRef<Set<string>>(new Set());

    useEffect(() => {
        if (!viewer || !isReady || viewer.isDestroyed()) return;

        const activeModels = activeModelsRef.current;
        const loading = loadingRef.current;

        const updateLOD = () => {
            if (viewer.isDestroyed()) return;
            const camPos = viewer.camera.positionWC;
            const animatables = animatablesMapRef.current;
            if (!animatables) return;

            // 1. Score all model-type entities by distance
            const candidates: Array<{ id: string; item: AnimatableItem; distance: number }> = [];

            for (const [id, item] of animatables.entries()) {
                if (item.options.type !== "model" || !item.options.modelUrl) continue;
                const dist = Cartesian3.distance(camPos, item.posRef);
                if (dist < MODEL_DISTANCE_M) {
                    candidates.push({ id, item, distance: dist });
                }
            }

            // Sort by distance (closest first) and cap at MAX_MODELS
            candidates.sort((a, b) => a.distance - b.distance);
            const promoted = candidates.slice(0, MAX_MODELS);
            const promotedIds = new Set(promoted.map((c) => c.id));

            // 2. Remove models that are no longer promoted
            for (const [id, active] of activeModels.entries()) {
                if (!promotedIds.has(id)) {
                    try { viewer.scene.primitives.remove(active.model); } catch { /**/ }
                    activeModels.delete(id);
                    // Show billboard again and clear promoted flag
                    const item = animatables.get(id);
                    if (item) {
                        item._modelPromoted = false;
                        item.promotedModel = undefined;
                        if (item.primitive) item.primitive.show = true;
                    }
                }
            }

            // 3. Create/update promoted models
            for (const { id, item, distance } of promoted) {
                const pos = item.posRef;
                const heading = item.entity.heading || 0;
                const scale = item.options.modelScale || 1.0;
                const offset = item.options.modelHeadingOffset || 0;

                const existing = activeModels.get(id);
                if (existing) {
                    // Update transform
                    const newMatrix = buildModelMatrix(pos, heading, scale, offset);
                    Matrix4.clone(newMatrix, existing.model.modelMatrix);
                    existing.distance = distance;
                    // Keep billboard hidden via flag
                    item._modelPromoted = true;
                    item.promotedModel = existing.model;
                    if (item.primitive) item.primitive.show = false;
                    continue;
                }

                // Skip if already loading
                if (loading.has(id)) {
                    item._modelPromoted = true;
                    if (item.primitive) item.primitive.show = false;
                    continue;
                }

                // Load new model
                loading.add(id);
                item._modelPromoted = true;
                if (item.primitive) item.primitive.show = false;

                Model.fromGltfAsync({
                    url: item.options.modelUrl!,
                    modelMatrix: buildModelMatrix(pos, heading, scale, offset),
                    minimumPixelSize: item.options.modelMinPixelSize ?? 24,
                    maximumScale: 20000,
                    color: item.options.color ? Color.fromCssColorString(item.options.color) : undefined,
                    silhouetteColor: Color.CYAN,
                    silhouetteSize: 0,
                    id: { _wwvEntity: item.entity },
                }).then((model) => {
                    loading.delete(id);
                    if (!viewer || viewer.isDestroyed()) return;
                    // Re-check still promoted
                    if (!animatables.has(id)) return;
                    viewer.scene.primitives.add(model);
                    activeModels.set(id, { model, entityId: id, distance });

                    const refreshedItem = animatables.get(id);
                    if (refreshedItem) refreshedItem.promotedModel = model;
                }).catch(() => {
                    loading.delete(id);
                    // Show billboard again on failure
                    item._modelPromoted = false;
                    item.promotedModel = undefined;
                    if (item.primitive) item.primitive.show = true;
                });
            }
        };

        // Run LOD check at a lower frequency (every 10 frames)
        let frameCount = 0;
        const onPreUpdate = () => {
            if (frameCount++ % 10 === 0) updateLOD();
        };

        viewer.scene.preUpdate.addEventListener(onPreUpdate);

        return () => {
            if (!viewer.isDestroyed()) {
                viewer.scene.preUpdate.removeEventListener(onPreUpdate);
            }
            // Cleanup all active models
            for (const [, active] of activeModels.entries()) {
                try { viewer.scene.primitives.remove(active.model); } catch { /**/ }
            }
            activeModels.clear();
            loading.clear();
        };
    }, [viewer, isReady, animatablesMapRef]);
}

import { useEffect } from "react";
import { useStore } from "@/core/state/store";
import { isDemo } from "@/core/edition";

export function usePersistentDataSync() {
    const updateMapConfig = useStore((s) => s.updateMapConfig);
    const initFavorites = useStore((s) => s.initFavorites);

    // Load graphics settings from cookie on mount
    useEffect(() => {
        try {
            const match = document.cookie.match(/(^| )wwv_graphics=([^;]+)/);
            if (match) {
                const saved = JSON.parse(decodeURIComponent(match[2]));
                updateMapConfig(saved);
            }
        } catch (e) {
            console.warn("[GlobeView] Failed to load graphics settings from cookie", e);
        }
    }, [updateMapConfig]);

    // Initialize favorites from cookie or API
    useEffect(() => {
        if (isDemo) {
            try {
                const match = document.cookie.match(/(^| )wwv_favorites=([^;]+)/);
                if (match) {
                    const saved = JSON.parse(decodeURIComponent(match[2]));
                    initFavorites(saved);
                }
            } catch (e) {
                console.warn("[GlobeView] Failed to load favorites from cookie", e);
            }
        } else {
            fetch("/api/user/favorites")
                .then((res) => {
                    if (res.status === 401) return []; // Unauthenticated, safe to ignore
                    if (res.ok) return res.json();
                    throw new Error("Failed to load favorites");
                })
                .then((data) => {
                    if (Array.isArray(data)) {
                        const mappedFavorites = data.map((item: any) => ({
                            id: item.entityId, // Restore entity property matching
                            pluginId: item.pluginId,
                            label: item.label,
                            pluginName: item.pluginName,
                            lastSeen: new Date(item.lastSeen).getTime()
                        }));
                        initFavorites(mappedFavorites);
                    }
                })
                .catch((err) => console.error("[GlobeView] Favorites fetch error:", err));
        }
    }, [initFavorites]);
}

import { useEffect } from "react";
import type { Viewer as CesiumViewer, Entity as CesiumEntity } from "cesium";
import { Cartesian3, CallbackProperty } from "cesium";
import type { AnimatableItem } from "../EntityRenderer";

const SELECTION_BOX_SVG = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(`
<svg width="64" height="64" viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg">
