  <!-- Bottom Right -->
  <path d="M 62 44 L 62 62 L 44 62" fill="none" stroke="#00fff7" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>
</svg>
`)}`;

export function useSelectionAnchor(
    viewer: CesiumViewer | null,
    isReady: boolean,
    selectedEntity: any,
    lockedEntityId: string | null,
    selectionEntityRef: React.MutableRefObject<CesiumEntity | null>,
    animatablesMapRef: React.MutableRefObject<Map<string, AnimatableItem>>
) {
    // Initialization of Selection Entity
    useEffect(() => {
        if (!viewer || viewer.isDestroyed() || !isReady) return;

        let entity: CesiumEntity | null = null;
        try {
            // Create a hidden entity for camera tracking/flying
            if (!viewer.entities) {
                console.warn("[GlobeView] Viewer entities collection not available during selection anchor init");
                return;
            }

            entity = viewer.entities.add({
                id: "__wwv_selection_anchor",
                point: {
                    pixelSize: 0,
                },
                billboard: {
                    image: SELECTION_BOX_SVG,
                    width: 56,
                    height: 56,
                    show: false,
                    disableDepthTestDistance: Number.POSITIVE_INFINITY, // Always rendered on top
                } as any
            });
            selectionEntityRef.current = entity;
        } catch (error) {
            console.warn("[GlobeView] Error accessing viewer entities:", error);
            return;
        }

        return () => {
            try {
                if (viewer && !viewer.isDestroyed() && viewer.entities && entity) {
                    viewer.entities.remove(entity);
                }
            } catch (error) {
                // Ignore cleanup errors if viewer is partially destroyed
            }
        };
    }, [viewer, isReady, selectionEntityRef]);

    // Update Selection Entity Position ΓÇö use CallbackProperty to track extrapolated position
    useEffect(() => {
        const selectionEntity = selectionEntityRef.current;
        if (!selectionEntity) return;

        if (selectionEntity.billboard) {
            selectionEntity.billboard.show = (!!selectedEntity && lockedEntityId !== selectedEntity.id) as any;
        }

        if (!selectedEntity) {
            if (viewer && !viewer.isDestroyed()) viewer.scene.requestRender();
            return;
        }

        const entityId = selectedEntity.id;

        // Use a CallbackProperty so viewer.trackedEntity follows the
        // extrapolated position in real-time, not just the polled position.
        const fallbackPos = Cartesian3.fromDegrees(
            selectedEntity.longitude,
            selectedEntity.latitude,
            selectedEntity.altitude || 0
        );

        selectionEntity.position = new CallbackProperty((time, result) => {
            const item = animatablesMapRef.current?.get(entityId);
            const pos = item ? item.posRef : fallbackPos;
            return Cartesian3.clone(pos, result);
        }, false) as any;

        if (viewer && !viewer.isDestroyed()) viewer.scene.requestRender();
    }, [selectedEntity, lockedEntityId, selectionEntityRef, animatablesMapRef, viewer]);
}

import { useEffect } from "react";
import type { Viewer as CesiumViewer } from "cesium";
import {
 Cartesian3, Color, Ellipsoid, Material, DistanceDisplayCondition, Cartographic
} from "cesium";
import type { AnimatableItem } from "../EntityRenderer";
import { getCollections } from "../EntityRenderer";

export function useTrailRendering(
    viewer: CesiumViewer | null,
    isReady: boolean,
    animatablesMapRef: React.MutableRefObject<Map<string, AnimatableItem>>
) {
    useEffect(() => {
        if (!viewer || !isReady || viewer.isDestroyed()) return;

        let lastUpdateTime = 0;
        const updateTrails = () => {
            if (viewer.isDestroyed()) return;
            const now = Date.now();
            if (now - lastUpdateTime < 250) return; // Only process trails at 4Hz to prevent 50k item JS map-loop from locking the thread
            lastUpdateTime = now;

            const collections = getCollections(viewer);
            const {polylines} = collections;
            if (!polylines) return;

            const MAX_DIST_SQ = 250000000000; // 500km squared
            const cameraPos = viewer.camera.position;

            // Manage additions and removals
            for (const item of animatablesMapRef.current.values()) {
                const history = item.entity.properties.history as any[];
                const trailOpts = item.options.trailOptions;

                if (history && history.length > 0 && trailOpts) {
                    const isSelected = item.lastHighlightState === 'selected';
                    const isHovered = item.lastHighlightState === 'hovered';
                    const shouldHighlight = isSelected || isHovered;

                    const distSq = Cartesian3.distanceSquared(cameraPos, item.posRef);
                    const isClose = distSq < MAX_DIST_SQ;

                    // WebGL Geometry Culling: Only push trailing polylines to Cesium memory if they are near the camera or actively highlighted
                    if (isClose || shouldHighlight) {
                        const tipCartographic = Cartographic.fromCartesian(item.posRef);
                        const altOffset = (item.entity.altitude || 0) + 10; // 10m offset perfectly synchronizes with SelectionHandler.ts dashed trail
                        const latestHistoryTs = history.length > 0 ? history[history.length - 1].ts : 0;

                        if (!item.trailPositions || item._lastHistoryTs !== latestHistoryTs) {
                            try {
                                item.trailPositions = history.map((point) => Cartesian3.fromDegrees(
                                        point.lon || point.longitude || 0,
                                        point.lat || point.latitude || 0,
                                        altOffset,
                                        Ellipsoid.WGS84
                                    ));

                                if (tipCartographic) {
                                    item.trailPositions.push(
                                        Cartesian3.fromRadians(
                                            tipCartographic.longitude,
                                            tipCartographic.latitude,
                                            altOffset,
                                            Ellipsoid.WGS84
                                        )
                                    );
                                } else {
                                    item.trailPositions.push(Cartesian3.clone(item.posRef));
                                }

                                item._lastHistoryTs = latestHistoryTs;
                            } catch (e) {
                                console.warn("[useTrailRendering] Invalid history formatting", e);
                                continue;
                            }
                        } else {
                            // History hasn't changed, but posRef is smoothly interpolating forward.
                            // Ensure the tip of the trail stays mathematically snapped to the moving mesh above.
                            if (item.trailPositions.length > 0) {
                                if (tipCartographic) {
                                    item.trailPositions[item.trailPositions.length - 1] = Cartesian3.fromRadians(
                                        tipCartographic.longitude,
                                        tipCartographic.latitude,
                                        altOffset,
                                        Ellipsoid.WGS84
                                    );
                                } else {
                                    item.trailPositions[item.trailPositions.length - 1] = Cartesian3.clone(item.posRef);
                                }
                            }
                        }

                        // Always assign back to primitive to hint Cesium to rebuild vertex buffer
                        if (item.polylinePrimitive && item.trailPositions) {
                            item.polylinePrimitive.positions = item.trailPositions;
                        }

                        if (!item.polylinePrimitive) {
                            const colorStr = trailOpts.color || item.options.color || "#0ef";
                            const baseColor = Color.fromCssColorString(colorStr);

                            let material;
                            if (trailOpts.dashPattern === "dashed") {
                                material = Material.fromType("PolylineDash", { color: baseColor });
                            } else if (trailOpts.opacityFade) {
                                material = Material.fromType("PolylineGlow", {
                                    color: baseColor,
                                    glowPower: 0.1,
                                    taperPower: 1.0
                                });
                            } else {
                                material = Material.fromType("Color", { color: baseColor.withAlpha(0.7) });
                            }

                            item.polylinePrimitive = polylines.add({
                                positions: item.trailPositions,
                                width: trailOpts.width || 2,
                                material,
                                distanceDisplayCondition: new DistanceDisplayCondition(0, 500000)
                            });
                        }

                        // Dynamically update trailing visibility and highlighting based on selection state
                        if (item.polylinePrimitive) {
                            const targetWidth = shouldHighlight ? (trailOpts.width || 2) * 2.5 : (trailOpts.width || 1);
                            if (item.polylinePrimitive.width !== targetWidth) item.polylinePrimitive.width = targetWidth;

                            const currentDDC = item.polylinePrimitive.distanceDisplayCondition;
                            if (shouldHighlight) {
                                if (currentDDC !== undefined) {
                                    item.polylinePrimitive.distanceDisplayCondition = undefined;
                                }
                            } else if (currentDDC === undefined || currentDDC.near !== 0 || currentDDC.far !== 500000) {
                                    item.polylinePrimitive.distanceDisplayCondition = new DistanceDisplayCondition(0, 500000);
                                }
                        }
                    } else {
                        // Math-culled: remove from geometry collection to save massive memory
                        if (item.polylinePrimitive) {
                            polylines.remove(item.polylinePrimitive);
                            item.polylinePrimitive = undefined;
                        }
                    }
                } else if (item.polylinePrimitive) {
                    // Removed or no longer valid
                    if (item.polylinePrimitive) {
                        polylines.remove(item.polylinePrimitive);
                    }
                    item.polylinePrimitive = undefined;
                    item.trailPositions = undefined;
                }
            }
        };

        viewer.scene.preUpdate.addEventListener(updateTrails);

        return () => {
            if (!viewer.isDestroyed()) {
                viewer.scene.preUpdate.removeEventListener(updateTrails);
                const collections = getCollections(viewer);
                const {polylines} = collections;
                if (polylines) {
                    for (const item of animatablesMapRef.current.values()) {
                        if (item.polylinePrimitive) {
                            polylines.remove(item.polylinePrimitive);
                            item.polylinePrimitive = undefined;
                            item.trailPositions = undefined;
                        }
                    }
                }
            }
        };
    }, [viewer, isReady, animatablesMapRef]);
}

/**
 * DOD: Primitive creation and cleanup helpers for EntityRenderer.
 * Separated from the main renderer to keep individual files under 150 lines.
 */
import {
    Cartesian3,
    Color,
    NearFarScalar,
    VerticalOrigin,
    HorizontalOrigin,
    Math as CesiumMath,
    PointPrimitiveCollection,
    BillboardCollection,
    LabelCollection,
    DistanceDisplayCondition,
    HeightReference,
} from "cesium";
import type { GeoEntity, CesiumEntityOptions } from "@/core/plugins/PluginTypes";
import type { AnimatableItem } from "./EntityRenderer";
import { scratchPosition, getCachedColor } from "./renderCaches";
import { globalRequestRender } from "./EntityRenderer";
import { getHiResIconSync, getHiResIcon, getBaseSize } from "./iconUpscaler";

/** Default billboard scale applied when plugin does not specify iconScale. */
const DEFAULT_BILLBOARD_SCALE = 0.7;

/** Returns a touch-friendly default point size: larger on mobile. */
function defaultPointSize(): number {
    if (typeof window !== "undefined" && window.matchMedia("(pointer: coarse)").matches) return 12;
    return 8;
}

const dotIconCache = new Map<string, string>();

/** Generates a simple circular dot SVG to act as a fallback billboard for points, enabling pixelOffsets. */
export function getDefaultDotIcon(color: Color, outlineColor: Color, outlineWidth: number, size: number): string {
    const colorHash = color.toCssColorString();
    const strokeHash = outlineColor.toCssColorString();
    const key = `${colorHash}_${strokeHash}_${outlineWidth}_${size}`;
    let cached = dotIconCache.get(key);
    if (!cached) {
        const actualSize = size + outlineWidth * 2 + 4;
        const center = actualSize / 2;
        const radius = size / 2;
        const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${actualSize}" height="${actualSize}">
            <circle cx="${center}" cy="${center}" r="${radius}" fill="${colorHash}" stroke="${strokeHash}" stroke-width="${outlineWidth}"/>
        </svg>`;
        cached = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
        dotIconCache.set(key, cached);
    }
    return cached;
}

/** Update an existing AnimatableItem with new entity data. */
export function updateExistingItem(item: AnimatableItem, entity: GeoEntity, options: CesiumEntityOptions, color: Color) {
    item.entity = entity;
    item.options = options;
    Cartesian3.clone(scratchPosition, item.posRef);
    item.basePosition = undefined;
    item.velocityVector = undefined;
    item.baseColor = color;
    item.baseOutlineColor = getCachedColor(options.outlineColor) || Color.BLACK;

    const isGroundBased = (entity.altitude || 0) < 100;
    const disableDepthTestDistance = isGroundBased
        ? Number.POSITIVE_INFINITY
        : options.disableDepthTestDistance;

    if (item.primitive.disableDepthTestDistance !== disableDepthTestDistance) {
        item.primitive.disableDepthTestDistance = disableDepthTestDistance;
    }

    const billboardColor = (options as any)._isAutoSVG ? Color.WHITE : color;

    if (!Color.equals(item.primitive.color, billboardColor)) item.primitive.color = billboardColor;
    if (!Cartesian3.equals(item.primitive.position, item.posRef)) item.primitive.position = item.posRef;
    if (options.iconUrl) {
        const baseSize = getBaseSize();
        if (item.primitive.width !== baseSize) item.primitive.width = baseSize;
        if (item.primitive.height !== baseSize) item.primitive.height = baseSize;

        const hiRes = getHiResIconSync(options.iconUrl) ?? options.iconUrl;
        if (item.primitive.image !== hiRes) {
            item.primitive.image = hiRes;
            if (hiRes === options.iconUrl) {
                getHiResIcon(options.iconUrl).then((url) => {
                    if (item.primitive && !item.primitive.isDestroyed?.()) {
                        item.primitive.image = url;
                        globalRequestRender();
                    }
                });
            }
        }
        const rot = options.rotation ? -CesiumMath.toRadians(options.rotation) : 0;
        if (item.primitive.rotation !== rot) item.primitive.rotation = rot;
        if (item.primitive.width !== getBaseSize()) item.primitive.width = getBaseSize();
        if (item.primitive.height !== getBaseSize()) item.primitive.height = getBaseSize();
        const targetScale = options.iconScale ?? DEFAULT_BILLBOARD_SCALE;
        if (item.primitive.scale !== targetScale) item.primitive.scale = targetScale;
    } else {
        const newSize = options.size || defaultPointSize();
        if (item.primitive.pixelSize !== newSize) item.primitive.pixelSize = newSize;
        if (!Color.equals(item.primitive.outlineColor, item.baseOutlineColor)) item.primitive.outlineColor = item.baseOutlineColor;
        const newOutlineWidth = options.outlineWidth || 1;
        if (item.primitive.outlineWidth !== newOutlineWidth) item.primitive.outlineWidth = newOutlineWidth;
    }
}

/** Create a new primitive + AnimatableItem and add it to the existingMap. */
export function createNewItem(
    entity: GeoEntity,
options: CesiumEntityOptions,
color: Color,
clickId: any,
    existingMap: Map<string, AnimatableItem>,
    points: PointPrimitiveCollection,
billboards: BillboardCollection,
) {
    const newPosition = Cartesian3.clone(scratchPosition);
    const outlineColor = getCachedColor(options.outlineColor) || Color.BLACK;
    const ddc = options.distanceDisplayCondition
        ? new DistanceDisplayCondition(options.distanceDisplayCondition.near, options.distanceDisplayCondition.far)
        : undefined;
    // Use the hi-res cached icon if available, otherwise use raw and trigger async upscale
    const resolvedIcon = options.iconUrl ? (getHiResIconSync(options.iconUrl) ?? options.iconUrl) : undefined;
    const baseSize = getBaseSize();
    const billboardColor = (options as any)._isAutoSVG ? Color.WHITE : color;

    // Performance optimization: Ground-based entities (altitude < 100m) should disable
    // Cesium's heavy depth testing and instead use our efficient manual horizon culling.
    // Air-based entities keep depth testing enabled for realistic occlusion against mountains.
    const isGroundBased = (entity.altitude || 0) < 100;
    const disableDepthTestDistance = isGroundBased
        ? Number.POSITIVE_INFINITY
        : options.disableDepthTestDistance;

        const addedPrimitive = options.iconUrl
        ? billboards.add({
            position: newPosition,
image: resolvedIcon,
            width: baseSize,
height: baseSize,
show: false,
            scale: options.iconScale ?? DEFAULT_BILLBOARD_SCALE,
            verticalOrigin: VerticalOrigin.CENTER,
horizontalOrigin: HorizontalOrigin.CENTER,
            rotation: options.rotation ? -CesiumMath.toRadians(options.rotation) : 0,
            color: billboardColor,
scaleByDistance: new NearFarScalar(1e6, 1.0, 2e7, 0.5),
id: clickId,
            // eyeOffset: new Cartesian3(0, 0, options.depthBias ?? -10000), // Small depth bias for far-range terrain
            // WARNING: Do NOT use heightReference: HeightReference.CLAMP_TO_GROUND here.
            // It causes severe lag/performance drops with thousands of dynamic entities.
            disableDepthTestDistance,
distanceDisplayCondition: ddc,
        })
        : points.add({
            position: newPosition,
pixelSize: options.size || defaultPointSize(),
color,
outlineColor,
            outlineWidth: options.outlineWidth || 1,
show: false,
            scaleByDistance: new NearFarScalar(1e6, 1.0, 2e7, 0.5),
id: clickId,
            disableDepthTestDistance,
distanceDisplayCondition: ddc,
        });

    existingMap.set(entity.id, {
        primitive: addedPrimitive,
labelPrimitive: undefined,
entity,
posRef: newPosition,
        options,
baseColor: color,
baseOutlineColor: outlineColor,
lastHighlightState: 'normal'
    });

    // Trigger async upscale for newly spawned primitives that missed the cache
    if (options.iconUrl && resolvedIcon === options.iconUrl) {
        getHiResIcon(options.iconUrl).then((url) => {
            const bb = addedPrimitive as any;
            if (bb && !bb.isDestroyed?.()) {
                bb.image = url;
                globalRequestRender();
            }
        });
    }
}

/** Cleanup primitives for entities no longer in visibleEntities. */
export function cleanupRemovedEntities(
    existingMap: Map<string, AnimatableItem>,
currentIds: Set<string>,
    points: PointPrimitiveCollection,
billboards: BillboardCollection,
labels: LabelCollection,
    polylines: any
) {
    for (const [id, item] of existingMap.entries()) {
        if (!currentIds.has(id)) {
            if (item.options.iconUrl) billboards.remove(item.primitive); else points.remove(item.primitive);
            item.primitive = null;
            if (item.labelPrimitive) { labels.remove(item.labelPrimitive); item.labelPrimitive = undefined; }
            if (item.polylinePrimitive) {
                polylines.remove(item.polylinePrimitive);
            }
            item.polylinePrimitive = undefined;
            item.trailPositions = undefined;
            existingMap.delete(id);
        }
    }
}

/**
 * DOD: Color cache and scratch allocations for the rendering pipeline.
 *
 * Centralizes cache utilities that are shared across EntityRenderer,
 * AnimationLoop, and other rendering modules.
 */
import { Cartesian3, Color, Ellipsoid } from "cesium";
import type { CesiumEntityOptions } from "@/core/plugins/PluginTypes";
import type { AnimatableItem } from "./EntityRenderer";

// ΓöÇΓöÇ Scratch Cartesian3 for position computation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Reused across all renderSingleEntity calls to avoid heap alloc per entity.
export const scratchPosition = new Cartesian3();

// ΓöÇΓöÇ Color cache ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Deduplicates Color objects by CSS string. Most plugins reuse a
// small set of colors (e.g. altitude bands), avoiding thousands
// of Color.fromCssColorString() calls per render cycle.
const colorCache = new Map<string, Color>();

/** Resolve a CSS color string to a cached Color instance. */
export function getCachedColor(css: string | undefined): Color {
    if (!css) return Color.CYAN;
    let c = colorCache.get(css);
    if (!c) {
        c = Color.fromCssColorString(css);
        colorCache.set(css, c);
    }
    return c;
}

/**
 * Resolve entity color from options, defaulting to cyan.
 * Uses the color cache for zero-allocation on repeated CSS strings.
 */
export function getEntityColor(options: CesiumEntityOptions): Color {
    return getCachedColor(options.color);
}

// ΓöÇΓöÇ Stable array cache ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Avoids Array.from(map.values()) allocation every render cycle.
let stableAnimatables: AnimatableItem[] = [];
let stableArrayDirty = true;

/** Mark that the animatables map changed and the stable array needs rebuilding. */
export function markAnimatablesDirty(): void {
    stableArrayDirty = true;
}

/** Return a stable array of AnimatableItems, only rebuilding when dirty. */
export function getStableAnimatables(map: Map<string, AnimatableItem>): AnimatableItem[] {
    if (stableArrayDirty) {
        stableAnimatables = Array.from(map.values());
        stableArrayDirty = false;
    }
    return stableAnimatables;
}

/**
 * stackAnimation ΓÇö Per-frame lerping of spider offsets and hub badge management.
 *
 * Called from the AnimationLoop every frame. Smoothly interpolates
 * pixelOffset towards the target (expand) or back to zero (collapse).
 * Uses a dedicated persistent Billboard per stack for the textual hub badge.
 */
import {
 Cartesian2, Cartesian3, HorizontalOrigin, VerticalOrigin, NearFarScalar,  Color
} from "cesium";
import type { LabelCollection, BillboardCollection } from "cesium";
import {
    getStacks, getSpiderOffset, isAnyStackExpanded,
    type EntityStack,
} from "./StackManager";
import { FADED_OPACITY } from "./animationHelpers";

/** Scale hub icons down when zooming out. */
const hubScaleByDistance = new NearFarScalar(2.0e6, 1.0, 1.5e7, 0.5);

/** Duration of expand/collapse animation in ms. */
const ANIM_DURATION_MS = 220;

/**
 * Radius of the cluster hub background circle.
 * Adjust this to scale the black half-transparent badge.
 */
const HUB_BG_RADIUS = 14;

/** Reusable scratch Cartesian2 to avoid allocation. */
const scratchOffset = new Cartesian2();

/** Tracks the dedicated textual badge primitive for each stack. */
const hubBillboards = new Map<string, any>();
const clusterIconCache = new Map<string, string>();

/** Generates a base64 encoded SVG for the cluster hub icon. */
function getClusterIcon(count: number, hexColor: string): string {
    const cacheKey = `${count}_${hexColor}`;
    let cached = clusterIconCache.get(cacheKey);
    if (cached) return cached;

    const size = 36;
    const center = size / 2;
    const textStr = count > 99 ? '99+' : count.toString();
    const fillValue = "rgba(15, 23, 42, 0.95)";
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">
        <circle cx="${center}" cy="${center}" r="${HUB_BG_RADIUS}" fill="${fillValue}" stroke="${hexColor}" stroke-width="2.5"/>
        <text x="${center}" y="${center + 1}" font-family="Inter, sans-serif" font-size="14px" font-weight="bold" fill="#ffffff" text-anchor="middle" dominant-baseline="middle">${textStr}</text>
    </svg>`;

    cached = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
    clusterIconCache.set(cacheKey, cached);
    return cached;
}

/** Lerp a single value. */
function lerp(a: number, b: number, t: number): number { return a + (b - a) * t; }

/**
 * Run one animation tick for all stacks.
 * Returns true if ANY stack is currently animating (requiring a continuous render).
 */
export function tickStackAnimation(labels: LabelCollection | null, billboards: BillboardCollection | null): boolean {
    const now = Date.now();
    const activeStacks = getStacks();
    let needsRender = false;

    // 1. Garbage Collect abandoned hub billboards
    for (const [stackId, bb] of hubBillboards.entries()) {
        if (!activeStacks.has(stackId)) {
            if (billboards) billboards.remove(bb);
            hubBillboards.delete(stackId);
            needsRender = true;
        }
    }

    // 2. Tick active stacks
    for (const stack of activeStacks.values()) {
        const running = tickSingle(stack, now, billboards);
        if (running) needsRender = true;
    }

    return needsRender;
}

function tickSingle(stack: EntityStack, now: number, billboards: BillboardCollection | null): boolean {
    const { state, stateStartMs, children } = stack;
    const elapsed = now - stateStartMs;
    const t = Math.min(elapsed / ANIM_DURATION_MS, 1.0);

    const isOpen = state === "expanding" || state === "expanded";
    const isClosed = state === "collapsed" || state === "collapsing";
    const isAnimating = state === "expanding" || state === "collapsing";

    // Transition end
    if (state === "expanding" && t >= 1) stack.state = "expanded";
    if (state === "collapsing" && t >= 1) {
        stack.state = "collapsed";

        // Final pass to ensure everything hidden completely
        for (let i = 0; i < children.length; i++) {
            const prim = children[i].primitive;
            if (prim && !prim.isDestroyed?.() && prim.show) prim.show = false;
        }
    }

    // Optimization: If it's collapsed, we don't need to recalculate or apply offsets and visibility
    const isRestingCollapsed = stack.state === "collapsed";

    if (!isRestingCollapsed) {
        (stack as any)._enforcedHidden = false;
        // Animate ALL children (no one is left behind!)
        for (let i = 0; i < children.length; i++) {
            const item = children[i];
            const prim = item.primitive;
            if (!prim || prim.isDestroyed?.()) continue;

            const offset = getSpiderOffset(item.entity.id);
            if (!offset) continue;

            // Animate pixel offset
            if (state === "expanding") {
                offset.currentX = lerp(0, offset.targetX, easeOut(t));
                offset.currentY = lerp(0, offset.targetY, easeOut(t));
            } else if (state === "collapsing") {
                offset.currentX = lerp(offset.targetX, 0, easeOut(t));
                offset.currentY = lerp(offset.targetY, 0, easeOut(t));
            } else if (state === "expanded") {
                offset.currentX = offset.targetX;
                offset.currentY = offset.targetY;
            }

            // Apply pixel offset
            if (prim.pixelOffset !== undefined) {
                Cartesian2.fromElements(offset.currentX, offset.currentY, scratchOffset);
                prim.pixelOffset = scratchOffset;
            }

            // Show/hide child items
            if (isOpen || state === "collapsing") {
                const shouldShow = !item._occluded;
                if (prim.show !== shouldShow) prim.show = shouldShow;
            }
        }
    } else {
        // Enforce the collapsed hidden state exactly once to catch newly clustered primitives
        if (!(stack as any)._enforcedHidden) {
            for (let i = 0; i < children.length; i++) {
                const prim = children[i].primitive;
                if (prim && !prim.isDestroyed?.() && prim.show) prim.show = false;
            }
            (stack as any)._enforcedHidden = true;
        }
    }

    // Manage the dedicated central Hub Billboard
    if (billboards && stack.children.length > 1) {
        manageDedicatedHub(stack, billboards);
    }

    return isAnimating;
}

function manageDedicatedHub(stack: EntityStack, billboards: BillboardCollection) {
    let bb = hubBillboards.get(stack.id);
    const count = stack.children.length;

    // Check if the hubItem's baseColor has changed since we last cached it
    const currentBaseColor = stack.hubItem.baseColor?.toCssColorString() ?? "#ffffff";
    if ((stack.hubItem as any)._cachedCssColor !== currentBaseColor) {
        (stack.hubItem as any)._cachedCssColor = currentBaseColor;
    }

    const cssColor = (stack.hubItem as any)._cachedCssColor;
    const expectedImage = getClusterIcon(count, cssColor);

    const anyExpanded = isAnyStackExpanded();
    const isExpanded = stack.state === "expanded" || stack.state === "expanding";
    const isFaded = anyExpanded && !isExpanded;
    // Set opacity for unexpanded hubs when a spiderifier is active
    const targetColor = isFaded ? new Color(1.0, 1.0, 1.0, FADED_OPACITY) : Color.WHITE;
    const isVisible = !stack.hubItem._occluded;

    if (!bb || bb.isDestroyed?.()) {
        bb = billboards.add({
            position: stack.hubItem.posRef,
            image: expectedImage,
            color: targetColor,
            horizontalOrigin: HorizontalOrigin.CENTER,
            verticalOrigin: VerticalOrigin.CENTER,
            pixelOffset: new Cartesian2(0, 0),
            scaleByDistance: hubScaleByDistance,
            show: isVisible,
            // WARNING: Do NOT use heightReference: HeightReference.CLAMP_TO_GROUND here.
            // It causes severe lag/performance drops with thousands of dynamic entities.
            disableDepthTestDistance: stack.hubItem.options.disableDepthTestDistance !== undefined 
                ? stack.hubItem.options.disableDepthTestDistance 
                : ((stack.hubItem.entity.altitude || 0) < 100 ? Number.POSITIVE_INFINITY : 0),
            // Tag with same ID as top entity! So clicking it triggers interaction/selection.
            id: { _wwvEntity: stack.hubItem.entity }
        });
        hubBillboards.set(stack.id, bb);
    } else {
        // Update position if moved
        if (!Cartesian3.equals(bb.position, stack.hubItem.posRef)) {
            bb.position = stack.hubItem.posRef;
        }
        if (bb.image !== expectedImage) bb.image = expectedImage;
        if (!Color.equals(bb.color, targetColor)) bb.color = targetColor;
        // Always ensure it's shown, it persists even when expanded!
        if (bb.show !== isVisible) bb.show = isVisible;
    }
}

/** Ease-out cubic for smooth deceleration. */
function easeOut(t: number): number {
    return 1 - (1 - t)**3;
}

