/* eslint-disable react-hooks/immutability */
import { useEffect, useRef, useState } from "react";
import {
    Viewer as CesiumViewer,
    ImageryLayer,
    SceneMode,
    Cesium3DTileset,
    Cesium3DTileStyle,
    createOsmBuildingsAsync,
    createGooglePhotorealistic3DTileset
} from "cesium";
import { useStore } from "@/core/state/store";
import { createImageryProvider, createOsmProvider } from "./ImageryProviderFactory";
import { loadConfig } from "../../lib/config";

export function useImageryManager(viewerInstance: CesiumViewer | null, viewerReady: boolean) {
    const viewer = viewerInstance;
    const baseLayerId = useStore((s) => s.mapConfig.baseLayerId);
    const fallbackLayerId = useStore((s) => s.mapConfig.fallbackLayerId);
    const sceneMode = useStore((s) => s.mapConfig.sceneMode);
    const showOsmBuildings = useStore((s) => s.mapConfig.showOsmBuildings);

    const selectedLayerId = baseLayerId || 'osm';
    const currentImageryLayerRef = useRef<ImageryLayer | null>(null);
    const initialCleanupDoneRef = useRef(false);
    const osmBuildingsRef = useRef<Cesium3DTileset | null>(null);
    const googleTilesetRef = useRef<Cesium3DTileset | null>(null);
    const [google3DActive, setGoogle3DActive] = useState(false);

    // 1. Manage Scene Mode (2D / 3D / Columbus)
    useEffect(() => {
        if (!viewer || !viewerReady || viewer.isDestroyed()) return;

        let targetMode = SceneMode.SCENE3D;
        if (sceneMode === 1) targetMode = SceneMode.COLUMBUS_VIEW;
        if (sceneMode === 2) targetMode = SceneMode.SCENE2D;

        if (viewer.scene.mode !== targetMode) {
            if (targetMode === SceneMode.SCENE2D) viewer.scene.morphTo2D(1.0);
            else if (targetMode === SceneMode.SCENE3D) viewer.scene.morphTo3D(1.0);
            else if (targetMode === SceneMode.COLUMBUS_VIEW) viewer.scene.morphToColumbusView(1.0);
        }
    }, [viewer, viewerReady, sceneMode]);

    // 2. Manage Imagery Layer and Google 3D Tiles
    useEffect(() => {
        if (!viewer || !viewerReady || viewer.isDestroyed()) return;

        let active = true;

        async function updateImagery() {
            if (!viewer || !viewerReady || viewer.isDestroyed() || !active) return;

            if (!initialCleanupDoneRef.current) {
                viewer.imageryLayers.removeAll();
                initialCleanupDoneRef.current = true;
            }

            // Handle Google 3D Tiles specifically
            const isGoogle3D = selectedLayerId === "google-3d";

            // Toggle Google 3D Tileset visibility if it exists
            // Or find it in primitives
            const {primitives} = viewer.scene;
            let foundTileset: Cesium3DTileset | null = null;

            for (let i = 0; i < primitives.length; i++) {
                const p = primitives.get(i);
                // Find the Google tileset ΓÇö skip any tagged as OSM buildings
                if (p instanceof Cesium3DTileset && !(p as any)._wwvOsmBuildings) {
                    foundTileset = p;
                    break;
                }
            }

            // Self-healing: if Google 3D Tiles is selected but no tileset exists yet,
            // try to dynamically create it if we have an API key.
            if (isGoogle3D && !foundTileset) {
                const config = await loadConfig();
                const apiKey = config.GOOGLE_MAPS_API_KEY || (import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string | undefined);
                if (apiKey && active && !viewer.isDestroyed()) {
                    try {
                        console.log("[useImageryManager] Dynamically initializing Google 3D Tileset...");
                        const tileset = await createGooglePhotorealistic3DTileset({ key: apiKey });
                        if (active && !viewer.isDestroyed()) {
                            viewer.scene.primitives.add(tileset);
                            foundTileset = tileset;
                        } else {
                            if (typeof tileset.destroy === 'function') {
                                tileset.destroy();
                            }
                        }
                    } catch (err) {
                        console.warn("[useImageryManager] Failed to create Google 3D Tileset dynamically:", err);
                    }
                }
            }

            const hasGoogle3D = isGoogle3D && !!foundTileset;
            if (foundTileset) {
                foundTileset.show = hasGoogle3D;
            }

            // Update state so buildings and components know whether 3D mode is active
            if (active) {
                setGoogle3DActive(hasGoogle3D);
            }

            // Hide/Show standard globe surface to prevent z-fighting with Google 3D
            viewer.scene.globe.show = !hasGoogle3D;

            // Manage standard imagery layer
            if (hasGoogle3D) {
                // Remove standard imagery if showing Google 3D tiles
                if (currentImageryLayerRef.current) {
                    viewer.imageryLayers.remove(currentImageryLayerRef.current);
                    currentImageryLayerRef.current = null;
                }
            } else {
                // Load the selected imagery layer, then optionally fall back.
                const initialLayerId = isGoogle3D ? "arcgis-world" : selectedLayerId;
                let provider;

                try {
                    provider = await createImageryProvider(initialLayerId);
                } catch (primaryErr) {
                    console.warn(`[useImageryManager] Failed to load imagery layer ${initialLayerId}, trying fallback if available`, primaryErr);

                    if (fallbackLayerId && fallbackLayerId !== initialLayerId) {
                        try {
                            provider = await createImageryProvider(fallbackLayerId);
                            console.warn(`[useImageryManager] Falling back to imagery layer ${fallbackLayerId}`);
                        } catch (fallbackErr) {
                            console.warn(`[useImageryManager] Fallback imagery ${fallbackLayerId} also failed`, fallbackErr);
                        }
                    }

                    if (!provider) {
                        provider = createOsmProvider();
                        console.warn('[useImageryManager] Using OSM fallback imagery');
                    }
                }

                if (!provider) {
                    return;
                }

                const newLayer = new ImageryLayer(provider);

                if (currentImageryLayerRef.current) {
                    viewer.imageryLayers.remove(currentImageryLayerRef.current);
                }

                if (viewer.isDestroyed() || !active) return;
                viewer.imageryLayers.add(newLayer, 0);
                currentImageryLayerRef.current = newLayer;
            }
        }

        updateImagery();

        return () => {
            active = false;
            if (viewer && !viewer.isDestroyed()) {
                if (currentImageryLayerRef.current) {
                    viewer.imageryLayers.remove(currentImageryLayerRef.current);
                    currentImageryLayerRef.current = null;
                }
                if (googleTilesetRef.current && viewer.scene.primitives.contains(googleTilesetRef.current)) {
                    viewer.scene.primitives.remove(googleTilesetRef.current);
                    googleTilesetRef.current = null;
                }
            }
        };
    }, [viewer, viewerReady, baseLayerId, fallbackLayerId]);

    // 3. Manage OSM 3D Buildings (only in 3D mode, not with Google Photorealistic tiles)
    const is3DMode = sceneMode === 3;
    useEffect(() => {
        if (!viewer || !viewerReady || viewer.isDestroyed()) return;

        const shouldShow = showOsmBuildings && !google3DActive && is3DMode;

        if (shouldShow && !osmBuildingsRef.current) {
            let cancelled = false;
            createOsmBuildingsAsync().then((tileset) => {
                if (cancelled || !viewer || viewer.isDestroyed()) {
                    tileset.destroy();
                    return;
                }
                (tileset as any)._wwvOsmBuildings = true;
                tileset.maximumScreenSpaceError = 16;
                tileset.style = new Cesium3DTileStyle({
                    color: "color('#E0DDD5')",
                });
                viewer.scene.primitives.add(tileset);
                osmBuildingsRef.current = tileset;
            }).catch((err) => {
                console.warn("[useImageryManager] Failed to load OSM 3D Buildings:", err);
            });
            return () => { cancelled = true; };
        }

        if (!shouldShow && osmBuildingsRef.current) {
            if (!viewer.isDestroyed()) {
                viewer.scene.primitives.remove(osmBuildingsRef.current);
            }
            osmBuildingsRef.current = null;
        }
    }, [viewer, viewerReady, google3DActive, is3DMode, showOsmBuildings]);

    return {
        isGoogle3D: google3DActive
    };
}

/* eslint-disable no-console */
/**
 * @file hostGlobals.ts
 * @description Exposes essential host libraries (React, Cesium, SDK, etc.) on `globalThis`.
 * This allows dynamically loaded ES module plugins to share the host's dependencies
 * rather than bundling their own copies, preventing version conflicts and reducing bundle size.
 */

import React from "react";
import * as ReactDOM from "react-dom";
import * as jsxRuntime from "react/jsx-runtime";
import * as WWVPluginSDK from "../../wwv-sdk/index";
import * as Cesium from "cesium";

import * as zustand from "zustand";
import { useStore } from "@/core/state/store";
import { pluginManager } from "./PluginManager";

export interface WWVHostGlobals {
    React: typeof React;
    ReactDOM: typeof ReactDOM;
    jsxRuntime: typeof jsxRuntime;
    WWVPluginSDK: typeof WWVPluginSDK;
    Cesium: typeof Cesium;
    zustand: typeof zustand;
    useStore: typeof useStore;
    pluginManager: typeof pluginManager;
}

declare global {

    var __WWV_HOST__: WWVHostGlobals | undefined;
}

/**
 * Injects the required libraries and configuration onto the global scope.
 *
 * This must be called exactly once during the application's initial boot sequence,
 * before any dynamic plugins are imported.
 *
 * @returns A promise that resolves when all globals have been injected.
 */
export async function injectHostGlobals(): Promise<void> {
    if (globalThis.__WWV_HOST__) return;

    const Cesium = await import("cesium");

    globalThis.__WWV_HOST__ = {
        React,
        ReactDOM,
        jsxRuntime,
        WWVPluginSDK,
        Cesium,
        zustand,
        useStore,
        pluginManager,
    };

    // REST Engine URL (Fallback)
    // Note: Local Docker-based engine interception (localhost:5000) happens dynamically inside
    // resolveEngineUrl.ts during plugin routing. These variables act as global fallbacks.
    const envDataEngine = import.meta.env.NEXT_PUBLIC_WWV_PLUGIN_DATA_ENGINE_URL;
    if (envDataEngine) {
        (globalThis as Record<string, unknown>).__WWV_ENGINE_URL__ = envDataEngine;
    } else {
        // ALWAYS default to the cloud engine unless explicitly told otherwise via env var
        (globalThis as Record<string, unknown>).__WWV_ENGINE_URL__ = 'https://dataengine.worldwideview.dev';
    }

    // WebSocket Engine URL
    const fallbackWs = envDataEngine ? `${envDataEngine.replace(/^http/, "ws")}/stream` : 'wss://dataengine.worldwideview.dev/stream';
    (globalThis as Record<string, unknown>).__WWV_WS_ENGINE_URL__ = fallbackWs;

    console.log("[HostGlobals] React and SDK injected for dynamic plugins");
}

/**
 * @file DeclarativePlugin.ts
 * @description Generic WorldPlugin implementation for declarative (JSON-only) plugins.
 * Note: This runtime is legacy and primarily used as a fallback for simple data layers.
 */

import type {
    WorldPlugin,
    GeoEntity,
    TimeRange,
    PluginContext,
    LayerConfig,
    CesiumEntityOptions,
    PluginCategory,
} from "../PluginTypes";
import type { PluginManifest } from "../PluginManifest";
import { mapGeoJsonToEntities } from "./mapGeoJsonToEntities";
import { mapJsonToEntities } from "./mapJsonToEntities";

/**
 * A generic plugin implementation that derives its logic from a JSON manifest.
 */
export class DeclarativePlugin implements WorldPlugin {
    readonly id: string;
    readonly name: string;
    readonly description: string;
    readonly icon: string;
    readonly category: PluginCategory;
    readonly version: string;

    private context: PluginContext | null = null;

    constructor(private readonly manifest: PluginManifest) {
        this.id = manifest.id;
        this.name = manifest.name;
        this.description = manifest.description ?? "";
        this.icon = manifest.icon ?? "≡ƒôª";
        this.category = manifest.category as PluginCategory;
        this.version = manifest.version;
    }

    /**
     * Initializes the plugin with the provided context.
     *
     * @param ctx - The host context provided by the manager.
     * @returns A promise that resolves when initialization is complete.
     */
    async initialize(ctx: PluginContext): Promise<void> {
        this.context = ctx;
    }

    /**
     * Cleans up internal state and stops all active processes.
     */
    destroy(): void {
        this.context = null;
    }

    /**
     * Fetches fresh data from the remote data source defined in the manifest.
     *
     * @param _timeRange - The current globe time range (unused in this implementation).
     * @returns A promise resolving to an array of GeoEntities.
     */
    async fetch(_timeRange: TimeRange): Promise<GeoEntity[]> {
        const ds = this.manifest.dataSource;
        if (!ds) return [];

        try {
            const url = this.buildUrl(ds.url);
            const headers = this.buildHeaders();

            const res = await fetch(url, {
                method: ds.method ?? "GET",
                headers,
                ...(ds.body ? { body: JSON.stringify(ds.body) } : {}),
            });
            if (!res.ok) throw new Error(`HTTP ${res.status}`);

            const data = await res.json();
            return this.parseResponse(data);
        } catch (err) {
            console.error(`[DeclarativePlugin:${this.id}] Fetch error:`, err);
            return [];
        }
    }

    /**
     * Retrieves the polling interval from the manifest configuration.
     *
     * @returns The poll interval in milliseconds (defaults to 30s).
     */
    getPollingInterval(): number {
        return this.manifest.dataSource?.pollInterval ?? 30_000;
    }

    /**
     * Returns the visual configuration for the map layer.
     *
     * @returns The LayerConfig object.
     */
    getLayerConfig(): LayerConfig {
        const r = this.manifest.rendering;
        return {
            color: r?.color ?? "#3b82f6",
            clusterEnabled: r?.clusterEnabled ?? true,
            clusterDistance: r?.clusterDistance ?? 40,
            maxEntities: r?.maxEntities,
        };
    }

    /**
     * Determines how a single GeoEntity should be represented on the Cesium globe.
     *
     * @param entity - The entity to render.
     * @returns The Cesium-specific rendering options.
     */
    renderEntity(entity: GeoEntity): CesiumEntityOptions {
        const r = this.manifest.rendering;
        const type = r?.entityType === "billboard" ? "billboard" : "point";
        return {
            type,
            color: r?.color ?? "#3b82f6",
            size: r?.maxEntities ? undefined : 6,
            iconUrl: r?.icon,
            labelText: entity.label ?? undefined,
        };
    }

    // ΓöÇΓöÇ Private helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    private buildUrl(base: string): string {
        const auth = this.manifest.dataSource?.auth;
        if (auth?.type !== "query") return base;

        const value = this.resolveEnvVar(auth.envVar);
        if (!value) return base;

        const sep = base.includes("?") ? "&" : "?";
        return `${base}${sep}${auth.key}=${encodeURIComponent(value)}`;
    }

    private buildHeaders(): Record<string, string> {
        const headers: Record<string, string> = {
            ...(this.manifest.dataSource?.headers ?? {}),
        };
        const auth = this.manifest.dataSource?.auth;
        if (auth?.type === "header") {
            const value = this.resolveEnvVar(auth.envVar);
            if (value) headers[auth.key] = value;
        }
        return headers;
    }

    private resolveEnvVar(name: string): string | undefined {
        if (typeof import.meta.env !== "undefined") {
            return import.meta.env[name] ?? undefined;
        }
        return undefined;
    }

    private parseResponse(data: unknown): GeoEntity[] {
        const format = this.manifest.dataSource?.format ?? "json";
        const mapping = this.manifest.fieldMapping;
        if (!mapping) return [];

        if (format === "geojson") {
            return mapGeoJsonToEntities(data, mapping, this.id);
        }
        return mapJsonToEntities(data, mapping, this.id, this.manifest.dataSource?.arrayPath);
    }
}

