/**
 * Imagery Provider Factory ΓÇö Inspired by WorldWideView's ImageryProviderFactory.
 * Provides a clean, cascading fallback chain for map tile sources.
 * Supports Google Photorealistic 3D Tiles ΓåÆ OSM fallback.
 */
import * as Cesium from 'cesium';
import { loadConfig } from './config';
import { useDiagnosticsStore } from '@/store/diagnosticsStore';

/** Attempt to load Google Photorealistic 3D Tiles (requires API key). */
async function setupGooglePhotorealistic3D(viewer: Cesium.Viewer, apiKey: string): Promise<boolean> {
  try {
    // Guard: viewer may be destroyed by the time async tileset loads
    if (!viewer || (typeof (viewer as any).isDestroyed === 'function' && (viewer as any).isDestroyed())) {
      useDiagnosticsStore.getState().add({
        level: 'warning',
        message: 'Viewer destroyed before Google Photorealistic 3D Tiles could be added',
        stack: null,
        metadata: { apiKeyProvided: !!apiKey },
        suggestion: 'Skip adding tileset when viewer is destroyed; ensure imagery setup aborts on unmount',
      });
      return false;
    }
    const tileset = await Cesium.createGooglePhotorealistic3DTileset({ key: apiKey });
    if (viewer.scene && viewer.scene.primitives) {
      viewer.scene.primitives.add(tileset);
    } else {
      useDiagnosticsStore.getState().add({
        level: 'warning',
        message: 'Viewer scene not available when adding Google 3D tileset',
        stack: null,
        metadata: {},
        suggestion: 'Verify viewer.scene exists before adding scene primitives',
      });
      return false;
    }
    return true;
  } catch (err) {
    console.warn('[imageryFactory] Google 3D Tiles failed:', err);
    useDiagnosticsStore.getState().add({
      level: 'warning',
      message: 'Google Photorealistic 3D Tiles failed to load',
      stack: err instanceof Error ? err.stack || String(err) : String(err),
      metadata: {},
      suggestion: 'Check API key and network access, falling back to ArcGIS or OSM imagery',
    });
    return false;
  }
}

/** Load high-resolution ArcGIS satellite imagery as a reliable fallback (like Google Earth). */
async function setupArcGisSatellite(viewer: Cesium.Viewer): Promise<void> {
  try {
    if (!viewer || (typeof (viewer as any).isDestroyed === 'function' && (viewer as any).isDestroyed())) {
      useDiagnosticsStore.getState().add({
        level: 'warning',
        message: 'Viewer destroyed before ArcGIS imagery provider could be added',
        stack: null,
        metadata: {},
        suggestion: 'Abort imagery setup when viewer is destroyed',
      });
      return;
    }

    const esriProvider = await Cesium.ArcGisMapServerImageryProvider.fromUrl(
      'https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer'
    );
    if (viewer.imageryLayers && typeof viewer.imageryLayers.addImageryProvider === 'function') {
      viewer.imageryLayers.addImageryProvider(esriProvider);
    } else {
      useDiagnosticsStore.getState().add({
        level: 'warning',
        message: 'Viewer.imageryLayers unavailable; cannot add ArcGIS imagery',
        stack: null,
        metadata: {},
        suggestion: 'Ensure viewer is not destroyed and imageryLayers API is present',
      });
    }
  } catch (err) {
    console.warn('[imageryFactory] ArcGIS fallback failed:', err);
    useDiagnosticsStore.getState().add({
      level: 'warning',
      message: 'ArcGIS imagery provider failed',
      stack: err instanceof Error ? err.stack || String(err) : String(err),
      metadata: {},
      suggestion: 'Network issue or ArcGIS service rate limit; falling back to OSM',
    });
  }
}

/**
 * Main entry point: Attempts Google 3D Tiles first, falls back to OSM.
 * Resolves when imagery is ready. Never throws ΓÇö always falls back gracefully.
 */
export async function setupImagery(viewer: Cesium.Viewer): Promise<void> {
  const config = await loadConfig();
  const apiKey = config.GOOGLE_MAPS_API_KEY || (import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string | undefined);

  if (!viewer || (typeof (viewer as any).isDestroyed === 'function' && (viewer as any).isDestroyed())) {
    useDiagnosticsStore.getState().add({
      level: 'debug',
      message: 'Aborting imagery setup because viewer is not available or already destroyed',
      stack: null,
      metadata: {},
      suggestion: 'Imagery setup was invoked after cleanup; guard calls in hooks',
    });
    return;
  }

  if (apiKey) {
    const ok = await setupGooglePhotorealistic3D(viewer, apiKey);
    if (ok) return;
  }

  // Fallback: High-res satellite imagery
  await setupArcGisSatellite(viewer);
}

import { OrbitEngine, OrbitParams } from '../core/satellites/OrbitEngine';

/**
 * Simulation Library
 * Backward-compatible proxy module for orbital mechanics.
 * Delegated to the new OOP-based OrbitEngine instance.
 */

const engine = OrbitEngine.getInstance();

export const EARTH_RADIUS_M = OrbitEngine.EARTH_RADIUS_M;
export const EARTH_GRAVITY_MU = OrbitEngine.EARTH_GRAVITY_MU;
export const EARTH_ROTATION_SPEED_RAD_S = OrbitEngine.EARTH_ROTATION_SPEED_RAD_S;
export const J2_PERTURBATION = OrbitEngine.J2_PERTURBATION;

export const ISS_INCLINATION_RAD = OrbitEngine.ISS_INCLINATION_RAD;
export const ISS_ALTITUDE_M = OrbitEngine.ISS_ALTITUDE_M;

export function calculateOrbitalSpeed(altitudeMeters: number): number {
  return engine.calculateOrbitalSpeed(altitudeMeters);
}

export function calculateOrbitalPeriod(altitudeMeters: number): number {
  return engine.calculateOrbitalPeriod(altitudeMeters);
}

export function propagateCircularOrbit(
  elapsedSeconds: number,
  altitudeMeters: number = ISS_ALTITUDE_M,
  inclinationRad: number = ISS_INCLINATION_RAD,
  omega0: number = 0.0,
  argLat0: number = 0.0
): { lat: number; lng: number } {
  return engine.propagateCircularOrbit(elapsedSeconds, {
    altitudeMeters,
    inclinationRad,
    omega0,
    argLat0
  });
}

export function propagateCircularOrbitInto(
  out: Float32Array | number[],
  offset: number,
  elapsedSeconds: number,
  altitudeMeters: number = ISS_ALTITUDE_M,
  inclinationRad: number = ISS_INCLINATION_RAD,
  omega0: number = 0.0,
  argLat0: number = 0.0
): void {
  engine.propagateCircularOrbitInto(out, offset, elapsedSeconds, {
    altitudeMeters,
    inclinationRad,
    omega0,
    argLat0
  });
}

export function propagateSatelliteTle(
  tleLines: string[],
  date: Date = new Date()
): { lat: number; lng: number; altitude: number } | null {
  const result = engine.propagateSatelliteTle(tleLines, date);
  if (!result) return null;
  return { lat: result.lat, lng: result.lng, altitude: result.altitude ?? 0 };
}

export function propagateSatelliteTleInto(
  out: Float32Array | number[],
  offset: number,
  tleLines: string[],
  date: Date = new Date()
): boolean {
  return engine.propagateSatelliteTleInto(out, offset, tleLines, date);
}

// Support for async batch processing
export async function propagateBatchAsync(
  satellites: Array<{ id: string; tleLines: string[] }>,
  date: Date = new Date()
) {
  return engine.propagateBatchAsync(satellites, date);
}

import {StrictMode} from 'react';
import {createRoot} from 'react-dom/client';
import App from './App.tsx';
import { WWVInitializer } from './core/WWVInitializer.tsx';
import './index.css';
import { useUIStore } from './store/uiStore';
import { useDiagnosticsStore } from './store/diagnosticsStore';

// Expose store on window for E2E/Puppeteer testing (only in dev or fallback mode)
if (typeof window !== 'undefined') {
  (window as any).useUIStore = useUIStore;
  (window as any).useDiagnosticsStore = useDiagnosticsStore;
  // Global runtime error hooks: capture unhandled exceptions and rejections for diagnostics
  window.addEventListener('error', (ev) => {
    try {
      useDiagnosticsStore.getState().add({
        level: 'error',
        message: ev.error?.message || ev.message || 'Global error',
        stack: ev.error?.stack || null,
        metadata: { filename: (ev as ErrorEvent).filename, lineno: (ev as ErrorEvent).lineno, colno: (ev as ErrorEvent).colno },
        suggestion: 'Check stacktrace and recent UI interactions leading to the error',
      });
    } catch (e) { /* ignore */ }
  });

  window.addEventListener('unhandledrejection', (ev) => {
    try {
      const reason = (ev as PromiseRejectionEvent).reason;
      useDiagnosticsStore.getState().add({
        level: 'error',
        message: reason?.message || String(reason) || 'Unhandled promise rejection',
        stack: reason?.stack || null,
        metadata: { reason },
        suggestion: 'Inspect promise chain; add catch handlers for expected failures',
      });
    } catch (e) { /* ignore */ }
  });
}

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <WWVInitializer>
      <App />
    </WWVInitializer>
  </StrictMode>,
);

import { Flame } from "lucide-react";
import type {
    WorldPlugin,
    GeoEntity,
    TimeRange,
    PluginContext,
    LayerConfig,
    CesiumEntityOptions,
} from "@/core/plugins/PluginTypes";

export class EarthquakesPlugin implements WorldPlugin {
    readonly id = "earthquakes";
    readonly name = "Global Earthquakes";
    readonly description = "Real-time global seismic activity monitoring from USGS";
    readonly icon = Flame;
    readonly category = "natural-disaster" as const;
    readonly version = "1.0.0";

    private context: PluginContext | null = null;

    async initialize(ctx: PluginContext): Promise<void> {
        this.context = ctx;
    }

    destroy(): void {
        this.context = null;
    }

    async fetch(_timeRange: TimeRange): Promise<GeoEntity[]> {
        const fetchWithRetry = async (retries = 3, backoff = 1000): Promise<any> => {
            try {
                const res = await fetch("https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson");
                if (!res.ok) throw new Error(`HTTP ${res.status}`);
                return await res.json();
            } catch (err) {
                if (retries > 0) {
                    await new Promise(resolve => setTimeout(resolve, backoff));
                    return fetchWithRetry(retries - 1, backoff * 2);
                }
                throw err;
            }
        };

        try {
            const data = await fetchWithRetry();
            const features = Array.isArray(data?.features) ? data.features : [];
            return features.map((feat: any) => {
                const coords = feat.geometry.coordinates;
                const props = feat.properties;

                return {
                    id: feat.id || String(props.time),
                    pluginId: this.id,
                    latitude: coords[1],
                    longitude: coords[0],
                    altitude: coords[2] ? coords[2] * 1000 : undefined, // depth in meters
                    timestamp: new Date(props.time),
                    label: `Mag ${props.mag} - ${props.place}`,
                    properties: {
                        mag: props.mag,
                        place: props.place,
                        time: props.time,
                        url: props.url,
                        tsunami: props.tsunami,
                        sig: props.sig,
                        rawEntity: feat
                    },
                };
            });
        } catch (err) {
            console.error("[EarthquakesPlugin] fetch error:", err);
            if (this.context) {
                this.context.onError(err instanceof Error ? err : new Error(String(err)));
            }
            return [];
        }
    }

    getPollingInterval(): number {
        return 120000; // Poll every 2 minutes
    }

    getLayerConfig(): LayerConfig {
        return {
            color: "#ff8800",
            clusterEnabled: true,
            clusterDistance: 40,
        };
    }

    renderEntity(entity: GeoEntity): CesiumEntityOptions {
        const mag = (entity.properties.mag as number) || 1.0;
        const size = Math.max(6, Math.min(24, mag * 3));
        
        let color = "#34a853"; // minor (<2.5) Green
        if (mag >= 4.5) color = "#ea4335"; // strong (>=4.5) Red
        else if (mag >= 2.5) color = "#fbbc05"; // moderate (>=2.5) Yellow

        return {
            type: "hexagon",
            color,
            size,
            outlineColor: "#ffffff",
            outlineWidth: 1.5,
            labelText: mag >= 4.0 ? `M${mag}` : undefined,
            labelFont: "9px monospace",
        };
    }
}

/**
 * Factory that creates a WorldPlugin instance for each imported GeoJSON layer.
 * Each import becomes its own independent plugin entry in the Data Layers list.
 */

import { FileJson } from "lucide-react";
import type {
    WorldPlugin,
    GeoEntity,
    TimeRange,
    PluginContext,
    LayerConfig,
    CesiumEntityOptions,
} from "@/core/plugins/PluginTypes";
import type { GeoJsonFeatureCollection } from "@/types/geojson";
import { featuresToEntities } from "./entityConverter";

/** Color palette for imported layers. */
const LAYER_COLORS = [
    "#00e5ff", "#ff6d00", "#76ff03", "#d500f9",
    "#ffea00", "#ff1744", "#00bfa5", "#651fff",
];

export function pickLayerColor(index: number): string {
    return LAYER_COLORS[index % LAYER_COLORS.length];
}

export interface ImportedPluginConfig {
    id: string;
    name: string;
    description: string;
    color: string;
    featureCollection: GeoJsonFeatureCollection;
}

/**
 * Creates a WorldPlugin instance for a single imported GeoJSON dataset.
 * The plugin ID is prefixed with "geojson-" to avoid collisions.
 */
export function createGeoJsonPlugin(config: ImportedPluginConfig): WorldPlugin {
    const entities = featuresToEntities(
        config.featureCollection.features,
        config.id,
    );

    return {
        id: config.id,
        name: config.name,
        description: config.description,
        icon: FileJson,
        category: "custom" as const,
        version: "1.0.0",

        async initialize(): Promise<void> { },
        destroy(): void { },

        async fetch(): Promise<GeoEntity[]> {
            return entities;
        },

        getPollingInterval(): number {
            return 9999999;
        },

        getLayerConfig(): LayerConfig {
            return {
                color: config.color,
                clusterEnabled: true,
                clusterDistance: 40,
            };
        },

        renderEntity(): CesiumEntityOptions {
            return {
                type: "point",
                color: config.color,
                size: 8,
                outlineColor: "#ffffff",
                outlineWidth: 1,
            };
        },
    };
}

"use client";

import { X } from "lucide-react";
import { useGeoJsonImport } from "./useGeoJsonImport";
import { MethodTabs } from "./components/MethodTabs";
import { FileDropZone } from "./components/FileDropZone";
import { TextInputArea } from "./components/TextInputArea";
import { PreviewInfo } from "./components/PreviewInfo";
import { MetadataForm } from "./components/MetadataForm";

interface ImportModalProps {
    onClose: () => void;
}

export function ImportModal({ onClose }: ImportModalProps) {
    const {
        method, setMethod,
        textInput, setTextInput,
        name, setName,
        description, setDescription,
        color, setColor,
        preview, setPreview,
        error, setError,
        dragging, setDragging,
        fileRef,
        processInput, handleFile, handleDrop, handleConfirm
    } = useGeoJsonImport(onClose);

    return (
      <div className="geojson-modal-overlay" onClick={onClose}>
        <div
          className="geojson-modal glass-panel"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="geojson-modal__header">
            <h3>Import GeoJSON</h3>
            <button
              type="button"
              className="geojson-modal__close"
              onClick={onClose}
              aria-label="Close"
            >
              <X size={18} />
            </button>
          </div>

          <MethodTabs
            method={method}
            onChange={(m) => {
                    setMethod(m);
                    setPreview(null);
                    setError(null);
                }}
          />

          <div className="geojson-modal__body">
            {method === "file" && (
            <FileDropZone
              dragging={dragging}
              fileRef={fileRef}
              onDrop={handleDrop}
              onDragOver={() => setDragging(true)}
              onDragLeave={() => setDragging(false)}
              onFileSelect={handleFile}
            />
                    )}

            {(method === "paste" || method === "custom") && (
              <TextInputArea
                method={method}
                value={textInput}
                onChange={setTextInput}
                onParse={() => processInput(textInput)}
              />
                    )}

            {error && <div className="geojson-error">{error}</div>}

            {preview && (
              <PreviewInfo preview={preview} />
                    )}

            {preview && (
              <MetadataForm
                name={name}
                description={description}
                color={color}
                onNameChange={setName}
                onDescriptionChange={setDescription}
                onColorChange={setColor}
              />
                    )}
          </div>

          <div className="geojson-modal__footer">
            <button type="button" className="geojson-btn geojson-btn--secondary" onClick={onClose}>
              Cancel
            </button>
            <button
              type="button"
              className="geojson-btn geojson-btn--primary"
              disabled={!preview}
              onClick={handleConfirm}
            >
              Import Layer
            </button>
          </div>
        </div>
      </div>
    );
}

import { Hexagon } from "lucide-react";
import type {
    WorldPlugin,
    GeoEntity,
    TimeRange,
    PluginContext,
    LayerConfig,
    CesiumEntityOptions,
} from "@/core/plugins/PluginTypes";
import { pluginManager } from "@/core/plugins/PluginManager";
import { generateHexagonDensityFeed } from "@/core/hexagons/hexagonFeeds";

export class EntityDensityPlugin implements WorldPlugin {
    readonly id = "entity-density";
    readonly name = "Global Density Map";
    readonly description = "Aggregates all entities into a 3D hexagon density layer";
    readonly icon = Hexagon;
    readonly category = "infrastructure" as const;
    readonly version = "1.0.0";

    private context: PluginContext | null = null;

    async initialize(ctx: PluginContext): Promise<void> {
        this.context = ctx;
    }

    destroy(): void {
        this.context = null;
    }

    async fetch(_timeRange: TimeRange): Promise<GeoEntity[]> {
        // Collect entities from all other active plugins except this one
        const allEntities = pluginManager.getAllEntities().filter(e => e.pluginId !== this.id);

        // Generate hexagon density feed
        const hexFeed = generateHexagonDensityFeed(allEntities, 10); // 10 degree cell size

        return hexFeed.map(h => ({
            ...h.entity,
            pluginId: this.id, // Ensure we tag it as from this plugin
            properties: {
                ...h.entity.properties,
                cesiumOptions: h.options // Store the generated options
            }
        }));
    }

    getPollingInterval(): number {
        return 5000; // Update hexagons every 5 seconds
    }

    getLayerConfig(): LayerConfig {
        return {
            color: "#FFFFFF",
            clusterEnabled: false,
            clusterDistance: 0,
        };
    }

    renderEntity(entity: GeoEntity): CesiumEntityOptions {
        // Return the options generated by hexagonFeeds
        return (entity.properties.cesiumOptions as CesiumEntityOptions) || {
            type: "hexagon",
            color: "#ea4335",
            size: 10,
        };
    }
}

