/**
 * @interface GeoEntity
 * @description The primary data primitive representing a geospatial object.
 */
export interface GeoEntity {
    /** Globally unique identifier for this specific entity instance. */
    id: string;
    /** The ID of the plugin that owns this entity. */
    pluginId: string;
    /** WGS84 Latitude. */
    latitude: number;
    /** WGS84 Longitude. */
    longitude: number;
