/**
 * @file viteGlobals.ts
 * @description Build-time utility for externalizing shared dependencies.
 * Provides a Vite plugin that maps core libraries (React, Cesium, Zustand) 
 * to the host application's global context, ensuring singleton stability 
 * for dynamic plugin bundles.
 * @module @worldwideview/wwv-plugin-sdk
 */

interface GlobalsMap {
    [moduleId: string]: string;
}

/**
 * @function wwvPluginGlobals
 * @description Creates a Vite/Rollup plugin that resolves shared dependencies to 
 * the `globalThis.__WWV_HOST__` object.
 * 
 * This ensures that dynamically loaded plugins inherit the exact library 
 * instances of the host application, preventing version mismatches and 
 * context errors.
 * 
 * @returns {any} A Vite plugin object.
 */
export function wwvPluginGlobals(): any {
    const HOST_MAPPINGS: GlobalsMap = {
        "react": "React",
        "react-dom": "ReactDOM",
        "react/jsx-runtime": "jsxRuntime",
        "cesium": "Cesium",
        "resium": "Resium",
        // zustand is also part of WWVHostGlobals or maybe not? Wait. I should check hostGlobals.ts!
        "@worldwideview/wwv-plugin-sdk": "WWVPluginSDK",
        "@/core/state/store": "useStore",
        "@/core/plugins/PluginManager": "pluginManager",
        "@/components/video/CameraStream": "CameraStream"
    };

    return {
        name: "wwv-plugin-globals",
        enforce: "pre",
        resolveId(id: string) {
            if (id in HOST_MAPPINGS || id === "zustand") {
                // Ensure Rollup doesn't try to look for these modules in node_modules
                return "\0" + id;
            }
            return null;
        },
        load(id: string) {
            if (!id.startsWith("\0")) return null;
            const originalId = id.slice(1);
            
            if (originalId === "react") {
                return `
                    const React = globalThis.__WWV_HOST__.React;
                    export default React;
                    export const { useState, useEffect, useRef, useMemo, useCallback, useContext, useReducer, useLayoutEffect, StrictMode, Suspense, createContext, createElement, cloneElement, isValidElement, Fragment, Children, Component, PureComponent, createRef, forwardRef, memo, lazy, startTransition, useTransition, useDeferredValue, useId, useSyncExternalStore, useInsertionEffect } = React;
                `;
            }
            if (originalId === "react-dom") {
                return `
                    const ReactDOM = globalThis.__WWV_HOST__.ReactDOM;
                    export default ReactDOM;
                    export const { createPortal, flushSync } = ReactDOM;
                `;
            }
            if (originalId === "react/jsx-runtime") {
                return `
                    const jsxRuntime = globalThis.__WWV_HOST__.jsxRuntime;
                    export const jsx = jsxRuntime.jsx;
                    export const jsxs = jsxRuntime.jsxs;
                    export const Fragment = jsxRuntime.Fragment;
                `;
            }
            if (originalId === "cesium") {
                return `
                    const Cesium = globalThis.__WWV_HOST__.Cesium;
                    export default Cesium;
                    // Export common bindings for direct destructuring
                    export const { Viewer, Entity, Cartesian3, Cartesian2, Color, CallbackProperty, DistanceDisplayCondition, NearFarScalar, HeightReference, Resource, Rectangle, PolygonHierarchy, ClassificationType, ArcType, Math, JulianDate, TimeInterval, TimeIntervalCollection, SampledPositionProperty, GeoJsonDataSource, PinBuilder, CustomDataSource, ConstantProperty, ColorMaterialProperty, Cartographic } = Cesium;
                `;
            }
            if (originalId === "resium") {
                return `
                    const Resium = globalThis.__WWV_HOST__.Resium;
                    export default Resium;
                    export const { Entity, PointGraphics, BillboardGraphics, CustomDataSource, Camera, PolygonGraphics, PolylineGraphics, EllipseGraphics, LabelGraphics, ModelGraphics, PathGraphics, BoxGraphics, GeoJsonDataSource, ScreenSpaceEventHandler, ScreenSpaceEvent } = Resium;
                `;
            }
            if (originalId === "@worldwideview/wwv-plugin-sdk") {
                return `
                    const SDK = globalThis.__WWV_HOST__.WWVPluginSDK;
                    export default SDK;
                    export const { WorldPlugin, PluginManifest, createSvgIconUrl, DEFAULT_ICON_SIZE } = SDK;
                `;
            }
            // If zustand is required, wait, is Zustand in host globals?
            if (originalId === "zustand") {
                return `
                    if (!globalThis.__WWV_HOST__.zustand) {
                        console.warn("zustand was not found on WWV_HOST");
                    }
                    const zustand = globalThis.__WWV_HOST__.zustand || {};
                    export default zustand;
                    export const { create, createStore, useStore } = zustand;
                `;
            }
            if (originalId === "@/core/state/store") {
                return `export const useStore = globalThis.__WWV_HOST__.useStore;`;
            }
            if (originalId === "@/core/plugins/PluginManager") {
                return `export const pluginManager = globalThis.__WWV_HOST__.pluginManager;`;
            }
            if (originalId === "@/components/video/CameraStream") {
                return `export const CameraStream = globalThis.__WWV_HOST__.CameraStream;`;
            }

            return null;
        }
    };
}

import fs from "fs";
import path from "path";



/**
 * Vite plugin that auto-generates a WorldPlugin class for static plugins.
 *
 * If the plugin's package.json has `worldwideview.format: "static"` and
 * no `src/index.ts` exists, this plugin injects a virtual module that:
 * - Fetches GeoJSON data from the CDN at runtime
 * - Converts features into GeoEntity objects
 * - Renders with the manifest's rendering config
 */
export function wwvStaticCompiler(): any {
    let pluginRoot = "";
    let manifest: any = null;
    let generatedEntry = "";

    return {
        name: "wwv-static-compiler",
        enforce: "pre" as const,

        config(userConfig: any) {
            pluginRoot = userConfig.root || process.cwd();
            const pkgPath = path.join(pluginRoot, "package.json");
            if (!fs.existsSync(pkgPath)) return;

            const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf-8"));
            manifest = pkg.worldwideview || null;
            if (!manifest) return;

            manifest._packageName = pkg.name;
            manifest._packageVersion = pkg.version;
            manifest._description = pkg.description || "";

            const srcIndex = path.join(pluginRoot, "src", "index.ts");
            if (fs.existsSync(srcIndex)) return; // real source exists

            // Write a generated entry file
            const srcDir = path.join(pluginRoot, "src");
            if (!fs.existsSync(srcDir)) fs.mkdirSync(srcDir, { recursive: true });

            generatedEntry = path.join(srcDir, "__generated_entry.js");
            const source = generateStaticPluginSource(manifest);
            fs.writeFileSync(generatedEntry, source, "utf-8");

            // Redirect lib entry to the generated file
            if (userConfig.build?.lib) {
                userConfig.build.lib.entry = generatedEntry;
            }
        },

        buildEnd() {
            // Clean up the generated file, but ONLY if we are not in watch mode
            const isWatchMode = process.argv.includes("--watch") || process.argv.includes("-w");
            if (!isWatchMode && generatedEntry && fs.existsSync(generatedEntry)) {
                fs.unlinkSync(generatedEntry);
                generatedEntry = "";
            }
        },

        closeBundle() {
            // Also clean up on close (redundant safety)
            const isWatchMode = process.argv.includes("--watch") || process.argv.includes("-w");
            if (!isWatchMode && generatedEntry && fs.existsSync(generatedEntry)) {
                fs.unlinkSync(generatedEntry);
                generatedEntry = "";
            }
        },
    };
}

function generateStaticPluginSource(manifest: any): string {
    const pluginId = manifest.id;
    const pluginName = manifest.name || pluginId;
    const description = manifest._description || "";
    const category = manifest.category || "custom";
    const icon = manifest.icon || "MapPin";
    const version = manifest._packageVersion || "1.0.0";
    const packageName = manifest._packageName;

    const color =
        manifest.rendering?.defaultColor ||
        manifest.rendering?.color ||
        "#3b82f6";
    const entityType = manifest.rendering?.entityType || "point";
    const clusterEnabled = manifest.rendering?.clusterEnabled ?? true;
    const clusterDistance = manifest.rendering?.clusterDistance ?? 50;
    const maxEntities = manifest.rendering?.maxEntities ?? 5000;
    const labelField = manifest.rendering?.labelField || "name";

    const dataFileName = manifest.dataFile
        ? path.basename(manifest.dataFile)
        : "data.json";

    const renderBlock =
        entityType === "billboard"
            ? `
        const cacheKey = "default";
        if (!this._iconUrls[cacheKey]) {
            this._iconUrls[cacheKey] = createSvgIconUrl(${icon}, { color: ${JSON.stringify(color)} });
        }
        return { type: "billboard", iconUrl: this._iconUrls[cacheKey], color: ${JSON.stringify(color)}, iconScale: 0.5 };`
            : `
        return { type: "point", color: ${JSON.stringify(color)}, size: 6 };`;

    return `
import { ${icon} } from "lucide-react";
import { createSvgIconUrl } from "@worldwideview/wwv-plugin-sdk";
import dataRaw from "../data/${dataFileName}?raw";

function representativePoint(geom) {
    if (!geom) return { lat: 0, lon: 0 };
    switch (geom.type) {
        case "Point":
            return { lat: geom.coordinates[1], lon: geom.coordinates[0], alt: geom.coordinates[2] };
        case "MultiPoint":
        case "LineString":
            return { lat: geom.coordinates[0][1], lon: geom.coordinates[0][0] };
        case "Polygon":
        case "MultiLineString":
            return { lat: geom.coordinates[0][0][1], lon: geom.coordinates[0][0][0] };
        case "MultiPolygon":
            return { lat: geom.coordinates[0][0][0][1], lon: geom.coordinates[0][0][0][0] };
        default:
            return { lat: 0, lon: 0 };
    }
}

export default class AutoStaticPlugin {
    id = ${JSON.stringify(pluginId)};
    name = ${JSON.stringify(pluginName)};
    description = ${JSON.stringify(description)};
    icon = ${icon};
    category = ${JSON.stringify(category)};
    version = ${JSON.stringify(version)};

    _context = null;
    _entities = [];
    _iconUrls = {};

    async initialize(ctx) {
        this._context = ctx;
        let data = null;
        try {
            data = JSON.parse(dataRaw);
        } catch(e) {
            console.error("Failed to parse data for ${pluginId}", e);
        }
        if (data && Array.isArray(data.features)) {
            this._entities = data.features.map((f, i) => {
                const pt = representativePoint(f.geometry);
                return {
                    id: "${pluginId}-" + (f.id ?? i),
                    pluginId: ${JSON.stringify(pluginId)},
                    latitude: pt.lat,
                    longitude: pt.lon,
                    altitude: pt.alt,
                    timestamp: new Date(),
                    label: f.properties?.${labelField} ?? f.properties?.name ?? undefined,
                    properties: { ...f.properties, _geometryType: f.geometry?.type },
                };
            });
        }
    }

    destroy() { this._context = null; this._entities = []; }
    async fetch(_timeRange) { return this._entities; }
    getPollingInterval() { return 0; }

    getLayerConfig() {
        return {
            color: ${JSON.stringify(color)},
            clusterEnabled: ${clusterEnabled},
            clusterDistance: ${clusterDistance},
            maxEntities: ${maxEntities},
        };
    }

    renderEntity(_entity) {${renderBlock}
    }
}
`;
}
